/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230309-3","meetingId":"r05-c-budget","date":"2023年3月9日","dateIso":"2023-03-09","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年度品川区一般会計予算","agenda":"令和５年度品川区一般会計予算","exchanges":[{"speaker":"江野下委員","kind":"質問・要望","question":"おはようあります。本日も１日どうぞよろしくお願いいたします。伴走型として町会に寄り添った支援をしていただくには１年間では非常に短く、参加した町会に何か新しい成果や成功事例ができるまで継続していただきたく、３月５日のあるデジタル新聞では、「曲がり角の自治会・町内会担い手不足、加入減、地域を支えるには」との見出しの記事もありますので要望しますが、いかがでしょうか。","respondent":"川島地域活動課長","answer":"今のお話にございました継続的な何年にもわたっての支援ですが、課題の中身によっては単年度では成果が出しにくいものもあると考えられますので、一律に支援を１年限りというふうにするということではなく、来年度の募集の際には。","id":"exchange-001"},{"speaker":"江野下委員","kind":"提案","question":"続けて、１９１ページのコンテナ型喫煙所設置についてお伺いします。その数何と約１２０万本。そこでお伺いします。計画がないのであれば、武蔵小山商店街に限らず、青物横丁駅などコンテナ型喫煙所を設置できるスペースがない駅の近隣商店街など、民間企業やＪＴ（日本たばこ産業）にもご協力いただいて、空き店舗を利用した喫煙所の設置などを提案しますが、いかがでしょうか。","respondent":"森田生活安全担当課長","answer":"それにつきましてはホームページに掲載をしたところですが、コンテナ型の計画につきまして、武蔵小山ですが、今様々検討を進めているところでございまして、以前にも少しご説明した機会がありますが、なかなかコンテナといいますとスペースが必要であるということと。","id":"exchange-002"},{"speaker":"江野下委員","kind":"提案","question":"そうですよね。なかなか契約の問題で、空き店舗、事業系で言うと大体５年ですか。午後８時以降の利用ができると喫煙者にとっても喜ばれるのではないかと思い、そこで提案というか、マイナンバーカードを利用して出入りができるよう、マイナンバーカードだけでなくてもいいのですけれども、促進にもつながりますし、提案、要望として、私の質問を終わらせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは、１８７ページ、八潮地区まちづくり事業。２０７ページ、戸籍事務費。時間がありましたら、２０３ページのしながわ中央公園ボルダリング場運営についてお伺いをいたします。所管は違いますけれども、この八潮みらい懇談会、この八潮地域のまちづくりの中で検討を進めていく中で、ぜひ所管課とも検討していただきながら、この団地への設置も進めていただきたいと思いますが、併せて見解を伺います。","respondent":"中西八潮まちづくり担当課長","answer":"担当所管とも連携を密にしまして、よりよい施設、よりよいまちとなりますよう、私のほうでも努めてまいりたいと思います。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ具体的に進めていただきたいと思いますので、よろしくお願いいたします。続いて、戸籍事務費のおくやみコーナーとマイナンバーカード普及促進、併せてお伺いをいたします。本定例会の代表質問で、おくやみコーナーの現庁舎での設置を改めて求めた際に、できるだけ早期の実現を目指すとのご答弁がありました。その方の支援を何か検討されているのか、お伺いをいたします。","respondent":"吉野戸籍住民課長","answer":"先行区の事例を参考にしながら進めていきたいと考えております。それから、パンフレットなのですけれども、こちらのほうは修正等がありましたら、そのたびに鋭意修正を行っているところです。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこをもう一歩、区としてできる取組をぜひ検討いただきたいと思いますので、よろしくお願いをいたします。そのときに、できたらそこのボルダリング場を活用して品川区の大会を開催していただきたいと要望させていただいた経緯がありますが、このしながわ中央公園にできるボルダリング場を活用して、ぜひ子どもたちのボルダリングの大会を品川区主催で開催をしていただきたいと思いますが、見解を伺います。","respondent":"吉野戸籍住民課長、辻スポーツ推進課長","answer":"こちらのＭａａＳなのですけれども、申請が困難な方のところに車で行ったりとか、もしくは商業施設に行ったりとか、そういった機動性を有効活用しながらいろいろと検討していきたいと考えております。しながわ中央公園にできるボルダリング場についてのお尋ねです。こちらは、大きさは、幅が１２メートル、定員が１２名ということで、当面は月１回の初心者講習会を開く予定にはしております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"１８３ページ、広町事業検討費について伺います。そもそも広町事業とあるのですが、広町事業という言い方はあるようでなかったと思うのですが、組織改正で新年度には広町事業担当も新設されると。広町事業の範囲はどこか伺います。これまでのＪＲ大井町・広町地区の範囲を指すのか、それとも中小企業センターのあるしながわ中央公園、下神明駅までの二葉の地域も指しているものなのか伺います。","respondent":"山下新庁舎整備課長","answer":"こちらにおける所掌ということですけれども、今実際に広町の開発が進められている中で、このたび庁舎広町跡地一帯、周辺敷地一帯の検討を進めていくということでお示ししておりますので、区有財産の部分を含めて広い検討が必要なものと考えています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"広いということなのですけれども、中小企業センターのしながわ中央公園や下神明駅の二葉も含まれているのかと伺いましたので、後で教えてください。伺いますけれども、区民の財産である区有地、庁舎跡地でなぜ収益を上げなくてはいけないのか伺います。収益性を追求するのではなく、区民の望む活用、区長の言葉を借りれば公共性に集中して追求すべきではないのか伺います。いかがでしょうか。","respondent":"山下新庁舎整備課長","answer":"さきの本会議等でもご答弁申し上げておりますとおり、広域な検討と言ったときに、実際には本庁舎、また第二庁舎、その周辺というところで、しながわ中央公園等が実際に所在をしておりますので、そういったところはやはり含んだ検討が今後必要になっていくものと捉えております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"第二庁舎は平成６年、１９９４年竣工なので、築年数は２８年余だと思いますが、あと何年ぐらいもつ建物なのでしょうか。建設費用は幾らだったのでしょうか。防災施設ということで起債を認められたと伺っておりますが、まだ使えるのに壊しても構わないのか、それとも縛りなどはあるのか、それぞれ伺います。","respondent":"山下新庁舎整備課長","answer":"他方で、今ご紹介がございましたとおり平成６年の竣工というところでは、一般的な庁舎という建物の構造の中で、５０年程度は使うようにもともとの段階では想定して建設をしていたものと認識しています。","id":"exchange-009"},{"speaker":"安藤委員","kind":"提案","question":"２０年もつということですね。区は現時点では、第二庁舎を壊すとも壊さないとも言いません。これからの検討だと言います。この手法ですと、参入民間企業からこれを更地にしてほしいと提案されれば、区は更地にするのではないかと思うのです。結局第二庁舎の今後というのは、連携相手の民間企業の考え方次第ということになるのではないでしょうか。伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"アンケートでしたり、ワークショップでしたり、また今のところ仮称ではありますけれども、跡地検討委員会のようなものを設置しまして、区民の意見を聞きながら進めていくということで方針としてお示ししていますので。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"懸念は全く払拭されないのですけれども、結局は連携相手の民間企業というのはいかに収益を上げるかが第一なのです。これは別に悪いというか、企業というのはそういうものなのです。庁舎や庁舎跡地は区民の財産です。活用の大きな方向性は区や民間企業で決め、区民の意向はその補完程度というのは違うのではないでしょうか。その活用は区民の声を聞いて、一から検討すべきではないのか伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"そういった意味では、今委員のご発言の中にあったような区民の意見を聞きながら、これから進めていくというところですので、今現在新庁舎整備費の中におかれまして、広町の部門を新たに設置していく中で、新たな担当の下で検討を進めていくものと考えています。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"この広町で４０階を建てろとは言いませんけれども、何も官民連携手法をとらなくても、区が単独事業でその全てを公共的な用途に使えば、例えば足りない区民要望の強い特養ホーム、障害者施設、区営住宅、巨大アリーナでなく区民が使えるスポーツ施設などに充てれば、より区民の願いに応えることができると思います。真っすぐ区民要望のための検討を、区民を入れて一から行うよう求めますが、いかがでしょうか。","respondent":"山下新庁舎整備課長","answer":"区のほうで今後進めていくものは、区民の目線に立って区のために取り組んでいくものですので、今後、区民の意見を聞きながら丁寧に進めていきたいと考えています。","id":"exchange-012"},{"speaker":"松永委員","kind":"質問・要望","question":"よろしくお願いします。私からは１８７ページ、町会ホームページ運営支援等について。時間がありましたら、１９３ページのハタチの龍馬ＰＲ事業について伺います。初めに、１８７ページの町会ホームページ運営支援等について伺いたいと思います。様々な事業がありますが、本区ではこの町会・自治会のホームページ作成支援も一生懸命やられると思うのですが、この予算の配分について伺いたいと思います。","respondent":"川島地域活動課長","answer":"ホームページの作成支援につきましては、こちらは先ほどもご紹介のありました町会・自治会ＷＥＢかわら版ではなくて、町会・自治会のホームページの作成、それからメンテナンスのほうを支援するという形になっておりまして。","id":"exchange-013"},{"speaker":"松永委員","kind":"確認","question":"ホームページを作るときにこの値段でできるのかなと考えています。そこで、このホームページの内容を確認したところ、個性のあるホームページもあり様々でございました。これはどのような仕組みになっているのでしょうか。今後町会・自治会からホームページを作りたいと思われるところもあるかもしれませんが、そうした町会・自治会の方々に対してはどのように進めていかれるのでしょうか。","respondent":"川島地域活動課長","answer":"独自支援につきましては、今回明治大学のほうはサーバーを借りている関係で容量が限られていたりとか、それから表現力のほうでもしかすると少し物足りないと感じる方もいるかもしれませんので、ということで、独自にあえて作っていらっしゃる町会もあるのかなと認識しています。","id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"２０１町会・自治会がある中で、まだ４０町会強しかないということで、ぜひ進めていただければと思います。明治大学にお願いしていることは理解させていただきました。例えば自分たちの町会の行事とか、イベントがありますよとか、そうした画像などの掲載といったところは明治大学に投げるのか、それとも自分たちの町会で更新しないといけないのか、そのことについて伺いたいと思います。","respondent":"川島地域活動課長","answer":"ホームページの更新につきましては、それぞれの町会でやっていただくということで、それがなかなかハードルが高く、ホームページは作ったのですけれどもなかなか更新されないというところも幾つかあるということで、大きな課題の一つだと認識しています。","id":"exchange-015"},{"speaker":"松永委員","kind":"質問","question":"そして今後についてなのですが、町会・自治会に対して、ホームページ作成など、様々な支援をされているのですけれども、ここ３年間の町会・自治会の加入率の推移を教えていただければと思います。","respondent":"川島地域活動課長","answer":"町会・自治会への加入率の推移ですが、過去３年間ということで申しますと、令和２年度が５８.３４％、令和３年度が６０.００％、令和４年度が５７.９３％ということでほぼ横ばい、少し減っている状況です。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"ぜひこうした方々に、町会・自治会に加入してほしいということで、町会・自治会加入促進支援を活用し、例えば独自の手ぬぐいや帽子、ジャンパーを加入者に対してお渡ししてもよろしいのでしょうか。加入しなくても、その場で例えばその手ぬぐいとかをお渡ししてもよろしいのか、この事業について少しお伺いしたいと思います。","respondent":"川島地域活動課長","answer":"イベントに参加していただいて物を配って当然問題はないということで、ただ、イベント実施に当たっては、町会の加入とか未加入ということで対応が変わるようなことがないようにしていただくのはお願いしています。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問・要望","question":"今後、政府も３月１３日にはマスクの着用を個人の判断に任せるという発表がありましたが、まだまだ油断はできないと考えています。要望で終わります。こうした高齢者をだます事件が後を絶ちません。ここ３年で起きた品川区の被害額はどのようになっているのでしょうか。減少傾向にあるのでしょうか、お知らせください。この事業によって未然に防げたことがあったのか、併せて伺います。","respondent":"森田生活安全担当課長","answer":"この自動通話録音機において被害を未然に防いだことがあるかというお話ですが、この自動通話録音機とＡＩ型特殊詐欺対策アダプタはまた別でございまして、ＡＩ型特殊詐欺対策アダプタにつきましては、令和４年１月に私どもで補助金を使って設置をさせていただいたお宅において。","id":"exchange-018"},{"speaker":"澤田委員","kind":"質問・要望","question":"私からは、１６７ページ、区施設営繕事務費、区有施設改修工事設計等委託。この３つについてお伺いしたいと考えています。１６７ページの区施設営繕事務費、区有施設改修工事設計等委託についてお伺いします。ですので、新庁舎にこのテレビ電話が搭載されたエレベーターをぜひ採用していただきたいという要望もあるのですが、まずは現在のエレベーターの状況をお伺いしたいと思います。お知らせください。","respondent":"小林施設整備課長、東野経理課長、大友新庁舎建設担当課長","answer":"エレベーターの台数ですが、約２００を超える区の施設がありますが、そのうちの１００程度の施設につきまして、エレベーターが設置されている状況です。例えば非常用のボタンもございまして、そこで音声でのやり取り、警備室とのやり取りなどもできるようになっておりますので、そういったところで。障害者の方への対応を目的とした設備の導入につきましては、委員からのご提案の設備も含め広く情報を収集しまして。","id":"exchange-019"},{"speaker":"澤田委員","kind":"質問・要望","question":"要望で終わります。続きまして、１７５ページ、国際交流推進事業、大使館ほか交流事業経費。１９５ページ、外国人観光客誘致事業につきましてお伺いいたします。５月には国の方針として新型コロナが５類へ引き下げられることが決定したことを踏まえ、今年度の国際交流では新たな事業などは考えていらっしゃるのでしょうか。区の考えをお知らせください。","respondent":"古巻総務課長","answer":"大使館を含めまして、国際交流は、コロナ禍で大分縮小してしまったというような残念な状況ではございましたけれども、来年度につきましては、オークランド市との交流の３０周年の事業ということで、オークランド市への派遣を考えております。","id":"exchange-020"},{"speaker":"澤田委員","kind":"質問","question":"ぜひコロナ禍以前のように活発に取り組んでいただいて、以前のように進んでいくとよいと考えています。それらバラエティに富んだ大使館等と連携し、２０２１年に開催されたパラリンピック教育の一環として行われた世界ともだちプロジェクトは大変意義のある取組だと思いましたが、パラリンピックとともに終わってしまったのでしょうか。現在もそちらのほうは行われているのでしょうか、お知らせください。","respondent":"古巻総務課長","answer":"世界ともだちプロジェクトに関してですけれども、東京都の事業という認識をしておりまして、学校のほうで主に事業をされているですので、総務課からのお答えはなかなか難しいところがありますけれども。","id":"exchange-021"},{"speaker":"澤田委員","kind":"質問・要望","question":"子どもたちにとって貴重な体験であるグローバル給食事業は、ぜひ引き続き行っていただきたいとともに、そのグローバル事業をさらに進化し、楽しみながら行える食を通じた異文化交流の取組の一環として、各国の大使館などと連携をより強化し、また品川区在住の在日外国人の方々も巻き込み、世界の料理や文化を紹介し提供するイベントやフェスティバルなどを行うというのはいかがでしょうか。","respondent":"古巻総務課長","answer":"直ちにどういった形でというのはなかなかお答えしづらい部分もありますけれども、様々に工夫して国際交流が進むように事業を進めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ進めていただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"いながき委員","kind":"質問","question":"２０９ページ、マイナンバーカード普及促進についてお尋ねをします。そこで、大きく３点質問いたします。補正予算の折、人権啓発課も早急にホームページ等で対応してくださるとのことでしたが、その後どうなっていますでしょうか。ＤＶ相談の窓口に相談に来られた方へのアナウンスはどのようになっているのか、併せて伺います。その後、国、総務省か厚労省かデジタル庁などからお知らせはあったのでしょうか。","respondent":"加島人権啓発課長、吉野戸籍住民課長","answer":"２点目のＤＶ相談のところでの説明なのですけれども、今現在ＤＶ相談を委託で行っておりますので、相談者のほうと情報を共有して、必要に応じてご案内できるよう図ってまいりたいと考えております。ここから大分時間がたっておりましたのと、委員のご指摘もありましたので、ホームページのほうに改めて載せさせていただいたところです。これからも丁寧に対応していきたいと考えております。","id":"exchange-024"},{"speaker":"いながき委員","kind":"質問・要望","question":"ほかの部署も上げてはいただいたのですけれども、たどり着くのがすごく深くて難しかったので、そこも改善をお願いしたいと思います。せめてホームページのトップページに持ってくるなど、より強い注意喚起をお願いしたいと思います。なぜなら、これは人の命に関わる問題なのです。なので、ぜひとも丁寧に進めてほしいと思います。改めて、品川区の見解を伺います。","respondent":"吉野戸籍住民課長","answer":"引き続きこの対応は続けたいと考えています。かつ、やはり何か漏れとかそういったものがあると重大な事件につながってしまいますので、マイナポータルとかのそういった仕様をもう一度確認しまして、何か漏れがないかどうかというところも今鋭意確認しているところです。","id":"exchange-025"},{"speaker":"いながき委員","kind":"質問","question":"新庁舎のことをお尋ねします。今さらと思われるかもしれませんけれども、そもそもなぜ新庁舎を建てるにあたって、大井町の駅に近い場所に建てようということにはならなかったのでしょうか。以上を踏まえ質問します。新庁舎を建てるにあたり、大井町駅近くの土地に建てないと判断した理由は何でしょうか。第二庁舎の活用を急遽変更したその理由は何でしょうか。詳しい経緯を伺います。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"先ほど駅前の土地という形でご提示されたところにつきましては新たな都市機能集積ゾーンという場所になっておりまして、このまちづくり方針に基づいて、新庁舎の建設予定地という形で計画しているものです。やはり区民への説明はしっかりしてほしいということは、委員長からも私どもも事を預かっておりまして、また１０月の策定委員会だったかと思いますけれども、設計の段階におきまして区民への説明がやはりされていかないのは。","id":"exchange-026"},{"speaker":"いながき委員","kind":"質問・要望","question":"お知らせの経緯は分かりました。検討の経緯を伺っています。重複のない答弁でお願いします。検討の経緯をお知らせください。区として換地の際に、駅近くの土地にしてほしいという要望が出されたのでしょうか。お願いします。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"検討の経緯ということで、先ほどご質問いただいた内容と同じ内容でのご質問なので、同じことの繰り返しにはなってしまうのですけれども、ご答申いただきましてから、項目の整理ですとか文言の調整といったことに複数回臨みまして。土地の再編につきまして区民のご意見というところにつきましては、令和３年３月に開催しております広町地区の説明会であったり、その後同年の９月に開催している都市計画案の説明の中で丁寧な説明をしていると認識しております。","id":"exchange-027"},{"speaker":"いながき委員","kind":"質問・要望","question":"すみません。区として換地の際の要望をされたのかというお尋ねをしましたけれども、それのお答えがなかったので、次の機会にそれは詳しくお尋ねをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"しながわ」でやっていくのでしょうか。これは情報の管理、個人情報の管理というのは徹底していただきたいのですけれども、どうなっているか教えてください。２０７ページ、戸籍事務費なのですけれども、戸籍も民間委託を戸籍住民課でしていると思うのですけれども、ここも個人情報を扱っていると思うのですけれども、情報の管理を徹底していただきたいと思うのですけれども、お伺いします。","respondent":"大澤広報広聴課長、宮澤情報推進課長、吉野戸籍住民課長","answer":"変更の必要性や、またその時期や方法につきましては今後検討してまいります。日々の運用に関しても、システムを扱う委託先の職員の方の氏名報告をいただきまして、その方の生体認証をした上で。戸籍住民課の窓口なのですけれども、こちらも委託事業者の方が対応しております。こちらの委託事業者なのですけれども、プロポーザルで選定いたしました。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"この「わ！しながわ」に関しては、決算特別委員会のときも私が伺いました。広報広聴課長に個人的な感想は述べませんという答弁をいただいたので、私の個人的感想、全然どこへ行っても「わ！どうしても私は分からないのです。けれども、これだけ個人情報が大事だという今の時代に、まさに時宜にかなってない方法といいますかシステムだと私は思うのですけれども、その辺についてはいかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"政治や社会生活に関して公的な調査として必要な場合。この３つの項目が、限定的に選挙人名簿の閲覧として認められているものです。なので、それ以外の方が一般的に名簿を閲覧して個人情報を見るということはできないという規定があります。","id":"exchange-030"},{"speaker":"藤原委員","kind":"確認","question":"しかし、それを選挙管理委員会としては確認しないではないですか。していたら別ですよ。その後確認しないのだから。そういうところが出ているのですから、ぜひ選挙管理委員会で、もう今日何個も私は投げかけたので、こういう話を選挙管理委員会でしていただければ、あのような１時間とか２時間とか週何回とか月何回とか、回数はこのようなものでは済まないと思います。その辺については、いかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただしご指摘のとおり、法の規定が定められたのも大分昔ですので、それが現在の個人情報保護の観点からどうかというところは、残念ながら区で対応できるところでありませんので、機会があるところで国や都にそういう話はしたいと考えます。","id":"exchange-031"},{"speaker":"藤原委員","kind":"確認","question":"質問しているわけですから、よろしくお願いします。次に、１９１ページ、歩行喫煙防止、生活安全についてお伺いしますけれども、生活安全担当課長、これは何回も質問しましたけれども、品川区に歩行喫煙等の条例があるわけですね。だから、私は自動販売機の横にはごみ箱を設置してほしいというお願いをしたのですけれども、課長、これは２年たっても全然変わっていないではないですか。確認です。","respondent":"森田生活安全担当課長","answer":"個々の事案につきましては、個々に対応させていただいているところです。委員のご心配のようにまちでごみが増えないような、そういったところでは注意しながらやっていきたいと考えています。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、条例は条例、仕事はバランスですから、グッズづくりはグッズづくり、そして、もう今２年していただいてこういう思いはいろいろあると思うのですけれども、もしも警視庁にまた戻ることがあったときには、私はこの品川区で仕事をしたことをキャリアにして、今度は東京都、警視庁という意味で力を発揮していっていただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"森田生活安全担当課長","answer":"そういった面では、一緒にこのように仕事をさせていただいた皆様のお力なども力に蓄えた上で、警視庁に戻っても仕事をさせていただきたいと考えていますが、まだ終わってはおりませんので、一生懸命引き続きやらせていただきます。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"次、１７８ページ、人事管理費なのですけれども、今出ている役職定年についてお伺いしますが、部長職でも役職定年になると課長補佐になってしまうのですね。","respondent":"崎村人事課長","answer":"委員のお話のとおり、部長職、課長職問わず管理職から外れるということで、課長補佐以下に降任するということになります。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"そうすると、今、部長職はウッドの机ですけれども、あれも変わってしまうということですね。つまりどうやってモチベーションを保っていくかということですね。人事として保っていくかということだと思うのです。そして、この人事院勧告というのですか、古いですね。それをまた始めるというのは遅いと思うのですけれども、その辺についてはいかがだと思いますか。","respondent":"崎村人事課長","answer":"今後については、役職定年制の導入は来年度から開始となりますけれども、こちらも社会一般の情勢を踏まえて、今後導入してどうなっていくのかというのを見ながら、こちらの制度については考えていく必要があるのではないかと捉えております。","id":"exchange-035"},{"speaker":"藤原委員","kind":"意見","question":"都営地下鉄に乗ると、東京都から同一賃金同一労働を進めますと言う。何か人事院勧告というのはおかしいですよね。同一労働しているのに同一賃金にはならない。７割になってしまう。その辺考えていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"松本委員","kind":"確認","question":"私からは、１８２ページ、新庁舎整備費。１９１ページ、青少年健全育成事業。１７７ページ、特別職報酬等審議会経費について伺います。その中で、あたかも大企業のもうけ主義という話が出てきたのですけれども、確認をしておきたいのですが、この官民連携、公民連携という言葉はよくあります。あるいはＮＰＯとか市民団体とか、あるいは地域の団体が入ってくるのか、その点をお伺いしたいと思います。","respondent":"山下新庁舎整備課長","answer":"実際に建物を建てる、また建物を運営するということになりますと、一定の能力でしたり一定の知見がある事業者というところが一般には想起されるところとは思いますけれども、今の委員のご紹介のあった例えばＮＰＯ団体がその相手方になり得ないかというところにつきましては。","id":"exchange-037"},{"speaker":"松本委員","kind":"意見","question":"やはり相手方も、では１社というか特定の企業が入っていくわけではなくて、その中でコンソーシアムを組んだり、いろいろやり方はあると思います。その中に、地域団体あるいはＮＰＯが入っていく。これはそのように品川区がやっていると言いたいのではなくて、そのように自治体のほうでもうほぼ特に聞かなくてもやっていくようなことが可能なのか不可能なのか、お願いいたします。","respondent":"山下新庁舎整備課長","answer":"今回予算としてご提案申し上げている点としましては、まず現庁舎跡地等の活用の検討ということで、区民の意見を聞きながら、どういった形でどういったものが区民ニーズにかなっていくのかというところの検討ですので。","id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"私が伺ったのが、進め方として、区民の声を聞かないやり方というのが一般論として可能か不可能かというお話を聞きまして、多分法律上いろいろと制約があると思うのですけれども、やろうと思えば、例えば自治体のトップの独断でどんどん進めていくということは従来方式でも可能ではないかと思います。これからそのようにやっていくかというところではなくて、そういうことが可能なのかどうか伺います。","respondent":"山下新庁舎整備課長","answer":"実際に財政負担が生じるという部分についてはご指摘のとおりでございまして、そういった中で、庁舎跡地の一体的な検討を進めることで、新庁舎整備において区民負担の軽減を、新庁舎の建設を契機として進めていくということで、大きな柱としてお示しをしているものですので、今後。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問・要望","question":"さらに加えて区民の声を聞きながらやっていくというところ。これはもう首長、区長にリーダーシップを取っていただきながらやっていただきたいと思います。次に、青少年健全育成事業について伺います。この調査については、所管が地域活動課というところなのでここでお伺いしたいのですけれども、まずこの調査というのはどういう具体的な調査なのかと、これをどのように活用しているのか、お伺いいたします。","respondent":"川島地域活動課長","answer":"こちらの地域環境実態調査ということで、今お話にございましたとおり、青少年を取り巻く健全育成の観点からの地域の調査ということで、６月から９月にかけまして各地区の地区委員が地域の中を回って調査結果をまとめまして。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"調査の内容は分かりました。パブリックコメントの集計を経て、このパブリックコメントの集計は特に図書類の部分については、東京都の青少年健全育成条例に合わせていただいたのだなと思うのですけれども、一方でこの看板・ポスターです。その中で、区としてやっていることの中で、この看板とかポスターと掲げられているのですけれども、これはどういう法令の根拠に基づいてやられているのか伺います。","respondent":"川島地域活動課長","answer":"こちらの調査の中身につきましては、何が根拠かと言われますと、その目的としては東京都の青少年の健全な育成に関する条例の、この条例は青少年の環境の整備を助長するとともにといったところになりますので、その目的を根拠としておりますが。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問・要望","question":"そのように考えていくと、この青少年の健全性を考えていく上では、こういった調査をやったりしていくよりも、もっとほかの分野にお金を投資していただきたいと考えていて、この事業についてはもう見直しの時期に来ているのではないかと思いますが、いかがでしょうか。","respondent":"川島地域活動課長","answer":"それから紙媒体につきましては、環境がかなりよくなっているということで、地区委員会連合会の役員の皆様とお話ししましても、そろそろこの辺の在り方を変えるべきではないかという話も聞いてございましたので、私どもとしましても。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"ぜひ地域活動課としても、そこの部分は地区委員会連合会の役員の皆様にお伝えいただいて、見直しになるようにお願いしたいと思います。次に、二十歳の集い式典経費について伺いたいのですけれども、こちらは令和３年度と令和４年度は大体予算が８００万円程度だったのですけれども、来年度の予算を見ると９００万円を超えていて１００万円以上の増額になっています。ここはどうして増額になったのか伺います。","respondent":"古巻総務課長","answer":"来年につきましてはきゅりあんでの実施を予定しておりますけれども、きゅりあん周辺は商業施設等が大変多くて、商業施設のほうからも終了後の様々な人の行き来の関係でご意見等をいただいているところですので、会場警備費を２０万円ほど余分にかかるような形での状況ですのと。","id":"exchange-043"},{"speaker":"松本委員","kind":"質問・要望","question":"今おっしゃった内容は納得できましたので、この部分は引き続き精査していただきたいというところで終わりたいと思います。そういう方たちがいらっしゃったときに、私たちの団体も品川区のために頑張っているし、区長とも話がしたいので、参加したいですといったときに、そういう呼ばれていない人たちがこの新年賀詞交歓会に参加することができるのか、伺いたいと思います。","respondent":"古巻総務課長","answer":"なので、飛び入りでという形になるとなかなか整理がつかないという部分もありますので、そこはなかなか難しいのかなと考えているところです。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"そうやって考えると、やはり区がある意味選んだ人たちに対して、アルコールとか食べ物を提供していたということになると思います。ここ数年のやり方はそれでよかったと思うのですけれども、予算を見ると、コロナ禍前と大体予算が一緒の額が計上されているので、そうするとまた来年度以降、アルコールを提供するのかとも思えるのですが、ここは提供される想定で予算を組まれているのでしょうか。","respondent":"古巻総務課長","answer":"予算編成上の想定につきましては、従来の形、コロナのある程度の落ち着きというようなところを踏まえた予算の編成をさせていただいているところですけれども、やり方につきましては、このコロナ禍で一度中止をせざるを得なかったということはありますけれども、やり方。","id":"exchange-045"},{"speaker":"松本委員","kind":"質問・要望","question":"このやり方は本当にいろいろ考えていただきたくて、これまでもこの新年賀詞交歓会は会員制にしたらどうかというような議論も出ていたかと思います。新年賀詞交歓会、名前は別にいいですけれども、区が選んだ方たちに参加していただくのではなくて、区長と交流したい方たちが参加して区長と交流して意見交換ができる。そういう場というのをつくっていただきたいと思いますが、ご意見を伺えればと思います。","respondent":"古巻総務課長","answer":"進め方等については様々検討はしたいと思います。","id":"exchange-046"},{"speaker":"西村委員","kind":"提案","question":"１９５ページ、インバウンド向け整備・ＰＲ事業、１７７ページ、早川町との交流事業を伺ってまいります。コロナで３年がたち、アフターコロナに向けて、インバウンドが戻ってくると思いますので、区としても、以前のようなまちでの体験型観光を強化する提案を幾つかします。ツールや取組をがっちりと連携させることが重要と考えますが、現在の取組と区の考えを伺います。","respondent":"山崎文化スポーツ振興部長","answer":"様々、まだまだ品川区には、この伝統工芸のすてきな方々もいますので、そうした魅力を最大限活用しながら取り組んでまいりたいなと考えているところです。","id":"exchange-047"},{"speaker":"西村委員","kind":"提案","question":"店情報、体験情報、コインランドリー施設などを外国人向けに案内するホームページやチラシを製作しまして、近隣ホテルとがっちり連携をしていただきたいと考えています。次に、小規模、５０から１００名くらい単位のＭＩＣＥの積極的な受入れを提案します。品川区での検討はいかがでしょうか。広がりの考えがあればお聞かせください。ご見解をお聞かせください。","respondent":"山崎文化スポーツ振興部長","answer":"そのようなところもありますので、先ほど来の体験なども含めて、そうした小規模ＭＩＣＥというのですか、商用のミーティングの中に区の魅力をはめ込んでいくような考え方、これは１つありかなと思っているところです。","id":"exchange-048"},{"speaker":"西村委員","kind":"提案","question":"まさに間伐材なのですけれども、マウントしながわの里山づくりを活かしていただきまして、森の木で子どもたちが作ったキーホルダーをエコルとごしで展示するですとか、森林環境譲与税を使った取組もできればとご提案差し上げたいところです。昨年私が品川区のキャンプ場開放事業に参加をさせていただいたのですが、１０倍以上か、相当な倍率だったと伺っています。ぜひご検討をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"横山委員","kind":"質問・要望","question":"１点目に男女共同参画推進事業についてお伺いいたします。区として、性的マイノリティ当事者に対して、今まで以上に寄り添った対応が必要になると考えますので、ＬＧＢＴＱ ＬＩＮＥ相談などのＳＮＳ相談をなるべく早急に実施していただきたいと要望いたしますが、区のお考えをお聞かせください。２点目に全庁共通プロジェクト推進経費、広聴関連経費についてお伺いいたします。それぞれ教えてください。","respondent":"加島人権啓発課長、佐藤企画調整課長、大澤広報広聴課長","answer":"私からは、ＳＮＳ相談のご質問についてお答えいたします。区では、男女共同参画センターにおきまして、カウンセリング相談を実施しております。２点目の、こういったツールの見解、どのように捉えているかですが、オンライン上で意見を出すだけではなく。インターネットが普及しているためと考えられますが、そのような中で、今後どのようなやり方が時代に合った適切な方法で。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目に行きます。大学の理念には地域活動との連動という部分があるかと思いますが、例えば初めから地域で活動したいといった、比較的モチベーションの高い区民の方々には、年齢制限を緩めたり、そのような方々に向けた広報をしたり、シニアライフを楽しみたい方向けには、１段ずつのステップを踏んでいけるような講座設計を要望いたします。４点目に監査委員費、住民監査請求についてお伺いをいたします。","respondent":"山崎文化スポーツ振興部長、高山監査委員事務局長","answer":"委員おっしゃったステップアップも含めて、踏んでいっていただけるように、さらなる検討をしてまいりたいと考えているところです。お尋ねの同趣旨の請求が繰り返し行われた場合の対応につきましては、個別の対応ということにはなってまいりますが、一般的には、要件が整った請求につきましては、それぞれ独立した１件の請求として受付をしまして。","id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"監査委員費、住民監査請求のところにつきましては、こちら大変な作業をしていただいているのだろうなというようなことが確認できました。効率的な運営とともに、また、大切な権利であるということは踏まえた上で、ぜひ効率的に、また監査のお仕事がさらに進めやすいように、強化していけるようにというところで進めていっていただきたいと思いますので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、２０９ページ、マイナンバーカード普及促進から行政ＭａａＳ、２０７ページ、マルチコピー機、マイナンバーカードの区独自の活用メリット等について伺っていきます。昨年、マイナンバーカードの普及促進を求めまして、第３回定例会一般質問と、それに続く決算特別委員会で質疑を行っておりましたので、それに沿って状況を確認してまいりたいと思います。","respondent":"吉野戸籍住民課長","answer":"令和５年２月末現在の数字になります。申請件数は３３万４,７４４件で、８２.９％になります。それから交付なのですけれども、２４万９,３５８枚で、６１.８％になります。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"確認","question":"昨年１１月の決算特別委員会の段階で、申請率が６９％で約７割、交付率は５３.４％でしたので、この４か月足らずでそれぞれ約１０％上昇したと。全国平均の７５.１％を上回っていることを確認しました。このコラボレーション事業について、品川区のご見解があれば教えてください。","respondent":"吉野戸籍住民課長","answer":"今年度なのですけれども、実施回数は５回になります。申請サポートなのですけれども、全部で２５８件になります。今後も行政書士の方のご尽力をいただけると、申請率などが伸びますので、今後も協力をしていただきたいというところであります。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"４点確認をしたいのですが、まず、車に乗り込んで現地に赴いて手続を行うのは、戸籍住民課などのしかるべき区の職員なのでしょうか。一般質問で、区内の介護施設等の入居施設で希望者への申請会を実施して、申請時に施設で本人確認を実施した上で、交付会場まで赴くことが困難な入居者については、施設長等が責任を持ってカードの交付を受けるような方法の実施を求めました。","respondent":"吉野戸籍住民課長","answer":"マイナポイントなのですけれども、今までも地域センターも含めて、こちらのほうマイナポイントのマイナポータルという機器があるのですが、こちらでの支援をしているところです。こちらも引き続き実施していこうと考えております。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"提案","question":"一番大事なことは、区役所に来なさいということではなくて、あなたの下へ行きますよという、誰１人取り残さないという、品川区役所としてのメッセージにもなるのではないかということで、ラッピングなどをしてしまうと次のステップにこの車が使えなくなってしまうので、何か工夫をして、この車は区民の下に区役所が向かっているのですよ。","respondent":"吉野戸籍住民課長","answer":"第１弾のときも、実は数か月延びたというような経緯もありますので、この辺は国の動向を注視していきます。それから、マルチタスク車両の愛称であったり、ラッピングなどなのですけれども、こちらのほうも関係各課と調整といいますか、検討していきたいと思います。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問","question":"一般質問で、地域センターでカード交付後のマイナポイント付与手続のサポートの実施について、できるということをまだまだご存じない区民がいらっしゃるので、避暑シェルターやワクチンの予約のように、地域センターでマイナポイント付与のお手伝いをしますと記載したのぼり旗等を立ててはいかがですか、区民へのサポートのさらなる周知をしてくださいということをお願いしました。","respondent":"吉野戸籍住民課長","answer":"それから交付金に関しましても、９,４００件のうち４,２００件が、地域センターのほうでこの辺支援していただいておりますので、一定の区民の方への周知も含めて、支援ができているのかなと考えています。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に、前に一般質問のときに、やはりカードを持っているメリットというものは、区独自の利活用の創出が必要ではないかということを要望しました。今回マルチコピー機が導入されるのですけれども、これで他自治体に本籍地がある方でも、品川区、コンビニでも取れるのですが、これも取れるようになるということで、この辺り、今検討状況はどうなっているのか、最後にお伺いします。","respondent":"吉野戸籍住民課長","answer":"今回、コンビニと同じマルチコピー機を導入いたします。これによりまして、窓口の混雑であったり、区民の方の利便性向上のほうに近づけていきたいなと考えている次第です。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ありがとうございました。マイナンバーカードを使って、他自治体に本籍地があったとしても、戸籍謄本、いわゆる戸籍全部事項証明書も取れるということで、それはいいのかなと思います。今後も、ぜひ独自の利活用策を検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"１６７ページの公有地活用検討等に関わって、旧第一日野小学校跡地の活用について質問いたします。この跡地に特別養護老人ホームをつくってほしいという要望は、従来から、住民の皆さんの声として非常に強くあります。区民の財産である学校跡地には、要望の強い特別養護老人ホームを建ててほしいと思いますけれども、いかがでしょうか。伺います。","respondent":"佐藤企画調整課長","answer":"お尋ねの旧第一日野小学校跡地に関しましては、来年度、旧荏原第四中学校でも予定されておりますけれども、区民の方、また、多くの地域の方々の意見を聞いて、そういったものが施設として適しているかというところも聞きながら、しっかりと進めてまいりたいと考えております。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問・要望","question":"そのような検討は、大体、今もう始まっているのでしょうか。今暫定活用ということでやられていますけれども、本格活用ということで、特別養護老人ホームをつくっていただければと思うのですが、本格活用の検討というものはいつからということに、検討あるいは本格活用そのものはいつからということになっているのか、教えていただきたいと思います。","respondent":"佐藤企画調整課長","answer":"最短で令和８年度まで使わせていただきますので、その後、すぐ工事着工しても令和９年度というところになりますと、そこから逆算していくと、来年か再来年ぐらいには、基本設計等々の作業が必要かなというところでございまして、具体的にまだ、本格活用するかどうかも含めて。","id":"exchange-061"},{"speaker":"おくの委員","kind":"質問","question":"その検討自体は、では来年あたりから始まるという感じの理解でよろしいのでしょうか。それともう一つ、その検討事項の中に、特別養護老人ホームも選択肢として入っていると理解しておいてよろしいのでしょうか。伺います。","respondent":"佐藤企画調整課長","answer":"この予算特別委員会のほうにお願いしている予算に関しましては、旧荏原第四中学校というところを外出しして出しているというところで、旧第一日野小学校に関しまして、例えば区民参加型の検討委員会を設置するという予定は来年度はございません。","id":"exchange-062"},{"speaker":"おくの委員","kind":"質問・要望","question":"住民の声を聴きながら検討していくと、今と同様のお答えだったと思うのですけれども、これ区有地という区民の財産の活用ですから、当然住民の声を聴きながら、あるいはそれを反映させてということが必要になってくると思うのですが、跡地の活用の計画の検討、あるいは策定、住民参加で行われるべきだと私は思うのですけれども、この点はいかがでしょうか。","respondent":"佐藤企画調整課長","answer":"跡地の検討に対して、住民参加、区民の声をよく聴いてほしいですが、先ほど来答弁しているとおり、区として区民の声を聴くことは非常に重要だと考えておりますので、当然そういった形で進めていくです。","id":"exchange-063"},{"speaker":"おくの委員","kind":"質問・要望","question":"１日説明会をやったというようなことではなくて、策定委員会といったようなものをつくって継続的に検討したり、あるいは、ワークショップのようなものを地域ごとに行ってみたり、あるいはアンケートを取るとか、とにかく地元住民の方になじみの深い小学校跡地だけに、丁寧にやっていく必要性は高いと思いますけれども、この地元住民の地域要望をどのような方法で把握していこうとお考えになっているのか。","respondent":"佐藤企画調整課長","answer":"どのような形で区民の声を聴いていくのかというところのご質問です。委員からご紹介のあったとおり、ワークショップであったり、アンケートであったり、あとそういったものを集約していくための検討委員会というものも必要になると考えています。","id":"exchange-064"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひとも住民参加ということで、住民の意思が十分に反映するように、ご満足いただけるように、やっていただきたいと思います。高齢者人口はこれからも増え続けると。区の説明でも、特別養護老人ホームをつくれるかどうかということは用地の取得が一番困難で、その用地を確保できるかどうかが一番重要なポイントだと説明されています。ぜひともつくっていただきたいと思いますけれども、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"特別養護老人ホームも含めて、様々な行政ニーズを探りながら検討してまいります。","id":"exchange-065"},{"speaker":"芹澤委員","kind":"質問","question":"学校の入学のお祝いであったり、敬老のお祝いであったりなどを贈ってきたかと思いますが、この町会でやってきた活動の意義を、まずどう捉えていらっしゃるのかということと、あとすみません、私も聞いたばかりであれなのですが、今後、個人情報の観点で、入学者や敬老の方の個人情報というものが、町会に下りてくるのが難しくなるということを、地域で今ご説明されていると伺っているのですけれども。","respondent":"川島地域活動課長","answer":"このたび、令和５年４月１日から個人情報保護法が施行されるということで、扱いのほうも大変厳しくなるということで、区としましても様々検討はしたところではありますが、改正後のほうは法に沿って厳格な扱いになるので。","id":"exchange-066"},{"speaker":"芹澤委員","kind":"質問・要望","question":"一方で、区でできることは引き続き区で模索をしていただきたいなと思っていて、個人情報として直接提供できないのであれば、そのまま個人情報を提供していいですかと同意を取ることはなかなか難しいと思うのですが、例えば保育園の申請時であったりとか、学校の申請のときに、お祝いの品を送っていいですかというようなことは、聞くことは十分可能なのかなと思っていて。","respondent":"川島地域活動課長","answer":"法令遵守というものが我々の大事なところではありますが、今までのやってきたことの目的や、それから意義も含めて、可能性については探っていきたいと考えています。","id":"exchange-067"},{"speaker":"芹澤委員","kind":"提案","question":"それで、例えば今の方法であっても、最終的には区から町会にリストを提供していくということに、今ご提案した方法でもなると思うので、そこに課題があるのか、これから研究していただきたいということと、どうしてもそれが難しいということであれば、やはりそれでも区と町会と地域住民のつながりというものはぜひ支援していただきたいので、例えば入学される方であったり、敬老の方であったりというものは。","respondent":"川島地域活動課長","answer":"やはり、先ほど申したとおりの見解にはなるのですが、同じような形での継続は非常に厳しいというところですけれども、意義のある活動であったということなので、それに類似するようなものが何かないかという部分については探ることはやめずに。","id":"exchange-068"},{"speaker":"芹澤委員","kind":"確認","question":"次に移ります。新年賀詞交歓会についてお伺いをします。これは久しぶりにできて非常によかったなと思っておりまして、まず管理権限のところから確認をしてまいりますが、スクエア荏原で今回やられて、基本的には文化振興事業団が管理されているものなのかなと思うのですけれども、今回は品川区が所有者として建物全体を使ったというような認識でよろしいのでしょうか。","respondent":"古巻総務課長","answer":"スクエア荏原ですけれども、指定管理の施設ということで、文化振興事業団が指定管理者として運営をしている状況です。ですから、区としましては、文化振興事業団のほうから施設の貸出しを受けて使用して、新年賀詞交歓会を実施いたしましたというような形になります。","id":"exchange-069"},{"speaker":"芹澤委員","kind":"質問・要望","question":"もちろん国会議員の方、来賓の方ですから、それは大切に扱っていただきたいという思い、ある程度柔軟に対応していただきたいという思いもありながらも、この新年賀詞交歓会というものは、区政にご協力いただいている皆さんが主役であって、残念ながら国会議員の方々も、お配りされていた区議会議員の方々も、別にそこがお客さんではないと思うので、終わったことですから、今後の対応として。","respondent":"古巻総務課長","answer":"そういった実態があったことにつきましては、把握が十分でなかった部分もありますけれども、確かにあまりふさわしい行為だとは考えられませんので、今後しっかりその辺り、幹事といいましょうか、実施する側として注視、目を光らせてということで。","id":"exchange-070"},{"speaker":"芹澤委員","kind":"意見","question":"私も偶然ながら同じ地域を回っているもので、不思議と聞いている声が大分違って、私の周りでは子育て世帯の方が多いので、特に小学校跡地というところもあって、ぜひあそこには公園をつくってほしいというような声のほうが、圧倒的に私としては多いです。できれば、ドッグランも整備してほしいというようなお声が多くて、特にあそこは高速道路沿いなので、あまり騒音が周りの方も気になっていない。","respondent":"佐藤企画調整課長","answer":"公有地の活用の関係です。基本的に大規模用地は、区にとって貴重な財産であるです。地域の特性や中長期的な行政上の見通しを持って、地域の将来像を見ながら、様々な施設について区民の声を聴いて検討してまいります。","id":"exchange-071"},{"speaker":"せお委員","kind":"質問・要望","question":"事項別説明の予算見積書には、旧荏原第四中学校基本方針策定委員会の報償費も計上されていますが、このプロジェクトは、公有地等活用検討のための策定委員会などの設置運営なども行われるという理解でよろしいでしょうかということの確認が１点と、さらに先日の一般質問でも取り上げましたが、グループホーム整備に係る未利用の公有地の洗い出しに関して。","respondent":"佐藤企画調整課長","answer":"１点目の検討委員会の経費も含まれるのかというところに関しましては、委員ご指摘のとおり、含まれるものです。公有地の活用については、都と調整中の用地や暫定活用中の用地も含めまして、大小様々な用地がありますので、そういった用地の検討をする経費です。","id":"exchange-072"},{"speaker":"せお委員","kind":"質問・要望","question":"旧荏原第四中学校も、当然区民と一緒に活用の検討を進めていくと理解していますので、ここでは要望だけしておきます。コロナ感染拡大もあって、旧リボン旗の台店がワクチン接種会場で、大井町のほうも保健予防課で使用しているというお話は伺いました。特に、旧リボン大井町店は庁舎内ということで、どのような管轄というか、位置づけなのでしょうか。","respondent":"東野経理課長","answer":"今後コロナの終息に向けまして、どういった使い方ができるのかにつきましては、そういった動向を踏まえて検討をしていきたいと考えています。","id":"exchange-073"},{"speaker":"せお委員","kind":"質問・要望","question":"会議室で検討していたというお話なのですけれども、現在は会議室が本当に必要なのかなというところは少しあって、会議は、環境さえ整えば、リモートで可能なのかなというところも思っています。そこで、旧荏原第四中学校ほど広さはない公有地も有効活用できるように、区民の声を何らかの形で広く伺いながら、今後の計画を進めていっていただきたいと考えますが、見解を伺います。","respondent":"佐藤企画調整課長","answer":"区では新時代の品川に向けまして、多様化する区民の価値観やニーズを的確に把握することが非常に重要だと考えております。大規模だけでなく、小規模な用地に関しましても、どういった形で区民の方の声を聴いていくかということも、引き続き積極的に検討してまいりたいと思います。","id":"exchange-074"},{"speaker":"せお委員","kind":"質問・要望","question":"ぜひこの全庁共通プロジェクト、使い方によってはとても有効なプロジェクトだと思っていますので、公有地活用だけではなくて、初めに申し上げましたふるさと納税の検討もそうですし、初日でしたか、ギネスに挑戦というお話もありましたが、そういったところは全庁挙げて検討できるところだと思っていますので、そういった活発な活用をぜひお願いしたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"こんの委員","kind":"質問","question":"地域振興経費ですけれども、これは町会・自治会加入に関することをお伺いしてまいりたいと思います。これまで加入していたマンションや集合住宅が、町会を脱退をしますというようなことがあると伺いました。何かこのようなことに対して、品川区が今取り組んでいること、それからまた、これから取り組もうと、このようなお声に対して取り組もうとされていることがありましたら教えてください。","respondent":"川島地域活動課長","answer":"その後、町会・自治会の活動活性化促進調査というものを実施した中でも、やはり多くの町会の方が、マンションの対策に頭を悩ませているということが分かりまして、これまでと違う何か支援をしなければならないということで、今年度。","id":"exchange-076"},{"speaker":"こんの委員","kind":"質問","question":"区民委員会でも、先日、このマンション管理組合等実態調査の報告がされたということですけれども、今、一部ご紹介がありましたが、いわゆるこの実態調査を基に、これまで、１０年前ぐらいから、今私が申し上げたような課題が、声があったということで進めてきて、半年ですか、伴走支援ということを展開されてきたということですが、この伴走支援をされてどのような効果があったのか、また、どのように町会が。","respondent":"川島地域活動課長","answer":"なかなかこの半年の支援で全て解決するというわけではございませんが、１つの町会におきましては、管理組合と会合を何度か持つことができたというようなところ、それから、住民アンケートを実施しまして、そのマンションの住民の方が何を地域。","id":"exchange-077"},{"speaker":"こんの委員","kind":"質問","question":"私もマンションに住んでいるので、管理組合としてそれぞれ温度差があって、マンションのコミュニティ形成はあると思うのですけれども、一方でそちらもしつつ、町会との接点を、今言ってくださった伴走支援といったところですので、５町会ですか、やってくださったということなので、予算的に５町会だったのだと想像しますが、今後はどれぐらい、これをしていこうと考えていらっしゃるのか、その辺と。","respondent":"川島地域活動課長","answer":"伴走型支援の実施の件数、５町会というものは、来年度はまた同じ数、５町会を支援させていただければと思いますが、その先は支援の広がり等、それから成果のほうも見ながら検討していければと考えています。それから支え愛活動推進委員会というものです。","id":"exchange-078"},{"speaker":"こんの委員","kind":"確認","question":"伴走型支援のほうは、一応５町会を予定されているということと、成果を見ながらということですので、事例集ですか、つくられて、町会の方にも周知をしていくということですので、どうか事例集の中で好事例を皆さんにご紹介しながら、その接点をどう結んでいくかというところの支援を引き続きよろしくお願いいたします。では次の質問に参ります。","respondent":"川島地域活動課長","answer":"１つ、アナログの部分とデジタルの部分と、両方しばらくやるということが結構大変だというお話も聞いてございまして、もう少し先行で実施したところの様子を見する、それから研究をさせていただければと思ってあります。","id":"exchange-079"},{"speaker":"こんの委員","kind":"確認","question":"防犯活動団体支援ですけれども、こちらの地域見守り活動助成金、これは防犯カメラの設置と理解をしておりますが、それでよろしいかどうかの確認と、町会・自治会で防犯カメラを設置されている、これはほぼ１００％、２００町会の自治会、ほぼ１００％設置をされていると想像するのですけれども、その設置状況や、あるいは各町会での設置台数、これで足りるかな。","respondent":"森田生活安全担当課長","answer":"ですが、私どもでも、なかなか進んでいないとか、助成金のやり方が分からないではないだろうかというところにつきましては、こちらから足を向けていきまして、ご説明をさせていただいているところです。","id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"足を運んでくださっているということですけれども、まだまだ、ここにもあそこにもつけたいというようなご要望も受けております。ですから、その助成金は台数が決まってしまっている、いわゆる１台にかかる費用が決まっておりますので、そうなるとつける台数も決まってしまうのかなと思うと、さらに助成金を使うスキームがなっているのか、その辺のところが要望です。何かありましたらお願いします。","respondent":"森田生活安全担当課長","answer":"他の区に比べまして、私どもの助成金のほうは１２分の１１ということで、多く補助をしておりますので、できる限りの助成はして、対応してまいりたいと考えています。","id":"exchange-081"},{"speaker":"松澤委員","kind":"提案","question":"ですから、この効果測定のような調査を実施してきたのだと考えています。こうした結果から、調査報告書の８４ページ、まとめの部分に、今後の支援施策というものが提案されておりました。では、これをどう増やしていくのか、ある程度の計画や方向性があるなら教えていただきたいということと、この伴走型支援というものは、字のごとく共に走っていく。その辺の覚悟をお話しください。","respondent":"川島地域活動課長","answer":"伴走型支援の対象町会数ですが、取りあえず、令和５年度は令和４年度と同じ５町会で実施させていただければと考えています。","id":"exchange-082"},{"speaker":"松澤委員","kind":"質問","question":"例えばこの支援というものが、切るというのは変ですけれども、だんだんと縮小して、町会・自治会のほうで頑張りましょうという話が出たときに、やはりこの町会加入率というものは、何といいますか、行政頼りにしている部分が強いから、そこが弱くなってしまうと加入率が衰退してしまうのか、その辺答えづらいかもしれませんが、その辺の感覚というものを教えてください。","respondent":"川島地域活動課長","answer":"私どもとしましては、こちらいろいろな下支えの支援をしてきて、何とかこうなっているというような認識もありますので、引き続き支援の手を緩めることなく、施策を進めていければと思ってあります。","id":"exchange-083"},{"speaker":"松澤委員","kind":"質問","question":"協働推進についてお聞きいたします。そこで学んだ、ＮＰＯや多様な主体との協働が大変重要であると、そのときの一般質問でも質問させていただきました。区長もおっしゃっております。そこでお聞きいたします。ＮＰＯ法人と区の連携というものは、現在どのような状況になっているのか教えてください。区で活躍するＮＰＯ法人の状況を区はどの程度把握しているのか、２点教えてください。","respondent":"川島地域活動課長","answer":"区内で活動しているＮＰＯ法人の把握に関しましては、区内のＮＰＯ法人の２３１団体に、活動状況のアンケートを２月下旬に郵送したところです。このアンケートで、区との協働を希望する団体についてはヒアリング調査を実施して、行政との連携の推進に努めたいと思ってあります。","id":"exchange-084"},{"speaker":"松澤委員","kind":"質問","question":"知りませんでした。それで、例えばＮＰＯとの連携が随分あるというお話の中で、そういったものを、区民に周知する期間というのですか、広報、例えば町会の好事例というものは先日出していただいたではないですか。そうではなくて、例えばこのような協働の部分でしっかり頑張っていますよという部分をどこかで広報する、そういったことというのは区でやっているのでしょうか。","respondent":"川島地域活動課長","answer":"２月２５日に行われました、しながわ地域貢献活動展という見本市のような形で、活動状況はきゅりあんで発表しておりますが、そういった形で活動の内容を披露する場は設けておりますし、それから活動状況も定期的にご紹介するニュースのようなものを発行しておりますので。","id":"exchange-085"},{"speaker":"松澤委員","kind":"質問","question":"より強いＮＰＯとの連携、そして協働を図りまして、地域課題解決のための一助にしていただきたく、次の質問に移ります。次に、しな助についてお聞きいたします。品川区でレガシーをつなげることはできないかと訴えまして、期間限定ではありますが、延長が決まりまして、もうその期間も近づいてきたと思いますけれども、その間どのような活動が行われてきたのでしょうか。今後の予定を教えてください。","respondent":"辻スポーツ推進課長","answer":"は２０２５年に行われるデフリンピックに向けて、手話の研修というものも行ったところです。来年度同じように、いろいろなボランティアの機会の提供や、そういったネットワークの紹介等を行いつつ、ボランティアに従事していただくというような予定をしております。","id":"exchange-086"},{"speaker":"松澤委員","kind":"質問・要望","question":"ボランティアというものは、基本自分で行うものです。ですから、しな助もオリンピック・パラリンピック、あるいはスポーツ、オリンピックに携わりたいという思いから、相当数の方が集まってくれたのだと考えています。そうするとその方が興味を持って、今サッカーの資格者というものも少ないと聞いています。そういった部分を品川区でぜひフォローしていただきたいと思いますが、ご見解をお聞かせください。","respondent":"辻スポーツ推進課長","answer":"あくまで、やはりボランティアというものは自発的にやるものですので、残っている皆様、今現在６６人いらっしゃるのですけれども、そういった方は、中にはほかのボランティアをもうやられている方もいらっしゃいますので、どのようなことがこれからしたいかということも。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１６７ページの旧荏原第四中学校活用方針検討、２１１ページ、区議会議員選挙執行費に関わって、投票権の保障を求めて質問をします。７０歳以上の方から要望が高いのが特別養護老人ホームです。３０歳以下の方から要望が高いのが保育所です。改めて、特別養護老人ホームや保育所、障害者施設、避難所機能、スポーツ利用など、住民要望に応えた活用を求めます。いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"プレス等でも議会のほうにご報告していますけれども、区民ニーズを踏まえた区有施設の整備の検討というところで、ワークショップを開催したり、基本方針の策定委員会を立ち上げるなど、区民のご意見をお伺いしていろいろと検討していきたいです。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民ニーズを踏まえたということなのですけれども、ぜひ今要望したもの、用途も含めて、検討していっていただきたいと思うのですが、今言われました予算にも１,１００万円盛り込まれ、ワークショップと活用基本方針策定委員会を開催するということで、プレス発表されました。住民参加をしっかり位置づけて、要望を反映することができるものにしていくことが必要です。","respondent":"佐藤企画調整課長","answer":"２点目の検討委員会のメンバーですが、こちらに関しましては、学識経験者２名程度と、今現状の利用状況から見て、スポーツ団体であったり、学校の代表であったり、また障害者団体であったり、当然地域の方々、町会長や町会を代表する方々、あと公募委員も入れて。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"策定委員会のところで、地元の方が何人かちょっと分からなかったですけれども、ぜひ多くの方、地元の方に参加していただいて、その住民要望を反映していっていただきたいと思うのですが、策定委員会でアンケートなどを実施していくことは考えているのか、そこを伺いたいと思います。当然地元の方を中心に公募していくということも考えるべきかなと思うのですが、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"２点ご質問いただきました。１点目のアンケートの実施に関しましては、ちょっと内容があれですけれども、策定委員会の中で参加していただける委員の意見も踏まえながら、どういった形がいいのか、アンケートがいいのか、違う形がいいのかも含めて検討してまいります。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"策定委員会のほうで委員の意見を踏まえてということですので、それも踏まえていただきながら、策定委員会のほうでも、この住民要望を反映できるようにしていっていただきたいと思います。この旧荏原第四中学校跡地のワークショップでも、分野に応じて分科会を設置して検討すべきだと思いますが、いかがでしょうか。","respondent":"佐藤企画調整課長","answer":"分科会設置に関するご質問です、こちらに関しましても、ワークショップで出たご意見の状況や、検討委員会のメンバーの方々のご意見等を踏まえて、検討していきたいと考えております。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたことを踏まえて、住民要望をしっかりと反映した検討を行って、住民に愛される活用をしていっていただきたいと、これは要望しておきたいと思います。次に選挙権、投票権の保障についてです。選挙は民主主義に参加する重要な制度です。体の不自由な人や、投票所に行くことが困難な人、こうした人の投票権を保障することが必要だと思いますが、いかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご質問の、投票に行くために支援が必要な方への対応ということだと思いますが、現在選挙の制度の中で、郵便による投票という制度があります。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問・要望","question":"対応もぜひしていただきたいのですが、私が伺ったのが、区としての認識として、投票権を保障することが必要だと考えているかどうか伺います。","respondent":"鈴木選挙管理委員会事務局長","answer":"選挙管理委員会の大きな職務の１つに、ご指摘の投票権の確保、またはその機会の確保ということがありますので、当然、区の選挙管理委員会としてもそのことは重要に考えております。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"重要だということで、先ほども郵便投票のことをご説明いただきました。その中で、要介護３ぐらいになるとほぼ寝たきりの状態です。そこでまず郵便投票の対象が、今要介護５や、障害に応じてですが、障害者手帳１級から３級などの方ということで、とても限定されています。その対象拡大を国に求めていただきたいと思いますが、いかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"今ご指摘のありました郵便投票の該当の条件ですが、こちらは公職選挙法、また、その関連法令等で定められているものですので、区で裁量を持って変えることはできないものです。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回特に障害者団体の方、障害者の方も投票権を保障するというところで伺いたいのですけれども、障害者団体からもこの要望が出ていると思います。知的障害の方は、１回投票に行ってハードルを感じてしまうと、行けなくなってしまうという特性もあると伺いました。どういった研修などをやっているのか、マニュアルなど作成していくということが必要ではないかと思うのですが、いかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただ、そのときにも、ご指摘にありました研修なり、それからマニュアルなりはしっかりと区のほうで用意したものに沿って、事前に実施をした上で従事するようにということで徹底はしておりますが、その状況によって、もしくは期日前の投票所によっては。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"期日前投票のほうは業者の方がやっているということなので、それはしっかりと対応できるようにしていただきたいと思います。やはりこの投票権を保障するということが必要だと思いますので、よろしくお願いします。ほかにも札幌市がやっている選挙支援カードの配布ですとか、代理投票などできるということも周知していくことが、投票権保障にもなると思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"木村委員","kind":"質問","question":"総務費なのですけれども、総務費は、令和４年度が２４３億７,４００万円余、令和５年度は２６６億９,５３７万円余と、大体２３億２,０００万円ほどの伸びを示していますが、全体的に増えているのかどうか、なぜこの二十何億円が増えたのか、それとも幾つかの事業に集中しているのでしょうか。それもお聞かせをください。","respondent":"黒田財政課長","answer":"令和５年度の総務費では、新庁舎建設のために基金の積立てを行っておりますので、そういった意味で、当初予算が伸びているというような状況です。","id":"exchange-097"},{"speaker":"木村委員","kind":"質問","question":"次は区民憲章です。４０周年からお聞きをいたしますけれども、まず最初に、この予算の内容をお聞かせください。そして令和４年度予算と比べると、大きく減っています。その理由もついでにお聞かせください。","respondent":"大澤広報広聴課長","answer":"今年度につきましては、区民憲章の制定から４０周年を迎えまして、記念事業を実施したため、その費用が必要でございましたけれども、令和５年度におきましては、その費用がなくなるために、予算額としては減少しているものです。","id":"exchange-098"},{"speaker":"木村委員","kind":"意見","question":"今度はこの区民憲章、今お話もありましたけれども、区民憲章４０周年ということでありました。記念行事として、いろいろなことが行われたと思います。率直に、記念事業に対する区民の皆さんの反応、それは本当に区民の皆さんがこの４０周年に対してどのように思っているのか、そのようなことに対して何か感じるようなことがあるのかどうか、お聞かせください。","respondent":"大澤広報広聴課長","answer":"父や母がいたふるさとを思い、心のよりどころとなる区民憲章が大好きなので、今後もより身近に感じられる企画を通して、未来へつなげてほしいということでございました。区としましても、区民憲章に込められた思いを伝える大切さを再認識したところです。","id":"exchange-099"},{"speaker":"木村委員","kind":"質問・要望","question":"区民の皆さんが、この区民憲章の４０周年に対してすごい熱意を持っているのだなというところも何となく感じました。次に、しながわ百景ですけれども、これはいつ、どのようにして活用してきたのでしょうか。聞くところでは、しながわ百景はリニューアルをしたということですけれども、どのようなところ、また、どのような部分をリニューアルしたのでしょうか。その理由もお聞かせをください。","respondent":"大澤広報広聴課長","answer":"リニューアルの理由ですが、しながわ百景を選定した当時から３０年がたちまして、時間の経過とともに消えてしまった風景もございました。そのために、新しく生まれた風景を加えまして、再度区民の方による投票を行い、その結果、１０余りの風景の入替えを行ったものです。","id":"exchange-100"},{"speaker":"木村委員","kind":"質問・要望","question":"これは品川区民だけのことなのか、それとも他区からもそのことを見ることができるのかどうか、これはどのようになっているのか、お聞かせください。そして、ほとんどが品川区民だと思いますけれども、高齢者が大変多いと思うのですが、一応若い方も大変興味があるのかどうか、そのようなこともお聞かせをいただきたいと思います。","respondent":"大澤広報広聴課長","answer":"こちらコメントがついておりますので、こちらのコメントから推量いたしますと、若い方のご視聴が多いように見受けられます。中には、ぜひ行ってみたいというコメントもあることから、区外の方へのＰＲにもなっていると考えられると認識しています。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひとも１人でも多くの方々に視聴をしていただいて、品川のよさを分かっていただきたいと思います。次に、１７５ページの非核平和都市品川宣言事業の中のしながわ平和の花壇からですけれども、二度と起こしてはならない戦争、これは日本国民であれば誰もが思うことであります。本区のこの花に対しての気持ちは、どのようなお考えで平和の花壇を作ったのか、お聞かせをいただきたいと思います。","respondent":"古巻総務課長","answer":"昨年の夏には、ウクライナへの支援というような意味合いを込めまして、ウクライナの国の花でありますヒマワリの植栽も実施をさせていただきました。","id":"exchange-102"},{"speaker":"木村委員","kind":"質問・要望","question":"１日も早く戦争が終わることを願っています。その下の危機管理経費ですけれども、新型コロナウイルス感染症対策費からですが、令和４年度では３２４万円余が計上され、令和５年度は３４９万円余です。ほぼ同額の予算となりました。この予算でどのような対応を行っているのでしょうか。令和４年度もほぼ同額の予算でしたけれども、令和４年度の結果もまたお聞かせをいただきたいと思います。","respondent":"古巻総務課長","answer":"新型コロナウイルス、５月以降５類への移行というようなことが言われておりまして、若干今までと違うフェーズに移行するというようなことはありますけれども、引き続き基本的な感染症の対策ということは必要であるですので、来年度、令和５年度につきましても。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問・要望","question":"市町村交流事業からですけれども、本区は現在山北町、そして早川町との交流を行っております。各、何年になるのか、これもお聞かせください。そして令和５年度は山北町６２２万円余、早川町が１８６万円余ですけれども、令和４年度の予算から早川町は減額しております。この減額の原因はコロナが影響しているのかどうか、お聞かせをいただきたいと思います。","respondent":"古巻総務課長","answer":"神奈川県の山北町、それから山梨県の早川町との交流ですが、山北町との交流につきましては、昭和６３年の４月以降、協定を締結いたしまして交流を続けております。早川町につきましては、平成２年の４月ということで、それぞれ三十数年の日付がたっているです。","id":"exchange-104"},{"speaker":"木村委員","kind":"質問・要望","question":"どちらにしても、区民の日頃の疲れを癒やす場所、そのような場所として、品川区の財産として、またしっかりと管理をしていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"小芝委員","kind":"質問","question":"よろしくお願いします。私からは、１８９ページの地域センターの改築に関連しまして、地域センターと地域とのつながりについて、また、１９９ページ、歴史館運営費についてお伺いします。地域センターと地域とのつながりについてお伺いします。そこでお聞きしますが、この地域センターに携帯電話ないしスマートフォンが配備され始めたいきさつについて、教えていただけばと思います。","respondent":"川島地域活動課長","answer":"目的としましては、緊急時の連絡手段ですとか、地域のお祭り等の事業用というような形で配備したものです。今、委員がおっしゃったとおり、令和３年度にスマホのiPhone SEへ機種変更して、今各センターに１台ずつ配備されている状況です。","id":"exchange-106"},{"speaker":"小芝委員","kind":"質問","question":"当然品川区は自治体ですので、公助の担い手にもなっております。この配備されています携帯電話、スマートフォンの役割、先ほど少しお話もいただいておりますが、これ自体は常時携帯をしているものなのか、その時々の、先ほどお祭りの話も出ましたけれども、その時々において使うものなのか、その辺教えてもらってもよろしいですか。","respondent":"川島地域活動課長","answer":"各地域センターによっても、運用は多分異なると思うのですけれども、所長が持っていたり、誰か職員が１人持っていたりということで、自宅に持ち帰っている所長もいますし、地域センターに置いてある場合もあるとは思うのですが、緊急連絡用ということですので。","id":"exchange-107"},{"speaker":"小芝委員","kind":"質問","question":"自宅に持って帰っておられるセンター所長もいらっしゃるかもしれないという話でございましたけれども、それは当然、これは仕事へのひたむきな姿勢から、場合によっては勤務時間外にも使用するケースも出てくると思います。私は、この携帯やスマートフォン、もう今の時代になくてはならないものですので、ぜひ積極的に利用してもらいたいという立場ですが、区の見解について教えていただければと思います。","respondent":"川島地域活動課長","answer":"今、皆さんスマホ等を、もうほぼ当たり前のように持っている状況ですので、本当の緊急連絡というものは、当然地域センターの所長、職員にも、個人用のスマホには連絡するような形での連絡網の体制等も取ってありますが、こういった公務に使うということで。","id":"exchange-108"},{"speaker":"小芝委員","kind":"質問・要望","question":"ぜひこのスマートフォン、携帯電話を利用促進していただきたいと思います。続きまして、品川歴史館の運営について伺います。というのは、この宿場町をあたかも歩いているかのような、そういったバーチャルツアーであれば、また面白いかなとは思うのですけれども、そういったことも含めて、バーチャルツアーの今後の展開、取組、一時的なものかどうかも含めて、教えていただければと思います。","respondent":"山崎文化スポーツ振興部長","answer":"現在ホームページのほうで、リアルな展示の実体験ができないということで、ご案内のバーチャルツアーと銘打ってやっております。","id":"exchange-109"},{"speaker":"小芝委員","kind":"提案","question":"続きまして、これからの運営といいますか、展開をめぐっては、私も再三一般質問等で提案をさせていただきましたが、この品川区にゆかりのある人物、特に幕末に活躍した志士でもありました坂本龍馬や山内容堂公、また伊藤博文、岩倉具視、板垣退助など、歴史の偉人をぜひ取り上げてもらいたいと思います。さらに、特に言いますと、西大井駅の裏には伊藤博文公の墓所があります。","respondent":"山崎文化スポーツ振興部長","answer":"ただ、歴史館の、公共施設として、その時代だけではなくて、やはり品川、縄文時代の大森貝塚からスタートしまして、中世の時代は江戸湊で栄え、江戸になりまして東海道など、産業の発祥の地になった、いわゆる交通の、物流の拠点品川という１つの大きな捉えで。","id":"exchange-110"},{"speaker":"小芝委員","kind":"質問・要望","question":"ご答弁ありがとうあります。本当にそうですね。その１つとして、これちょっと紹介させてもらいたいのですけれども、ある児童書があります。決して人ごとではない。直接品川区で起こった出来事ではないかもしれませんが、この品川区に住んでいた当時の小学生が無残にも戦火に倒れた、そういった歴史も、ぜひ歴史館の中で取り扱っていただきたいと思いますが、お考えをいただければと思います。","respondent":"山崎文化スポーツ振興部長","answer":"様々工夫しながら、区民の皆様に愛される歴史館として、しっかり取り組んでまいる所存です。","id":"exchange-111"},{"speaker":"たけうち委員","kind":"質問","question":"１７５ページの非核平和都市品川宣言事業、１８１ページ、庁舎管理費、１８３ページ、庁舎計画費で伺います。非核平和のほうですが、非核平和都市品川宣言２０周年の記念事業として、しながわ中央公園に平和のモニュメントが設置されておりますけれども、設置の際、タイムカプセルが埋められていると思いますけれども、中にどのようなものが入っていて、これはいつ頃開けるのか、お聞きしたいと思います。","respondent":"古巻総務課長","answer":"開けるのは５０周年記念事業の際ということですので、２０周年からすると３０年後という設定で埋めたものと認識をしております。","id":"exchange-112"},{"speaker":"たけうち委員","kind":"質問・要望","question":"約１,７００人の小学校６年生のそういったものが、メッセージ、また広島・長崎のが入っていると。それで、３０年後なので、あと１２年後なのですね。名前を書いていなかったというのがあるらしいですが、当然、品川区ではそのようなことにならないと思うのですが、これはしっかりどこが引き継いで、１２年後、タイムカプセルを開封していくのか、お知らせをいただきたいと思います。","respondent":"古巻総務課長","answer":"非核平和都市品川宣言ですけれども、今現在、総務課の平和・国際担当が所管をしておりまして、しっかり、タイムカプセルの状況に関しましては引継ぎをしておりますので、まだ、１２年後ということでございまして、少し先の話ですけれども、５０周年に向けて。","id":"exchange-113"},{"speaker":"たけうち委員","kind":"提案","question":"私たちの公明党の先輩議員の嶋邦子さんが、平成１６年の決算特別委員会で、このタイムカプセルについて、ポートランド、オークランド、ジュネーブ、こうした友好姉妹都市の方々と連携をして、そうした方々の発信もいただいたらどうでしょうかというご提案をさせていただいた、古いお話ですけれども、そうしたことも４０周年、５０周年の記念事業の際には検討いただけないかなと思うのですが。","respondent":"古巻総務課長","answer":"タイムカプセルのことに関しましては、４０周年の際にはもう２０年が過ぎているですので、区としてはしっかり引き継いではありますけれども、区民へのそういったアピールというのも必要になってくるのかなと考えていますので。","id":"exchange-114"},{"speaker":"たけうち委員","kind":"質問・要望","question":"庁舎管理費と庁舎計画費ですけれども、本庁舎や第二庁舎にタイムカプセル的なものが埋まっているのでしょうか。礎を定めると書いて定礎という言葉がありますが、第二庁舎には定礎の石があります。ただ、本庁舎には見当たらなかったのですが、どこかにあるのか教えていただきたい。定礎という言葉の意味を教えていただきたいと思います。","respondent":"東野経理課長","answer":"定礎ですが、こちらは、建築工事の開始を記念しまして、建物の安泰を祈るために行われる定礎式というものが、明治時代から日本に入ってきました。もともとはヨーロッパで行われていた風習のようです。","id":"exchange-115"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ぜひともその辺を曖昧にせずに、分かる範囲で結構ですので、しっかりしていただきたいと思います。それで、それを見たいときに、個人情報のこともありますが見られるようにするとか、何かいろいろな工夫があるのかなと思うのですが、その辺のお考えをお聞きしたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"そのことを踏まえまして、具体的にどのようなものを入れるか。よく民間のビルとかですと、その竣工に携わった人の名前を入れるとか、そういうこともありますので、委員のお話でいただいたことも踏まえながら、今後検討してまいりたいと考えております。","id":"exchange-116"},{"speaker":"たけうち委員","kind":"質問・要望","question":"港区なども７０周年のときに、タイムカプセルという形で庁舎に埋めているようです。いろいろな形で、代表者になるのでしょうけれども、より多く、区民の方のそういった賛同をいただいたということのあかしとしても、また品川区の発展のためにも、そういったものを検討いただきたいと思います。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１８２ページ、新庁舎整備費について、それとあと、１７７ページ、特別職報酬等審議会経費についてお尋ねします。新庁舎整備に備えて財源確保をしっかりとする必要があると考えて、前々からお尋ねしています。財源計画の起債について今までもお伺いしてきましたけれども、昨年の決算特別委員会で、地方財政法第５条では、公用施設、つまり庁舎の整備には起債が認められないのではないかとお伺いしました。","respondent":"黒田財政課長","answer":"いわゆる庁舎に係る事業ということですが、通常はその建設でありましたり、事業の内容によると思いますが、いわゆる外構的な整備というところも含まれると思いますが、実際にどの部分が起債対象事業になるかということにつきましては、起債をする段階で。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"意見","question":"これによると、公用施設、つまり庁舎や消防署等に地方債が活用できる事業の紹介が５事業ありました。私がその資料を読んだところによると、新庁舎整備に当たっては、この５事業の中で該当するものは１事業しか見当たりません。それも、令和４年度から令和７年度がその１事業です。それから、もしそれが可能だとすると、約４００億円のうちのどのぐらいのパーセンテージになるのか、お尋ねします。","respondent":"黒田財政課長","answer":"今の委員からご紹介がありましたいわゆる防災事業というのは、地方債同意等基準の中で言うと、いわゆる一般事業債とは別の事業で、地方財政計画の中で地方交付税を充当してできる事業という中で、幾つか事業紹介がありまして、その中に緊急防災事業ということで。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"地方財政計画のその他の事業ということですね。そうすると、それのどういう事業で起債ができるかということを、東京都とお話ししているのでしょうか。","respondent":"黒田財政課長","answer":"ですので、庁舎の中に、例えばいわゆる防災センターのエリアができれば、そこはまた違った起債メニューが使えるといったことも東京都と話をしていますので、そういった意味では、庁舎として機能するものについては一般事業債で起債の対象になると確認しているものです。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、緊急防災・減災事業債については先ほどの１つの事業の中にあって、それが先ほどお話があった防災センター施設、第二庁舎の防災センターですね、ああいう形でやると、全体の床面積のどれだけかとかで起債をしていける。","respondent":"黒田財政課長","answer":"いわゆる一般事業の中では、総務省の地方債同意等基準でも庁舎という表現が出てまいりまして、いわゆる行政機能を活動する建物は庁舎ということですから、例えばその建物の中に、スペースの中で商業施設、例えばコンビニを入れるということがあれば。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問","question":"今のご説明だと、お店とか、そういう行政機能に関わらないところに関しては、先ほどのお話にあった、地方財政計画のその他の事業で起債できるというお答えでよろしいですか。","respondent":"黒田財政課長","answer":"いわゆる地方債同意等基準の中では、「一般事業については、地方単独事業のうち他の事業区分に属する事業の対象とならない事業を対象とするもの」と記載がありますので、そこに庁舎建設が当たるというものです。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、そこが庁舎建設に当たるというお話でしたが、それは、約４００億円の中のどれぐらいの割合でできるのかということを、当然いろいろ検討されながら、今お話しされているのではないかと思うのですが、いかがでしょうか。","respondent":"黒田財政課長","answer":"上限いっぱいまで起債するかどうかというのは計画の内容によりますが、ただ、庁舎の建設に当たっては、国や都の施設が入れば、そういったところのいわゆる分担する部分も出てまいりますので、区として負担する部分がどのぐらいかというところで。","id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません、物分かりが悪くて。勉強させていただいて、お尋ねしたいと思います。それで、今、７５％がマックスということなので、前もお話ししましたけれども、その中で果たして、では、積立てですね、基金を積んでいるのと、東京都とか国は置いておいて、それで何とか充当していけるという見込みが現在あるから、ああいう基金の積立て計画を立てていらっしゃるのでしょうか。","respondent":"黒田財政課長","answer":"建設事業費は基本構想の中で約４００億円となっておりまして、その中で自己資金として１２０億円という形ですが、充当率が７５％ということですので、そのほかに、分担があれば分担金を差し引いていくというところで、そういった計画を立てているです。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"新庁舎整備に備えてしっかりと財源確保をしてほしいということは思っていて、そこが成功するようにきちんと準備をしていただきたいという考えから、私は質問させていただいているので、後からばたばたと何かとか、そういうのではなくて着実に。大変な金額を進めていくわけですから、そのために、今のご説明だと、区民の方に説明しても、私、説明し切れないところがあるので、また勉強します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は予算書ページ１６８、広報広聴費、広報経費に関連して、自治体広報とフェイクニュースについて取り上げ、質疑してまいりますので、よろしくご答弁のほどをお願いいたします。現在の品川区の広報活動についてお伺いいたします。区の情報発信は様々な手段で行われています。その評価等は行われているのでしょうか。","respondent":"大澤広報広聴課長","answer":"今年度実施しました世論調査におきましては、区に関する情報の入手先として、上位は広報しながわ、ホームページ、回覧板、ＳＮＳの順となっております。","id":"exchange-126"},{"speaker":"鈴木（博）委員","kind":"質問","question":"デジタル、アナログの両面で情報発信を行っているとのことですが、例えば区民にとって重要な情報である新型コロナウイルス感染症及びコロナワクチンに関しては、コロナ禍以降、どのぐらいの情報発信がなされてきたのでしょうか。ご説明をお願いいたします。","respondent":"大澤広報広聴課長","answer":"ホームページにおきましては、コロナに関する新規ページを１２回開設しております。プレスリリースは１２９回行っておりまして、区としましては、区民の皆様が必要な情報を手に入れられるよう、複数の手段を組み合わせて発信してきたところです。","id":"exchange-127"},{"speaker":"鈴木（博）委員","kind":"質問","question":"感染症に関する情報発信については、区としてもそれなりに努力されてきたということは理解できました。感染症に関する情報をはじめとして、現在、世の中ではフェイクニュースが大量に流布されております。そのようなフェイクニュースに関して、区はどのように捉えているのでしょうか。ご説明をお願いいたします。","respondent":"大澤広報広聴課長","answer":"フェイクニュースに関してですが、これは、悪意を持ってつくられたうその情報や、現在、ＡＩ技術を駆使してつくられた偽の映像など、悪い意味でのレベルの高いものから、単なる誤解による誤った情報や、悪ふざけや、発信者にとっては冗談だったというようなレベルのものまで。","id":"exchange-128"},{"speaker":"鈴木（博）委員","kind":"意見","question":"２０１６年に世界的に発生した偽ニュースの氾濫と、それが引き起した混乱をきっかけにして、事実かどうか分からない情報の代名詞として、フェイクニュースという言葉が使われ始めました。このような状況の中で、フェイクニュースに対する公的情報の提供者である品川区の現在の対応について、ご説明をお願いいたします。","respondent":"大澤広報広聴課長","answer":"フェイクニュースに対しての区の対応ですが、情報の真偽の見極めというのは、専門的な知見が必要な場合もありますし、また真偽の判断が分かれる場合もありますので、ほかのところから発信された情報に対しまして、直接区として反論を表明するということはしておりませんが。","id":"exchange-129"},{"speaker":"鈴木（博）委員","kind":"質問","question":"全くご説明のとおりだと思うのですが、フェイクニュースに振り回されないためには、情報リテラシーが非常に大切だということが言われております。区として、情報リテラシーに関して何か取組などを行っているのでしょうか。","respondent":"大澤広報広聴課長","answer":"区では現在、学校において、情報リテラシーについて学習していると聞いております。ただ、今後は子どもだけではなく、その上の世代にも、情報リテラシーについて普及啓発していく必要があるということは、今、感じているところです。","id":"exchange-130"},{"speaker":"鈴木（博）委員","kind":"質問","question":"フェイクニュースをまき散らす風評加害者から、被害を受ける、損害を受ける風評被害者を守らなければなりません。区として、今後も区民を守る情報発信をしっかりと、情報加害者に翻弄されないように区民を守るために、今後の情報発信をしっかりとするようにお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、１７８ページの人事管理費のところから、保健師の定数増と、それから、会計年度任用職員の待遇改善を求めて質問をしたいと思います。２３区平均まで持っていくのに、２０２１年の１０月の決算特別委員会で私が伺ったときは、１２名足りないということでしたが、今はどれぐらい足りないのかが分かれば、教えていただきたいと思います。","respondent":"崎村人事課長","answer":"保健師の定数の増のお話ですけれども、認識としては、委員のお話にありましたように、２３区中２２位というような保健師の体制の状況もありますので、この間も、保健師については増員を図ってきたところですし、こちらの人数については。","id":"exchange-132"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２０２１年の１０月よりもさらに広がって、１４名も足りないというのは、本当にゆゆしき状況ではないかなと思うのです。本当にこれだと、早急に、１４名も足りないというところの解決には向かっていかないのではないかと思うのですが、こういう計画が必要ではないかと思うのですが、このガイドについてご覧になられているかも含めて、伺いたいと思います。","respondent":"崎村人事課長","answer":"そういった中で、これから、繰り返しになりますけれども、１４名足りないというところで、では来年度、１４名採ればいいのかという話になるかと思うのですけれども、そうすると、１４名を誰が育成するのかという話にもなりますし、若手が若手を育成するとなりますと。","id":"exchange-133"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが今の品川区の実態になっていると思うのです。そして、継続的に増員していただきたいと思います。それで、ここの中に書かれていたのが、計画を策定するに当たって、統括保健師の役割が非常に重要だということが書かれていまして、平成２５年の指針の中に、その統括保健師の役割というのが記載されているのですけれども、統括保健師というのは、品川区ではどういう配置の状況になっているのか伺います。","respondent":"崎村人事課長","answer":"統括保健師という職があるわけではありませんので、区の中でどういう配置をしているのかというのは、なかなかお答えしづらいのですけれども、今の健康課の中に保健師を定数で配置しておりまして、その保健師が。","id":"exchange-134"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"会計年度任用職員について伺います。私は、この改善が必要なのではないかという思いで質問したいと思います。１つは、公募によらない再度の任用の上限の回数というのは、多くの自治体が２回としているということで、３年目の壁ということで今年言われていると書かれているのですが、その雇い止めが危惧されている中で、品川区は上限回数をどう定めているかというのを１つ伺いたいと思います。","respondent":"崎村人事課長","answer":"ですので、なかなか待遇面の違いといったところを説明するのは難しいのですけれども、あとは一つお話しできるのは、会計年度任用職員ですと期末手当のみが支給されているところ、例えば常勤職員ですと期末手当と勤勉手当が支給されているといったような。","id":"exchange-135"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"会計年度任用職員は定期昇給もありませんよね。それから、退職金もない。それから、地域手当というのもないのかなと思ったのですが、職員は地域手当がついているということですが、職員の地域手当というのは賃金の何％になるのかも伺いたいのと、地域手当が会計年度任用職員についていない、その理由についても伺います。","respondent":"崎村人事課長","answer":"地域手当につきましては、常勤職員の場合は給料月額の２０％ということで、設定されております。会計年度任用職員については、報酬額を決定する際に、地域手当も含めて算定しています。","id":"exchange-136"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"地域手当の２０％も含めてこの時給というのは、一覧表も見ましたが、本当にこれは低い。しかも、時給１,５００円未満が５割もいるというところで、本当に会計年度任用職員の待遇というのはひどい条件になっているなと思います。この基準と、それから、その中で、賃上げがされると言いながら賃上げがされない職種というか、ところもあるのですが、それはなぜなのかについても伺います。","respondent":"崎村人事課長","answer":"今年の４月から、会計年度任用職員の報酬額の改定をする予定でございまして、１つは、今年度の給与改定において、初任給や若年層を中心に給料額の増額改定がございましたので、その給料表にひもづくといいますか、報酬額についても引上げになる職があります。","id":"exchange-137"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういった方も決して高いわけではないと思うのです。物価高とか負担増が大きい中で、ぜひともそういう方も含めて賃上げをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-138"},{"speaker":"若林委員","kind":"質問・要望","question":"１９９ページ、文化センター事業の中のプラネタリウムを取り出してと考えています。歳入で少し消化不良を起こしましたので、引き続きというところです。歳入の質疑の中で確認をさせていただきました。その発想をさらに醸成させるために、この施政方針とかをしっかりと理解すること、またその真意が伝わっているか否かを確認する、そういったやり取りの作業も、今後必要になってくるのではないかなと思います。","respondent":"山崎文化スポーツ振興部長、佐藤企画調整課長","answer":"その中では、品川区が持つ江戸時代からの交易の拠点としてのにぎわいでありますとか、明治時代からの近代産業の発祥の地としての発展、こうした、現在も歴史に由来する名所旧跡、１００を超える活力ある商店街、運河・水辺。委員のご紹介のとおり、施政方針で区長から、「『誰もが生きがいを感じ、自分らしく暮らしていける品川』を区民とともにつくっていく、まさにその出発点となる１年としていく」というところでございまして、ここに向かって来年度。","id":"exchange-139"},{"speaker":"若林委員","kind":"質問・要望","question":"観光のプランがあることは存じております。ぜひとも区内・区外の数ぐらいは取っていただいて、何か今後、ＴＯＣも改築する、ゆうぽうとも今年の末に竣工する、こういう時期を、これはまちづくりの話になるかもしれませんけれども、でも、なりませんけれどもということを私が発言すること自体がもうおかしいわけであって、そういう意味では、ご答弁を再度いただきたいと思います。","respondent":"山崎文化スポーツ振興部長","answer":"大変すみませんでした。","id":"exchange-140"},{"speaker":"渡部委員","kind":"質問","question":"２０９ページ、マイナンバーカードですが、普及していって、持っている人も増えていって、だけれども、私も聞かれることなのだが、「住民票を取るのも戸籍も始まって、すごく便利になったんだよ。逆に「一・四・八」の地域センターでできるというよりも、できないところでできるようにしてほしいなと思いまして、そういう意味で件数も聞いているのですが、教えてください。","respondent":"吉野戸籍住民課長","answer":"数値のほうが、今、持ち合わせておりませんでして、確かに一定数、区民の方からの問合せがありまして、実際には一定数の方が窓口にいらっしゃいます。一応マイキーＩＤなど、そういったところに関しましては、毎日やはり一定数、約１００人程度の方がいらっしゃっております。","id":"exchange-141"},{"speaker":"渡部委員","kind":"質問","question":"それに対しては答弁は結構です。言い逃げになってしまいますが、１３地域センターでパスワードの照合ですとか、やって差し上げてほしいなというところがあって、少し時間を取らせていただきました。これは誠におめでとうあります。スポーツ協会のホームページを見ると、何か記念誌は作るみたいなことは書いてあったのですが、その辺を教えてください。","respondent":"辻スポーツ推進課長","answer":"スポーツ協会の３０周年についてのお問合せかと思います。来年度のスポーツ協会助成金の中で、３０周年記念事業ということで２００万円を計上しております。山下さんが来たときほどではないですが、講演会やいろいろな催しというものも準備していると聞いております。","id":"exchange-142"},{"speaker":"渡部委員","kind":"質問・要望","question":"安心をいたしました。それをまた地域に戻って子どもたちとやっていったら、意外と子どもたちは学校でやっているということがあって、では、例えばそういうニュースポーツの３０周年の記念大会とか、スポーツ協会と一緒になって。ボッチャとか、そういう大会とかを企画して、どんどん参加してもらえるような形のイベントも、ぜひ検討していただきたいと思うのですが、いかがですか。","respondent":"辻スポーツ推進課長","answer":"３０周年の記念事業ですが、新年度に入りますと、実行委員会形式で開いて、内容について決めてまいりますので、委員の提案なさったような、みんなが楽しめるイベントも含めて、考えていきたいと考えています。","id":"exchange-143"},{"speaker":"渡部委員","kind":"質問・要望","question":"当然それは、世代は関係なしでいろいろなことをやっていかなければいけないから、では、シニアに特化したものはテニス教室と何とかとぐらいになってしまうのかもしれないのですけれども、やはりそこを充実してほしいかなと。普通に私は元気だよという方々はいっぱいいて、そういう人が普通に足を運べるようなイベントを、これからもいろいろ考えて増やしてほしいなというところで、これは要望します。新庁舎。","respondent":"山下新庁舎整備課長","answer":"ただいま委員からございました、今後の取組というところですけれども、これまでは、ある意味では新庁舎整備課とはまた別のまちづくりの部隊として、都市環境部都市開発課のほうでそれを担っていた部分がありますけれども、今般予定しております組織改正の中では。","id":"exchange-144"},{"speaker":"渡部委員","kind":"質問","question":"そうなった場合に、これから、あり方検討会というのですか、広町地区を、新しい部署もつくっていろいろやっていくという中で、当然、それは検討委員会をつくって、先ほど来、本日もいろいろな話があって、地域というか、区民の皆様の意見も聞きながら、いろいろなことをやっていくというのですが、逆に私はそろそろ、やはり本当にまちのコンサルとか、それこそＪＲの事業部隊とかも、話というのは。","respondent":"山下新庁舎整備課長","answer":"今般、組織改正の中で広町事業担当という形で、広町の部分について、ある意味では特命部隊のような形で独立して設けますけれども、今まで都市開発の部門で、いわゆる大井町駅周辺のまちづくりを進めているところがありますので。","id":"exchange-145"},{"speaker":"吉田委員","kind":"質問・要望","question":"契約情報のことを伺います。それから、１９５ページ、しながわ観光大使関連事業で２つ伺いたいと思います。最初に、契約関係事務費で伺います。昨年の決算特別委員会の総括質疑の際に、質問に関連して、区の契約情報が公募期間が過ぎると消えてしまう件について、情報をぜひ残していただきたいと改善を求めたところ、素早く対応していただいたことは評価をいたします。ただ、情報量があまりにも少ないです。","respondent":"東野経理課長","answer":"そうしますと、過去の情報は、令和３年度でいきますと２５０件ほどありますので、１００ＭＢを超えるような情報をホームページ上に残すというのがどうかという議論を、経理課内で行いまして、現在のような形で掲載をしているものです。","id":"exchange-146"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、例えばどういう手続が必要なのか、誰でも、この契約についてどうなったのかというのを聞けば、窓口で特に手続なく聞けるのでしょうか。窓口に行かなければ駄目なのでしょうかね。例えばメールでの問合せとか、何かそういうことは可能なのか、伺いたいと思います。ぜひ多くの人がアクセスできるような情報提供にしていただきたいのですが、いかがでしょう。","respondent":"東野経理課長","answer":"知りたい情報がどういう情報かにもよるかと思いますが、公募という部分におきましては、もう公表されている情報ということになりますので、その辺を踏まえた上で、所管のほうで対応が可能かと思われます。","id":"exchange-147"},{"speaker":"吉田委員","kind":"質問・要望","question":"一般の区民の方は、情報公開請求の手続を取らなければ駄目ということなのでしょうか。ぜひ、資料提供ということでおっしゃいましたが、過去にもう公表されているものですので、もっと簡便な手続で出していただきたいのですが、一応、情報公開請求となると２週間程度待たされたりするのですが、その点についていかがでしょう。","respondent":"大澤広報広聴課長","answer":"現在、情報公開に関しましては紙媒体でのお返しとなっておりますが、ＣＤ等については今後の検討課題とさせていただきたいと考えています。","id":"exchange-148"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。ぜひこういう情報を知りたいという方には、簡便な手続で、安い費用でやっていただきたい。できたら情報公開手続ではなくて、何らかの形で、過去に掲載されていたこの情報について出してほしいと言えば出していただけるように、お願いしたいと思います。もし何か見解があったら後で伺います。次に、１９５ページのしながわ観光大使関連事業について伺います。それをお聞かせください。","respondent":"山崎文化スポーツ振興部長","answer":"委員のおっしゃられる理解で結構かと思います。基本的には、平成３０年４月１日に基本協定を締結しまして、毎年、変化がある部分については、年度協定的に個別協定を結んでいるです。","id":"exchange-149"},{"speaker":"吉田委員","kind":"質問","question":"基本協定は毎年結ぶように読めたのですが、そうではなくて、基本協定というのは１回で終わりということでしょうかね。その辺、改めて伺います。要するに、他自治体で使われたことも、非独占的な許諾の結果だからやむを得ないということなのでしょうか。つまり、シナモロールを品川区の観光大使として使ってもよいけれども、他の自治体が使っては駄目とは言っていないよという理解でいいですか。","respondent":"山崎文化スポーツ振興部長","answer":"基本協定については平成３０年４月１日より締結をし、現在までその内容に変化がありませんので、１年ごとの自動更新で来ているよということと、それから、個別協定書については金額設定などがありますので。","id":"exchange-150"},{"speaker":"吉田委員","kind":"確認","question":"確認です。それから、投票済証のことがあります。昨年の区議会議員補欠選挙のときに、シナモロールの絵柄で投票済証が発行されて、しかも２回やったので、２回デザインが違ったと思うのですけれども、その活用については、区としての基本的な活用の範囲として認められたものなのか、それとも新たな個別の協定が必要だったのか、その辺についても伺いたいと思います。","respondent":"山崎文化スポーツ振興部長","answer":"今年度当初、令和４年４月１日に個別協定書を締結しておりまして、その中の特記事項の、いわゆるロイヤリティーの金額を定める部分があります。ここの部分では、税込み金額で３９６万円です。","id":"exchange-151"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。だから、今回の投票済証については、もう基本的な使い方の中に含まれたということで、製作費用は発生したけれども、ロイヤリティーとかそういう支払いはなかったということですね。分かりました。さっき伺いましたか。これまでどれくらいサンリオに支払ったかは、ぱっとは出ませんかね。もし、ざっくりとでもいいので伺えたら。","respondent":"山崎文化スポーツ振興部長","answer":"先ほどのロイヤリティーの４１８万円で、契約が平成３０年度からですから、約２,０００万円ということになります。","id":"exchange-152"},{"speaker":"吉田委員","kind":"質問","question":"それは基本ロイヤリティーだけですよね。何かその後、サンリオから、いや、それは個別の協定が必要でしょうと言われたものは、では、なかったということですか、この間。","respondent":"山崎文化スポーツ振興部長","answer":"例えばそうではなくて、これ、私ども文化観光課でも作ったのですが、例えば腕につけるふわふわのクッションのようなもの、これはノベルティを作るということになりますので、例えば製作費の３０％をお支払いするとかという、個別のものは発生しています。","id":"exchange-153"},{"speaker":"吉田委員","kind":"質問・要望","question":"大分分かってきました。それで、私は別にこのシナモロールの活用に賛成・反対とか、そういうことはないのですが、やはりこういう金額的なことも含めて、どこかに、議会に、それほど大きな金額ではないという判断かもしれませんけれども、その事業に関係するところには、お金のことについては報告を出していただきたいと思いますが、その点についてはいかがでしょう。","respondent":"山崎文化スポーツ振興部長","answer":"全体の事業の金額の内訳として出てくるところですので、いろいろ表記については工夫なり、分かりやすく表現するというのも考慮したいなとは思っております。","id":"exchange-154"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当然、すばらしいことで、やっていただきたいと思うのですが、この中で少し気になったのは、議会に対してはどういうふうに説明していただけるのか、そのタイミングはどうなのかなということを確認させていただきたいと思います。区の中で、現在活用の検討をして、随分進んでいるところがあるのですが、それ以外に今、区の公有地として活用できる部分というのはどこかあるのかというのが、１つ確認です。","respondent":"大澤広報広聴課長、佐藤企画調整課長","answer":"区民アンケートですが、集計の結果につきましては、まずは議会に報告する予定です。その後、区長の記者会見や広報紙やホームページでの公表という順番になります。こちらに関しましては、平成２９年３月当時に更地になったタイミングで、区から一応、活用であったり取得の調整をしたところなのですが、なかなか条件がいろいろありましてかみ合わなかったというところで。","id":"exchange-155"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"東品川文化センターを直したばかりですから、大きな金額をかけて何かやるということはできないと思うのですが、やはりせっかく考えていた都有地がパーキングになってしまったというのは寂しかったので、何かこれからもうまく活用していただいて、ほかに私はあまり場所をよく知らないですが、ほかの場所を転用してもらって、使える場所もあるのではないかなということも考えているところですが。","respondent":"古巻総務課長","answer":"今ご紹介いただきました大学との連携の関係ですけれども、この間、区内の６つの大学と包括的な協定を結んでということで始まりまして、しながわ大学連携推進協議会などというものも立ち上げて、様々なこういう連携を進めてきていたところですけれども。","id":"exchange-156"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"しかし、活かしていただいて、２０万円ずつ４校に出ているというお話もありました。さらに、これはもう先々ですけれども、そういう学生さんが行政に意識を持っていただいて、そういう方は品川区の中の職員にまた入ってきてくれるような、そういう形まで進んでいけば幸いだと思いますので、そこまで、少し望みも高いかもしれませんが、うまくできれば、進めていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"石田委員","kind":"質問","question":"私は、１７８ページ、人権啓発費からパートナーシップ制度について、関連して性的マイノリティへの支援について伺いたいと思います。こうした国の閣僚等によるジェンダーや性的マイノリティへの差別発言が繰り返されていることを、区はどのように受け止めているか、伺いたいと思います。","respondent":"加島人権啓発課長","answer":"今、委員からございました元首相秘書官の発言につきましては、既に首相のほうで対応がされているもので、一自治体としての見解は控えたいと思います。","id":"exchange-158"},{"speaker":"石田委員","kind":"質問・要望","question":"そうした根深い差別意識などを克服していくことこそ、必要だと思います。そういうところで今回、都のパートナーシップ宣誓制度の活用が予算に組まれましたけれども、共産党としては、区としてこのパートナーシップ制度をつくってもらいたい、実施してほしいということを求めてきましたので、なぜ都の制度活用なのかということで、昨年の決算特別委員会でも中塚委員がお聞きしました。","respondent":"加島人権啓発課長","answer":"そのため、区として東京都パートナーシップ宣誓制度の活用を進めていく、そのように決定いたしまして、プレス発表も行いました。","id":"exchange-159"},{"speaker":"石田委員","kind":"質問","question":"そうすると、現段階というよりは、ずっとこの東京都のパートナーシップ宣誓制度でいくと、区としてつくる考えはないということでよろしいでしょうか。伺います。","respondent":"加島人権啓発課長","answer":"都の制度対象の要件といたしまして、都内在住に限らず、在勤・在学の方も対象となっていること、また、子どもに関する困り事に対応するため、証明書にもそのような配慮がなされていることから、区としては東京都パートナーシップ宣誓制度の活用を進めてまいります。","id":"exchange-160"},{"speaker":"石田委員","kind":"質問","question":"やはりメッセージになるのですよね。そういうことでつくられているという声を伺いました。なので、都と連携して他区もやられていますので、区としても性的マイノリティの理解を促進している、そして啓発も進めていくというその姿勢を示していること、それが当事者の方々に伝わることが必要だと思うので、都に限らず区としてパートナーシップ制度をつくるべきだと思いますけれども、いかがでしょうか。","respondent":"加島人権啓発課長","answer":"そのため、都制度との差別化というものを区制度に図る上で、こちらは困難であること、また、都のようなシステム構築には時間がかかることからも、都制度の活用を進めること、それが一番区民にとって利便性が高い、当事者の方の生活の不便を解消するのに近道だと考えました。","id":"exchange-161"},{"speaker":"石田委員","kind":"質問","question":"なので、区として「「条例」によって、性的マイノリティ支援を表明し、パートナーシップ制度を設けることが望ましい」というふうに報告ではあるので、そういう方向で進められるし、それこそが区としての姿勢の表明になると思うので、条例をつくっていくということが望ましいと私も思うのですけれども、都は制度の特徴が結集されているというのは分かるのですが、区の姿勢としてというところで伺っているので。","respondent":"加島人権啓発課長","answer":"区の姿勢というところですけれども、長期基本計画、それから総合実施計画等、多様性の尊重がうたわれておりまして、区としてそういったものを尊重しているという姿勢は、計画を通して区民、区内外に示されていると考えております。","id":"exchange-162"},{"speaker":"石田委員","kind":"提案","question":"それで、改めてそこを求めたいのですけれども、それとあともう一つ、区が理解促進に向けて取り組んでいることを表明するために、性的マイノリティ支援宣言として「レインボー宣言しながわ」が提案されていますけれども、これは今現在、検討はされているのでしょうか。","respondent":"加島人権啓発課長","answer":"「レインボー宣言しながわ」についての検討というところですけれども、ご提案いただきましたものは「レインボー宣言しながわ」だけではなく、様々な啓発の方向についての提言がございました。そういったものを、区としてこれから総合的に検討してまいります。","id":"exchange-163"},{"speaker":"塚本委員","kind":"質問","question":"トータルとして、令和５年度としてどれぐらいの手数料の支払いを見込んでいるのかということをお伺いします。それから、システム標準化経費ですけれども、これは、令和７年度を目指して国で進めているシステムの標準化ということで、品川区においても進められているということで、まず、令和５年度においてどこまで進捗として進める予定となっているのかということで、お伺いをいたします。","respondent":"宮澤情報推進課長","answer":"区内で活動されている方の状況というのは、区としては把握していない状況ですが、委員ご指摘のとおり、機器等に不慣れな方へのお手伝いというところでございまして、区でも独自として、高齢者のスマホ教室等を実施しているところですが、そちらの国の動きというのも注視しながら。","id":"exchange-164"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは要望です。それから、キャッシュレス決済の金額については分かりました。システム標準化経費のことにつきましては、今、令和５年度の進捗を伺いましたけれども、今後、現在、歳出で計上されている区としてのシステム維持管理費、この辺がどれぐらい軽減されていくかというところについて、現時点で分かる範囲で教えていただきたいと思います。","respondent":"宮澤情報推進課長","answer":"システム標準化の経費の削減の見込みです。正直申しまして、現在、精緻な数値というのは出せないところでございまして、国はシステム標準化の基本方針の中でも、平成３０年度比で３割程度の削減をというところを見込んでおります。","id":"exchange-165"},{"speaker":"塚本委員","kind":"質問","question":"そこで、まず、荏原の地区に旗の台と源氏前という地名がありますけれども、これについてどういう、品川区にとって源氏とのゆかりというか、この名がついた由来があるのかというのをお聞きするのと、それから、文化観光課としては、源氏とのこういうゆかりということを、いわゆる品川区の中の文化、あるいはまた観光ということまで含めて、どのように考えて。","respondent":"山崎文化スポーツ振興部長","answer":"旗岡八幡神社が源氏由来の神社なので、それの御前というようなことで認識しています。","id":"exchange-166"},{"speaker":"塚本委員","kind":"質問・要望","question":"いわゆる八幡太郎義家とかもあそこで旗を立てて、源氏前という由来になっているので、この「あつまれ！えばら」で源氏のパレード等も、ぜひこれはやれば盛り上がるのではないかなということで、ご答弁の時間がないので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-167"},{"speaker":"渡辺委員","kind":"質問","question":"１６７ページ、公有地活用検討等と指定管理者制度経費、それと、２０１ページ、ジュニアスポーツの拡大・定着プロジェクト、この２点を伺います。初めに、公有地活用検討等６,０００万円、結構な金額、これの対象が結構あるのか、複数なのか、内容、その辺のことを教えてください。この辺の内容を教えてください。","respondent":"佐藤企画調整課長","answer":"１点目の公有地活用検討等の６,０００万円に関しましては、比較的大規模な用地、旧第一日野小学校でありましたり平塚二丁目、また大小様々な用地がありますので、そういった用地に関しまして、急にボリュームチェックでありましたり。","id":"exchange-168"},{"speaker":"渡辺委員","kind":"質問","question":"願わくはそういうふうになってほしいという意味です。それと、労務環境のチェック等は、これまでやってきた中では、そのチェックで何かが判明する、それは改善すべきものだとか、そういうことはどれぐらいあったのかどうか。それと、あった場合の事例を教えてください。そういう中では、この調査項目にどんな問いがあるのか、そんなところを教えてください。","respondent":"佐藤企画調整課長","answer":"民有地の取得に関してもというご質問です。これは非常にケース・バイ・ケースでありまして、所管のほうで民有地を見つけてきたりして、直接、所管のほうで対応する場合もありますし、企画調整課にまず第一報が入ることもあります。","id":"exchange-169"},{"speaker":"渡辺委員","kind":"質問","question":"区民ニーズは高いのに、適した土地だとかがない。よくこの２３区でこんな話題が出てきたなと思いながら、やはりタイミングですよね。そういうことがありました。それと、先ほどの利用者満足度調査のところで、先ほどのチェックのところはどういう方が担っているのかだけ教えてください。恐らく労務環境であれば社労士であろうし、この利用者満足度調査はどういう方が担っているか、そこも教えてください。","respondent":"佐藤企画調整課長","answer":"しかしながら、来年度、予算書にも載せてありますけれども、公共施設等総合計画の改訂というのを予定しておりまして、その中でＰＰＰ／ＰＦＩの取組方の明記でありましたり、最新の人口動向、今後の行政ニーズ等を踏まえた計画の改訂を考えております。","id":"exchange-170"},{"speaker":"渡辺委員","kind":"質問","question":"それぞれ調査等は適した方々がやっているのだと思います。来年度から拡大の方向性を今、初めて伺いましたが、特に民間のスピード力とか企画の発想力というのは、よくどの行政でも言われていると思います。そして、今、もう念頭にあるというお話だったので、この制度を育ててほしい、進化させてほしい。それと、２０１ページのジュニアスポーツの拡大・定着も伺います。関わりが広がらないというのですかね。","respondent":"久保田企画部長、辻スポーツ推進課長","answer":"企画部におきましても、民間も含めまして、土地等が出たときにはそれぞれ精査をしながら、区の施策に活用できないかということを検討しながら進めているところでありまして、こうした姿勢を持って。スポーツ推進委員が様々活動する中で見聞きしたことから、その需要を把握することもあります。テレビやニュース等、そういったことでの話題からもニーズを把握するというような、様々な面でいろいろな興味の対象を見ているところです。","id":"exchange-171"},{"speaker":"渡辺委員","kind":"質問","question":"公有地の検討の制度の、今、見通しと決意を伺って、本当に期待していますし、本当にやりやすいように私たちも応援したいと思います。特に言いたかったのは、武道・ダンス必修化と言われて、もう早いもので１０年以上がたった中で、ブームではなくて本当に積み上がっているのではないかなと思います。特にタブレット活用などとも連携ができたら最高かなと思うのですが、その点だけ制度面で教えてください。","respondent":"辻スポーツ推進課長","answer":"そういったニーズもつかみながら、どんなジャンルのダンスがいいかとか、そのあたりのことも、地域のニーズを捉えながらいろいろな展開をしていきたいなと考えています。","id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/491981?Template=document&Id=1166#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":128793,"voices":391}},{"id":"r05-20230310-3","meetingId":"r05-c-budget","date":"2023年3月10日","dateIso":"2023-03-10","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を169件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"江野下委員","kind":"質問・要望","question":"本日も１日どうぞよろしくお願いいたします。歳入でも質問されていましたが、ヤングケアラーという社会問題に対する疑問点や課題、また、どのようにして関わっていくことが必要なのか等、ご見解をお伺いします。誰もが生きがいを感じ、自分らしく暮らしていける新時代の品川を目指し、区民アンケートも実施するのですから、ヤングケアラーに関しての項目も入れていただけるように要望します。","respondent":"染谷子ども家庭支援センター長","answer":"現状でヤングケアラーが区内でどのくらいいるかというところにつきましては、令和４年度、本年度におきまして、教員向けのアンケート調査を実施してございまして、その中で、担任をするクラスの中にヤングケアラーと思われる子どもがいるかという問いに関しまして。","id":"exchange-001"},{"speaker":"江野下委員","kind":"確認","question":"一定数やはり品川区内にもヤングケアラーの児童生徒がいるということ、確認できました。コーディネーターも設置するとお伺いしましたが、一番相談しやすいのは、学校の先生などや、周りの大人や友人だと思います。講義の中でも、子どもにとって信頼できる大人とはどんな存在か、それは定期的に会って話してくれる人だといいます。日頃、子どもと接点のないコーディネーターの役割をお知らせください。","respondent":"染谷子ども家庭支援センター長","answer":"コーディネーターの役割といたしましては、そういった関係機関が受けた相談ですとか、気づきといったものの情報を受けまして、それを基に、それぞれのご家庭の状況に応じた支援計画を検討し、また、関係機関と協力しながら。","id":"exchange-002"},{"speaker":"江野下委員","kind":"質問","question":"相談窓口にＳＮＳを活用すると伺いました。その理由と、可能であれば、区で小中学生に配付しているタブレットを活用することはできないのでしょうか。ヤングケアラーへの支援は、本人に対する支援だけではなく、その家族全体を支援していくことが重要です。ほかの関係機関など、今もご答弁いただきましたけれども、連携についてはどうお考えでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"区のほうで配付しておりますタブレットの活用につきましても、相談の入り口に、どのような媒体などのツールが活用できるかということについては、今後も積極的に検討してまいりたいと考えております。","id":"exchange-003"},{"speaker":"江野下委員","kind":"提案","question":"国のマニュアルなどというのもあるのですね。私は、ＰＴＡのときに、ゲートキーパー養成講座を受講しました。本人に自覚がなかったり、人に言いたくない、知られたくない方も多いと伺いました。ヤングケアラーをどうやって見つけていくのか。そこでご提案です。啓発や周知のためにも、区民が受講できる、ヤングケアラー支援研修みたいなものを行うのはいかがでしょうか。区のご見解をお伺いします。","respondent":"染谷子ども家庭支援センター長","answer":"地域全体で支援していくというところの姿勢という部分ですけれども、先行自治体などにおきまして、民間の団体によるヤングケアラーの学習支援等を協力しながら行っているような事例もありますので、地域で活動される団体と連携できないかといった可能性についても。","id":"exchange-004"},{"speaker":"江野下委員","kind":"質問・要望","question":"地域全体で支援していく体制を要望いたします。同じ会派の西村委員から教わったヤングケアラーの実話の記事があるのですけれども、こちら要約しますと、小学生の先生が、服装が不潔でだらしなくて好きになれない少年がいたのだそうです。本人とその家族の声を聞くしかないとは思いますが、区としても、声を聞き取り、寄り添った支援を要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問","question":"おはようあります。私からは、２２５ページ、中等度難聴児発達支援事業、２４７ページ、青少年問題協議会、２４１ページ、住宅あっせん事業、２６５ページ、私立保育園費から、時間のある限りお伺いをしていきます。最初に、中等度難聴児発達支援事業についてお伺いをいたします。この目的と、令和３年度の利用者、また、年度途中でありますが、令和４年度の利用者数をお知らせください。","respondent":"松山障害者支援課長","answer":"私から、中等度難聴児発達支援事業についての目的、実績についてご説明いたします。目的です。","id":"exchange-006"},{"speaker":"新妻委員","kind":"確認","question":"１５人、そして令和４年度は１２月までで１０人ということで利用があるということなのですが、そもそものこの利用実態の把握ですとか、この周知は、どのようにされているのか、多くの方に事業が知られていないのか、対象者があまりいないという認識でいらっしゃるのか、こういう該当者がどういうふうにいらっしゃるのかという把握をどういうふうにされているのか、お伺いをしたいと思います。","respondent":"松山障害者支援課長","answer":"補聴器を使うということまでになるかどうか、あるいは耳の大きさも成長とともに変化してまいりますので、補聴器の使用時期や調整等は、お子さんによって非常に異なるということ、必ずしも補聴器がいいというわけでもなく、成長するに当たり。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"分かりました。この事業は、平成２５年の１１月から開始した事業で、これまで要望があった中で、東京都が市区町村に対象事業として補助を行い、品川区は東京都のこの事業を活用する形で実施をしていると認識をしております。この東京都の補助金を活用するに当たっての条件ですとか、何かそういうものがあって、この１８歳未満にしているのかというところをお知らせください。","respondent":"松山障害者支援課長","answer":"東京都の条件といたしましても、同じように１８歳未満の中等度の難聴児となっておりますので、東京都の要件と同じように考えております。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"分かりました。不安を抱えているご家庭の方がいらっしゃいます。今後、また、ニーズを確認しながら、１８歳以上の対象にもこの補助金をつなげていかれるような、そういうこともぜひご検討を進めていただきたいと思います。要望として終わらせていただきます。次に、青少年問題協議会についてお伺いをいたします。この増加の要因と、今後はどのような対策を検討されているのか、お伺いいたします。","respondent":"廣田子ども育成課長","answer":"今後につきましては、警察は取り締まるというほうになってしまうのですけれども、我々青少年の健全育成の部門におきましては、青少年問題協議会は大きい情報共有の会議ですので、その下に専門委員会であるとか、また、幹事会等がございまして。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"区外の人であってもそういう行為があるということでありますので、ぜひ問題意識を持っていただきたいと思います。次に、私立保育園のおむつのことについて、お伺いをいたします。既に区立保育園では、１００％園で回収をされていると認識しておりますが、私立保育園の状況と、されていないところに対して、区の対応をお伺いいたします。","respondent":"中元保育支援課長","answer":"私立保育園での使用済みおむつの処分の状況ですが、認可保育所９８園中、持ち帰りは１園だけでございました。そのほかの家庭的保育事業等で１園、認証で１園、合計で１４５園中３園が従来どおりの持ち帰りです。","id":"exchange-010"},{"speaker":"安藤委員","kind":"確認","question":"２５５ページ、区立保育園費、区立保育園民営化について、２６５ページ、区内私立保育園経費、運営費について伺います。２月２７日、文教委員会の請願審査でこの点を伺ったところ、区は基本的に区のガイドラインに沿って進め、内容は事業者に任せる部分もあり、多少は変わることもあると。あるとしたら、どんな声で、区はどのように対応したのでしょうか、伺います。","respondent":"初貝保育教育運営担当課長","answer":"お尋ねの、民営化後の保護者からの声ですけれども、もちろん事業者のほうに、保護者の方からお声が届きましたら、速やかに保育課のほうにも連絡が来ますので、しかるべき対応をするということと、民営化後に、それぞれの園でアンケートを実施しております。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"アンケートの中に先ほど紹介したような、給食がこんなことになってしまったという声などはあったのでしょうか、伺います。","respondent":"初貝保育教育運営担当課長","answer":"アンケートの中では、今民営化しているところの中では、いろいろな項目があるのですけれども、おおむねきちんと移管をされていて、その保育の内容に関しても満足されているというような声が届いているというところです。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"ちなみに事実として、既に民営化された２園と今年４月から民営化する１園、合わせて３園のうち、２園は株式会社が選定事業者となっています。改めて、給食の質を下げない業務委託というのだったら、区立と同じメニューを実施させるべきではないでしょうか、伺いたいと思います。業務委託なわけですから。それができないなら、こうした手法はやめて直営に戻すべきではないでしょうか、伺います。","respondent":"初貝保育教育運営担当課長","answer":"今のお尋ねですけれども、もちろん給食に関しては、栄養面のバランス、そういったところも、きちんとバランスの取れた食事を提供しているというところで実施しているです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"バランスが取れていないという声も上がったということなので、少しアンケートなども取り寄せて、声も把握した上でさらに質問していきたいとは思いますが、改めて今、区立園をわざわざ民営化する方針の撤回を求めて、次の質問に移りたいと思います。私立保育園運営費への区の加算の内容というのは具体的に何か、何にどのぐらい加算しているのか、中身を伺います。","respondent":"中元保育支援課長","answer":"保育教材の充実を図るための保育教材費助成、約１億３,０００万円。延長保育を実施している保育所に対する保育士１人分の人件費相当額としての延長保育充実加算が約５億円。障害児等を有する者が在籍する保育所の運営充実を図るための特別支援保育加算が約１億５,０００万円。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"私、一般質問で、昨年に相次いだ置き去り事件が起きた背景に、低い保育士配置基準があると指摘して、保育園の区独自の保育士配置の上乗せを求めました。配置基準の検討は国の責任という説明と矛盾しているのではないでしょうか、伺います。ぜひ、国の責任だと、やらない言い訳を探すのではなく、区独自に、１歳児へのさらなる加算や、ほかの年齢児にも加算を行っていただきたいのですが、いかがでしょうか。","respondent":"中元保育支援課長","answer":"区の加算ですが、こちらは１歳児の部分に少しでも充実した保育を行っていくために、誘導するためにこの補助金の上乗せを行っているところです。国において現在も議論がされているところですので、区といたしましては、そちらの動向を注視してまいりたいと考えているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"少し矛盾しているのではないかと思うのですけれど、注視をずっとしているという答弁は少し残念です。改めて配置基準の引上げを国に求めるとともに、区も１歳児のみでなく独自に配置基準を引上げ補助することを求めますけれども、いかがでしょうか。区独自の配置の加算を行わない理由、できない理由、何かあるのか伺いたいと思います。","respondent":"中元保育支援課長","answer":"配置基準とは別の観点で、園児の安全確保に関しましては、区内の保育園につきましては送迎バス等を使っているところはないのですけれども、今回来年度の予算で、安全確保の保育支援員というものの予算を今、計上させていただいているところですので、外へお散歩に行くときとか。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"私、一般質問で、０歳児クラス、私立認可保育園がなかなか埋まらず、厳しい経営、あと安定した保育の提供のためにかなり苦労しているという私立保育園が増えているということも紹介して、目黒区で行っている０歳児未充足児童数に見合う保育士の配置に要する経費の補助を紹介し、その実施を求めましたが、ここでも区は、１歳児への区独自加算をしていますということを理由に。","respondent":"中元保育支援課長","answer":"令和５年度予算案でも、保育所において一時預かり事業を実施した場合の補助額の拡充や、小規模保育事業、認証保育所においても、空きスペースを活用した一時預かりを実施した場合の補助を行います。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"とても冷たい、ほかの区ではやっているわけです。本当に経営努力しろと、本当に冷たい答弁だと思いますけれど、ぜひ実施を改めて求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松永委員","kind":"確認","question":"私からは、２１７ページの高齢者安否確認事業のうち、長寿お祝い事業について、２３７ページの認知症高齢者支援事業について、時間がありましたら、２３９ページのグラウンドゴルフ大会について伺いたいと思います。初めに、２１７ページの高齢者安否確認事業の長寿お祝い事業について伺います。そこで伺います。来年度予算では約３,０４８万円となっており、今後も増加していくものと考えております。","respondent":"寺嶋福祉計画課長","answer":"長寿お祝い事業ですが、こちらの事業は、長寿を祝福して敬老の意を表するという目的で実施されている事業でございまして、委員ご案内のとおり、品川区の区内共通商品券を、年齢に応じて金額を設定してお渡しするという事業で、お渡しする物は、品川区からは区内共通商品券で。","id":"exchange-019"},{"speaker":"松永委員","kind":"確認","question":"そうしますと、本区におきましては、今現在８８歳、９０歳、９９歳、１００歳、そして１０１歳以上の方が対象となっており、他区も確認をさせていただいたのですが、豊島区では７７歳、８８歳、１００歳、１０１歳以上、練馬区では８８歳、９９歳、１００歳以上であり、対象年齢や祝い品につきましては様々でございました。この港区のような考えがあれば、いつ頃になるのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"今後につきましては、今の段階では高齢者数のピークが２０４０年や２０４１年頃と言われている、少なくともまだ１０年以上は人口増が続くということもありますので、一定程度、どこかでまた、判断が必要な時期が来るのかもしれませんが。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問・要望","question":"今までは、先ほどおっしゃっていましたように、もらえてうれしいという声も多かったのですが、近年では、不要なのでそのお金を福祉や子育てに使ってほしいという意見も伺っております。どうぞよろしくお願いいたします。次に、２３７ページの認知症高齢者支援事業の約２,０００万円について伺います。そして１００歳を超えた方も約９万人を超えたそうです。初めに、この認知症検診の推進について伺います。","respondent":"川原高齢者地域支援課長","answer":"委員お尋ねの認知症検診推進事業、品川区もの忘れ検診について、令和５年度の予算の概要についてご説明をします。今年度と同様に、対象の年齢は７５歳を迎える方を予定しています。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"認知症に対する意識は全国的に広まっているものと考えております。森澤区長もおっしゃっておりましたが、２０２５年には６５歳以上の５人に１人がなってしまうと言われております。そこで伺います。治療等も受けられるのかお知らせください。分かる範囲でよろしいのでお願いいたします。本区におきまして、どれくらいの方がこの認知症患者と言われてしまったのか、その件数も分かればお願いします。","respondent":"川原高齢者地域支援課長","answer":"クリニックで、そのままかかりつけ医として、お医者様の診断の下、投薬治療を開始された方もいらっしゃれば、在宅介護支援センターに情報提供をして、引き続き、ご家庭での支援も含めてご相談に乗っていただいたり、さらには認知症疾患医療センターという。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"このもの忘れ検診というのはとても大切だと考えています。早期発見、早期治療がとても大切なので、ぜひ進めていただければと考えています。続きまして、認知症の理解について伺いたいと思います。この修了された方については、例えば、免許のように更新をされるのか、それともまた新たにステップアップ、いわゆるスキルアップをするような項目等というのはあるのでしょうか、お知らせください。","respondent":"川原高齢者地域支援課長","answer":"認知症サポーター企画会議というものは、サポーターとして実際にどういったことができるかというものを話し合ってくださったり、あとは認知症の方の心理状況を把握するために、認知症の方の気持ち、心を理解していこうという。","id":"exchange-023"},{"speaker":"澤田委員","kind":"質問","question":"本日は、２４３ページ、子育て支援情報発信アプリ運用等、２６４ページ、２６５ページ、第３款民生費、第２項児童福祉費、第６目保育支援費についてお伺いします。品川区には、子育て支援情報発信アプリとしてしながわパパママ応援アプリがあると思いますが、アプリのダウンロード数は把握されているのでしょうか、また、どのような周知活動をされているのでしょうか、お知らせください。","respondent":"廣田子ども育成課長","answer":"アプリについてです。今現在のダウンロード数が２万１,９９０件というふうに把握しております。","id":"exchange-024"},{"speaker":"澤田委員","kind":"質問","question":"ＱＲコードを様々な紙媒体などに使っているということですけれども、ぜひ区役所の子ども支援に関係するような窓口に小さなパネルなどを置いて、気になった方、関心を持った方がすぐダウンロードできるように、さらに取り組んでいただくなどというのはいかがでしょうか。区の見解をお聞かせください。","respondent":"廣田子ども育成課長","answer":"ご提案の内容につきまして、これからアプリをリニューアルしますので、今ダウンロードするとまた、リニューアルになりますので、新しいアプリのときに周知のところで参考にさせていただこうかと思います。","id":"exchange-025"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。これから子どもを出産する世代にとっては、紙媒体よりスマホで情報を受け取る機会が多いと考えられますので、ぜひ、多くの方がアプリを活用し、しっかりと支援の情報を受け取っていただくためにも、しながわパパママ応援アプリのより一層のブラッシュアップを、改善を要望いたします。","respondent":"廣田子ども育成課長","answer":"令和５年度に、アプリのリニューアルを考えておりまして、令和５年１０月頃にできたらいいなと準備をしているところなのですが、今、ほかの区のアプリの状況なども検証しているところですので、委員ご提案の内容も含めまして、取り組ませていただこうと考えています。","id":"exchange-026"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ、ご検討と研究のほう、よろしくお願いいたします。一方で、支援が充実しているがゆえに、ホームページで探そうにもなかなか求めている支援にたどり着けない、求めていた支援があることすら知らなかったというお声もありますので、ぜひアプリのさらなる改善、ブラッシュアップを要望して次の質問に参ります。現在の私立幼稚園の介助員の予算は、どの事業に計上されているのでしょうか、お知らせください。","respondent":"中元保育支援課長","answer":"私立幼稚園の介助員の予算ですが、２６９ページの中ほどから下のところに、私立幼稚園費とございまして、そこの私立幼稚園経費の中に、私立幼稚園振興費等補助金がございまして、その中に計上しています。","id":"exchange-027"},{"speaker":"澤田委員","kind":"質問・要望","question":"私立幼稚園振興費等補助金に含まれるとのことですが、先日、私立幼稚園から介助員の補助額が少ないとお聞きしました。特別な支援を必要としている児童にとって、安全面でも精神的な安定を保つ上でも、介助員は大変重要です。特別支援を要する児童を受け入れている私立幼稚園に対して、補助金の拡充を要望いたします。区の見解をお聞かせください。","respondent":"中元保育支援課長","answer":"私立幼稚園協会からのご要望により何度か、これまでも拡充を行ってきているものでございまして、来年度につきましても、対象園児数の増加を見込みまして、２０人分の予算を計上しておりましたものを来年度は２５人分ということで、区としましても増額を見込んでおります。","id":"exchange-028"},{"speaker":"澤田委員","kind":"質問","question":"都の補助金もあるとのことですが、ぜひ区としても、さらなる補助の拡充のほう、よろしくお願いいたします。次に、同じ２６５ページの特別支援巡回相談についてお伺いします。特別支援巡回相談事業の、区立幼稚園、区立保育園、私立幼稚園、私立保育園、それぞれの実施の状況をお知らせください。","respondent":"初貝保育教育運営担当課長、中元保育支援課長","answer":"この事業の目的としましては、嘱託医および臨床発達心理士、学校心理士が巡回をして、特別支援児に対する保育の仕方や、保育士としての対応の留意点等々を助言したり、園長ならびに保育士からの質問や相談に応じているという事業です。私立保育園における１月末の実績ですが、臨床発達心理士によるものが認可保育園で１６０回、地域型保育事業で５回、認証保育園で１１回です。学校心理士の巡回相談が認可保育園で６０回の実績となっています。","id":"exchange-029"},{"speaker":"澤田委員","kind":"質問・要望","question":"今後は区立小学校のように、専門家、教諭、保護者の３者間で、特別支援の必要な子どもについて情報を共有し、その保育教育について相談できる、話し合う場や仕組みの持てる環境のためにも、ぜひキンダーカウンセラーの配置を要望いたします。しかし、人材や費用面での課題も大きいかと思いますので、まず、オンラインで取り入れるのはいかがでしょうか。伺います。","respondent":"松山障害者支援課長","answer":"巡回相談は、保育所からの申請に基づき行っているものでして、保育所等訪問支援については、保護者からの申請に基づき行っております。まだ少し周知が不足しておりますので、今後、様々な媒体を通じて周知をし、使っていただくよう促してまいります。","id":"exchange-030"},{"speaker":"いながき委員","kind":"提案","question":"在宅介護支援センターについてお尋ねします。在宅介護支援センターの名称を、地域包括支援センターに変更しない理由は何でしょうか。なので、お尋ねをします。お尋ねは、２０件ある在宅介護支援センターの常駐の方の人数、職種を教えてください。各地域の在宅介護支援センターの機能も併せてお尋ねします。こういったものも、ぜひ品川区でも取り入れてほしいなという、最後の１つは提案です。","respondent":"菅野高齢者福祉課長","answer":"その際に、区では、区民になれ親しんでもらった在宅介護支援センターの看板をそのままにして、そこに地域包括支援センターの機能も加えて、様々な相談に対応できる体制と、きめ細やかな仕組みとしたという経緯がありますので、地域の高齢者の方たち、名前が変わってしまうと。","id":"exchange-031"},{"speaker":"いながき委員","kind":"質問・要望","question":"厚労省の、地域包括支援センターの設置運営についてを見ると、センターには、包括的支援事業を適切に実施するため、原則として保健師、社会福祉士、主任介護支援専門員、いわゆる主任ケアマネを置くこととするとあるのですけれども、これ、今お尋ねをした人数で、これは３職種、各センターに１人ずつ、都合３人置くという意味ですか、それとも、１つのセンターに１人いればいいということでしょうか。","respondent":"菅野高齢者福祉課長","answer":"専門職の配置人数のお尋ねです。こちら、人口３,０００人以上６,０００人未満で、主任ケアマネ、保健師、あと、社会福祉士、１人ずつ置くということになっておりますので、おおむね区では、６,０００人当たりにその職種が１人ずつということの配置になっております。","id":"exchange-032"},{"speaker":"いながき委員","kind":"提案","question":"高齢者福祉施設設備費、これはご提案です。そのための仕組みづくりとして、例えば、富山県砺波市にある、ものがたりの郷のような、一人一人の人生、物語を大切にした、家庭のような、終末期の医療を中心とした施設、まちづくりのモデルケースをつくるのはいかがでしょうか。ケアマネ１人当たりが抱える高齢者の人数は何人ですか。自宅で暮らしている高齢者の様子を見に行く頻度は何回ぐらいでしょうか。","respondent":"菅野高齢者福祉課長","answer":"担当の利用者に対して、ケアプランを作成しまして、おおむね１か月に１回、そちらのお宅に訪問して、モニタリングをして、状況を確認するということになっておりますので、委員お尋ねの該当者につきましては。","id":"exchange-033"},{"speaker":"いながき委員","kind":"質問","question":"北品川高齢者多世代交流支援施設に関してお尋ねをします。この多世代交流支援施設という名前のとおり、子どもや若者、高齢者、それぞれの世代がきちんと交流できる、どうしても世代間で少し差が出てしまうというようなことが起きないような配慮、施策はどういったことがありますでしょうか。もともとの趣旨である多世代交流、いわゆるごちゃ混ぜの施設にしてほしいなと思うのですが、伺います。","respondent":"川原高齢者地域支援課長","answer":"そこは、ベビーカーですとか、シルバーカーなども入れるような、間取りを広く取ってございまして、道路から中身が見えるような形でどなたでもお訪ね、お気軽にどうぞという雰囲気を出したいというところをまず、第一に考えてあります。","id":"exchange-034"},{"speaker":"いながき委員","kind":"質問・要望","question":"いわゆる、ごちゃ混ぜ施設、多世代が交流できるゴジカラ村のようなごちゃ混ぜの施設になってほしいなと思っています。要望をして終わります。次に、障害者理解・普及啓発事業に関連しお尋ねします。その区民から、この協議会に対し、当該区民の相談事例は資料だけでも協議会ホームページに載せてほしいと言っています。何かそういったことはできますでしょうか。そこで、その見解を伺います。","respondent":"川崎障害者施策推進課長","answer":"今、相談事例等を蓄積して、来年度、令和５年度に向けて、この体制を広めて、どのように相談の仕組みをつくっていくか、そこを検討している最中ではありますので、また、こちら側の委員長等と、ホームページも含めて公開のところも含めて、検討はしてまいります。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"２１７ページ、重層的支援体制、２２１ページ、グループホーム、２３５ページ、福祉人材確保、２３９ページ、高齢者クラブ。委員長に許可をいただいたので、しながわふれあいメッセージ作品集というのを読ませていただきました。この作品集の発表会があったと伺っていますが、どういう状況だったか教えてください。","respondent":"菅野高齢者福祉課長","answer":"その中から、金賞、銀賞、銅賞、在宅サービス特別賞、入所サービス特別賞を選考させていただきまして、そちらの、メッセージを送った方と、メッセージを送られた事業所の方を対象に、表彰式を実施させていただきました。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"目的等、これ読めば分かりますので、どういう状況だったのですかと。利用者と、そして介護してくださる方がどういう感じだったかということを伺いたかったのです。それで、私、ひとつ読みますね。「毎日決まった時間に訪問してくれるヘルパーさん。だから毎回訴えているのです。介護士、介護福祉従事者の方々の給料を、行政の力で少しでも上げてあげることというのはできないでしょうか。答弁をお願いします。","respondent":"菅野高齢者福祉課長","answer":"ただ、実情では事業所ごとにいろいろと差があるのかなというところで、今後そういったお声を聞きながら、区内の事業所が少しでもサービスが継続できて、サービス提供できるように支援していかなくてはいけないと感じているところです。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問・要望","question":"いつもこの答弁、私が質問すると、介護保険制度、私も調べました。もう１回言います。それで、今、直接伺うと改善されていないのです。だから、もう申請するならば事務的に複雑で大変だから、要らないというふうに、求めないところもあるし、この申請をすると、事業者も含めて、事務的手続が増えてしまうからということで我慢してしまうところもあるのです。その辺についていかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"区独自の支援金等ができないかというお話についてです。こちらについては、２３区の中でというお話でしたが、ある区でそういうことをやっているというのは私もお聞きしております。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"そういう事務的手続が増えると、区の職員の方も本当に大変だと思います。職員の方、介護従事者の方、本当に今精いっぱい、目いっぱいやってくださっているというのは分かっているのです。本当に分かっているのです。でも、この方がお話ししているではないですか。ヘルパーの手を借りないと生きていけないのです。私はそう思っている。だから分かっていただきたいと思います。その点についても伺います。","respondent":"菅野高齢者福祉課長","answer":"ふれあいメッセージ、取り上げていただきまして、どうもありがとうあります。介護サービスの仕事は、人と人との対面の仕事であるということで、今ＤＸ化が進められている中で、なかなかそういった部分については難しいというところは認識しております。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"課長の発表会みたいで、本当にありがとうあります。熱き思いがよく分かりました。はもう、この辺の施策に関しては、今、財源がとおっしゃったけれど、品川区財源あるではないですか。今日は聞きません。２００名分整備を目標にと。私が伺うのは、この手を挙げてくれる事業者自体あるのですか。数少ないと伺っています。人材をどう確保するかです、そうですよね。その辺については、いかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"グループホームの整備について、あと人材確保という面についてのご質問ですが、まず、区としても、令和５年度の施政方針にありましたように、区有地、都有地、そして民有地の活用に向けた情報収集に努めております。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問・要望","question":"グループホームは直近の課題ですよね。そこを頭に入れておいていただきたいのが一つ。それと、高齢者クラブについてお伺いしますけれども、高齢者クラブ、私はすばらしいクラブだと思っています。その辺の分析、そしてこれからの課題、そういう点についてお伺いします。その中において、もうどんどん具体的に動いていっていただきたいと思っているのですけれども、態勢的にはどうなっているのでしょうか。","respondent":"川原高齢者地域支援課長、寺嶋福祉計画課長","answer":"は新規の高齢者の方の加入については、どうしてもお仕事の定年が延長されていることもあって、日中なかなか参加するのが難しいというところを挙げられておりますので、そういったところで。重層的支援体制整備事業ですけれども、昨年度プレス発表させていただきまして、３か年の移行準備事業ということで国の補助対象にもなっているのですけれども、現在鋭意進めているところで、目標としては。","id":"exchange-041"},{"speaker":"芹澤委員","kind":"提案","question":"２５５ページの養育費相談支援事業、あとは２３１ページの超短時間就労についてお伺いをします。養育費支援についてお伺いをします。後追いになりますが、３年前に、決算特別委員会の中で、我が会派から、養育費の支援を区が独自でしたらいいのではないかというような提案をさせていただいて、翌年から実施をしていただいていると認識をしています。","respondent":"飛田子育て応援課長","answer":"そういうところで、丁寧に対応していきたいと思います。来年度も、相談員を配置しまして、そういう相談に丁寧に応じていきたいと考えております。","id":"exchange-042"},{"speaker":"芹澤委員","kind":"質問","question":"それを区がわざわざ排除することはないのではないですかというようなお話をさせていただきました。これを上げていくためには、やはり今の制度を変えていって、品川区では、統計よりも高く受給率があるという状況を目指すべきだと思うのですが、もう一度ご見解をお聞かせください。","respondent":"飛田子育て応援課長","answer":"国とのそういう補助等ありますが、そういうところはまた、いろいろ相談を受けながら、どういうふうにしていったらいいか、また、そういうところは検証していきたいと考えております。","id":"exchange-043"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ぜひ前向きにご検討いただきたいと思います。この予算があるうちに始めていかないと、多分どんどん縮小化してしまうのではないかと思っています。大体月額で４万円ぐらいの相場だと伺っていますけれども、年間にすると約５０万円。毎年、区の補助なしに入るようになる仕組みができるわけですから、ぜひこれは前向きに乗り出していただきたいと思いますが、最後ご見解をお聞かせください。","respondent":"飛田子育て応援課長","answer":"そういうところで、相談等に応じまして、今後の施策に生かしていければと考えております。","id":"exchange-044"},{"speaker":"芹澤委員","kind":"質問・要望","question":"それで実際メニューを見てみたら、いや、これだったらやらないよという方が、残念ながらいるのだと私は思っていて、それが、離婚を考えている方もしくは離婚をした方が、こんなメニューがあったのだ、ぜひやりたいな、というふうに思えるような制度の設計をしていただきたいということで、これは要望で終わります。超短時間就労についてお伺いをします。","respondent":"松山障害者支援課長","answer":"特に民間だけという形で限定しているものではございませんで、これから東京大学の近藤先生を中心にノウハウをいただきながら、区内の就労環境の分析に当たるです。区内、区外とも、今のところ想定しておりますので、特に限定して民間だけということではございません。","id":"exchange-045"},{"speaker":"芹澤委員","kind":"提案","question":"その際に、せっかく業務を切り出した企業の方々が、その情報を無駄にすることなく、例えば、先ほどのひとり親家庭の就労に生かせないかとか、場合によってはシルバー人材センターで使えないかとか、そういった横の展開、連携というのもご提案しますが、ご見解をお聞かせください。","respondent":"松山障害者支援課長","answer":"多様な仕事の切り出しのときの対応についてお答え申し上げます。確かにおっしゃるとおり、マッチングによっては難しい場合もあります。障害者の方だけに特化できない場合もありますので、そこら辺は柔軟に考えていくしかないかなと思っています。","id":"exchange-046"},{"speaker":"せらく委員","kind":"質問","question":"区立保育園の電子化推進経費について、こちらプレス発表にありました保育園業務支援システムの導入の部分に当たりますでしょうか。先日の一般質問でも、保育園の人手不足にはＩＣＴを活用していく研究をするというご答弁があったことが印象に残っています。こちらについては、どのような形でＩＣＴ化をしていくというようにお考えか、連絡アプリでということですが、具体的に教えてください。","respondent":"初貝保育教育運営担当課長","answer":"今ご質問いただきました、保育園のＩＣＴ導入のところです。こちらの事業は、品川区の区立保育園の中で、保育園業務支援システムというものを導入しようというところで、今ご提案させていただいているところです。","id":"exchange-047"},{"speaker":"せらく委員","kind":"質問","question":"私の子どもが通う保育園では、入退室と連絡帳アプリはそれぞれ別のシステムで既存にあったところなのですが、そちらと、例えば一体にするということはお考えでしょうか。教えてください。","respondent":"初貝保育教育運営担当課長","answer":"今想定しているところといたしましては、来年度、保護者への連絡等々と、記録の一元管理を予定しております。","id":"exchange-048"},{"speaker":"せらく委員","kind":"意見","question":"保育士の日誌をはじめとした、書類もペーパーレスにするということだと思うのですけれども、日々の保育の記録、日誌なりを入力する端末は、例えばクラスに１台など、どのように確保するように想定をしていらっしゃいますか。","respondent":"初貝保育教育運営担当課長","answer":"端末のお話ですけれども、端末は、現在園でも使える端末を配備しています。そちらをまずは活用して、入力をするというような形で考えております。","id":"exchange-049"},{"speaker":"せらく委員","kind":"質問","question":"その端末は保育園に１台あって、例えば入力するにしても、各クラスで保育士が紙などにまとめて、それを保育時間が終わった後などに時間を確保して、入力していくという形になるのでしょうか。分かれば教えてください。","respondent":"立木保育課長","answer":"保育園では、２人に１台ずつは必ずあるようになっていまして、順次１人１台ずつ使えるような形で、配分調整をかけているようなところです。","id":"exchange-050"},{"speaker":"せらく委員","kind":"確認","question":"今２人に１台で、今後１人に１台ということで理解いたしました。例えば、園児のお昼寝中は、遊び保育はなくなりますが、寝姿勢や呼吸の確認などをひっきりなしに行っているので、気が抜けないと思います。安心・安全な保育環境のサポートで、お昼寝のＡＩカメラなどといったツールもありますが、こういったツールを補助的に利用することについて、区のお考えをお聞かせください。","respondent":"初貝保育教育運営担当課長","answer":"今ご提案いただきましたＩＣＴの活用に関しましては、そういったＡＩカメラのサービス以外にも様々今出てきておりますので、保育の質の向上というところを含めて、今後さらなる情報収集を進めてまいりたいと考えております。","id":"exchange-051"},{"speaker":"せらく委員","kind":"質問・要望","question":"おむつのサブスクリプションについて、次に伺いたいと思うのですけれども、区立保育園でモデル実施すると、昨年区長のご答弁があったと思います。私も前回の決算特別委員会の中で、導入を要望させていただいていたので、前進をするということをすごくうれしく思っています。前回課題として上がっていた費用面、保管場所、メーカーについては、現状どのようにお考えでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"今ご質問いただいた場所でありましたり、費用面に関しましては、基本的には保護者負担というところになりますけれども、その他の課題についても今整理して、スタートに向けて準備をしています。","id":"exchange-052"},{"speaker":"せらく委員","kind":"質問・要望","question":"毎日のおむつへの記名や、保育園でおむつの在庫管理、補充がなくなるわけなので、特に週の初めの月曜日は、そのほかの荷物も多いですから、助かると思う人は多いのではないでしょうか。次に、第２子以降の保育料について、認証保育所の助成の拡充に関して伺います。私立幼稚園においての第２子、第３子への保育料、預かり保育の完全無償化についてはいかがでしょうか。区のお考えをお聞かせください。","respondent":"中元保育支援課長","answer":"実際には給食費であるとか、入園料という部分はご負担をいただいているのですけれども、その辺のところで、周辺区の状況等も見ながら、どのような形でほかの区が助成制度を設けているのかなども調査研究してまいりたいと考えているところです。","id":"exchange-053"},{"speaker":"せらく委員","kind":"質問","question":"どのような家庭でも、子どもを望むことを諦めてほしくないという思いです。次に、より安全・安心な保育環境を目指して、保育人材の確保の取組や、安全装置の導入支援について伺います。私立幼稚園の保育支援員の雇用費補助が新規事業として発表されていますが、現在の支援員の状況について伺います。今回の事業で、支援員の配置、どういったところで変化があるか教えてください。","respondent":"中元保育支援課長","answer":"現状ですけれども、プールやお散歩時の配置人数は、年齢別の配置基準を総数で守ること、また、各組、各グループに常勤の保育士が１名以上配置されていることをルールとして、各私立保育園で遵守して実施していますが、区としましても体制を一層支援するということで。","id":"exchange-054"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。さらなる拡充ということで、より安全・安心な保育環境になるかと思います。保育支援員補助の部分で、こちらもすみません、幼稚園のほうになってしまうのですけれども、幼稚園の預かり保育について伺いたいと思いますが、まず、幼稚園は先生１人に対して児童数も多いと思います。通常保育時と預かり保育時での先生に対する児童の数、また、交代や補助者の体制を伺いたいと思います。","respondent":"中元保育支援課長","answer":"預かり保育の時間帯は、当然３５名より少ない人数でのお預かりと実際なってありますので、そちらにつきましても、幼稚園教諭の方お一人という形で配置をしているものです。","id":"exchange-055"},{"speaker":"せらく委員","kind":"質問","question":"幼稚園だと３歳から５歳児が中心になると思いますが、保育園と比べても児童の人数も多いので、事故防止や先生１人の負担を思うと、追加の支援員の役割が重要だと考えます。私立幼稚園での預かり保育での補助支援員についてのお考えを伺います。","respondent":"中元保育支援課長","answer":"私立幼稚園における保育事業に関しましては、支援員という形ではなく、各私立幼稚園で事業費として設定しています。その事業費の中に人件費も入ってあります。","id":"exchange-056"},{"speaker":"せらく委員","kind":"質問","question":"ありがとうございました。こちらは今回の予算特別委員会でも既に質疑応答されている部分ですが、こちら国のモデル事業の活用ということで、これから実施する保育園の選定をする対象のお子さんは、保育園などに通っていない、子育て環境に不安がある、または心配がある方にご案内をしていき、週に一、二回預かりというケースを想定していることと伺いました。教えてください。","respondent":"中元保育支援課長","answer":"園で用意するものにつきましては、従来お渡ししている保育園の運営費でありますとか、今回の予算で計上しているものの中からお渡ししたお金で、園で用意していただくということで考えております。","id":"exchange-057"},{"speaker":"せらく委員","kind":"質問・要望","question":"持ち物や園での生活など、いろいろ対象になったお子さんのご家庭では情報が少ない方もいらっしゃると思うので、お子さん、親御さんともに、しっかりケアしていただきたいです。最後に、出産育児一時金について伺います。出産育児一時金が５０万円に引き上げられ、そこに加えて、都でも応援ギフトが配布されて、品川区でも５万円ずつギフトが配布されます。改めてこちらについて伺えますか。","respondent":"池田国保医療年金課長","answer":"出産育児一時金につきましては、国民健康保険の部分では４２万円から５０万円にということで、４月１日から改正する予定になってあります。","id":"exchange-058"},{"speaker":"せらく委員","kind":"質問・要望","question":"では一言だけ、最後に申させていただきたいと思います。実際に私が出産した際は、６５万円以上かかりました。病院選びのときに比べていたもう一つの病院は、７４万円以上するということでした。加えて出産の予約もしづらく、ちょっと民生費から離れてしまうのですけれども、健診のときも毎回５,０００円ぐらい、検査をする日は１万円から２万円ほど、毎回お支払いしていました。これで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、２４９ページ、児童相談事業、児童相談所移管推進事業、２５９ページ、のびしなプロフェッショナルスクール、２６５ページ、児童の安全確保支援事業、時間がありましたら、２１９ページの障害者施策推進経費と、２２１ページ、権利擁護支援事業、２３７ページ、介護施設高齢者虐待防止等研修についてお伺いいたします。１点目に児童相談事業、児童相談所移管推進事業についてお伺いをいたします。","respondent":"長谷川児童相談所移管担当課長","answer":"児童相談所としましては、通告に基づき対応する機関となりますので、要保護児童地域対策協議会等の場を活用して、しっかりと情報把握に努めてまいります。","id":"exchange-060"},{"speaker":"横山委員","kind":"質問・要望","question":"児童相談所の開設に向けて、準備をどうぞよろしくお願いいたします。２点目に、のびしなプロフェッショナルスクール、児童の安全確保支援事業についてお伺いいたします。最新の事故予防に関する研修を受講いただいて、情報を整理した上で、現場とメディアとの情報共有を進めていただきたいと要望いたしますが、区のお考えをお聞かせください。","respondent":"中元保育支援課長","answer":"テレビ、新聞、ＳＮＳ等のメディアにより、様々な情報を取得し、お子様の安全についての啓発が行われることは望ましいと考えています。国や都からも、例えば節分の季節には子どもの誤飲防止の注意喚起の文書が出されてあります。","id":"exchange-061"},{"speaker":"横山委員","kind":"質問・要望","question":"記者のお話では、ぜひ現場の先生方からも、事故に対してのことを教えていただきたいというお話がありました。３点目に、介護施設高齢者虐待防止等研修について、また、障害者施策推進経費、権利擁護支援事業、障害者虐待防止対策費、障害者理解・普及啓発事業についてお伺いをいたします。以前よりも優先順位をもう１段階上げていく必要性があるかと思いますが、区のお考えをお聞かせください。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"今年度におきましては、虐待の中でも一番多いと課題となっております、身体拘束廃止研修について、施設長と従事職員と２回に分けまして、研修等も実施させていただいている次第です。今はコロナ禍で中止になっておりますが、また再開したいと考えています。次に、障害者理解・普及啓発のもう１段階です。講演会のほか、手話理解普及啓発についても、来年度ぐるっぽで実施する予定です。","id":"exchange-062"},{"speaker":"横山委員","kind":"質問・要望","question":"研修の実施等が、この間とても厳しかったと考えています。区内のコミュニケーションも難しい状況が続いておりました。引き続き進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"松澤委員","kind":"質問","question":"私からは、予算書の２３７ページ、認知症高齢者支援事業についてお聞きいたします。は昨年度の決算特別委員会で質問しました、「品川“くるみ”認知症ガイド」の再編集についてお聞きいたします。「品川“くるみ”認知症ガイド」の再編集、これはどのような計画で進んでいるのか、今お答えできる範囲で教えてください。","respondent":"川原高齢者地域支援課長","answer":"検討会議の参加予定者については、現在検討の段階ではありますが、認知症サポーターの講座の講師等をしてくださっている認知症地域支援推進員のほか、認知症のご本人と、そのご家族にもお声かけを行いまして、当事者の目線を踏まえた、高齢者の皆様にも分かりやすく。","id":"exchange-064"},{"speaker":"松澤委員","kind":"質問","question":"要は「品川“くるみ”認知症ガイド」が基盤になるわけですから、すばらしい冊子になることをお祈りしております。次に、プレス発表の認知症予防の取組の強化についてお聞きいたします。４,９６２人中、２４６人受診があった、そのうちの５４人を支援につなぐことができたというお話は伺いました。来年度拡充していくでしょうけれども、どのように拡充していくのか、細かく教えてください。","respondent":"川原高齢者地域支援課長","answer":"１点目が、検診はしたものの、その後クリニックにどうしても受診をしたくない、お医者様をお嫌いになられる方が一定数いらっしゃるということが分かりましたので、今後におきましては、訪問看護ステーションとの連携を考えてございまして。","id":"exchange-065"},{"speaker":"松澤委員","kind":"質問","question":"専門医に受診だと１５か所ですが、相談員の資格がある先生が９０名前後いらっしゃるということですね。やはり受けてもらうには、先ほど課長もおっしゃいましたけれども、壁があると思っていますので、区のほうで何か受診につながる取組ですか、そういったお考え、先ほど少しお話ししていただきましたが、まだ心がけていくというか、さらに進めていくと、そのようなお考えを教えてください。","respondent":"川原高齢者地域支援課長","answer":"日頃から認知症を身近なものと捉えていただくように、どなたでも訪れることのできる、今、区内に認知症カフェがありますので、そういった認知症カフェでもの忘れ検診の情報発信を行うなど、様々な場での広報の活動を実施してまいりたいと考えています。","id":"exchange-066"},{"speaker":"松澤委員","kind":"質問","question":"今課長から少しお話も出ましたけれども、私もかかりつけ医というのですか、私は病院にあまりかからない、丈夫に生んでいただいたのでかからないのですが、医者の発言力というのですか、例えば私も会派の鈴木博ドクターが言うと、ああ、そうなんだと信じてしまう部分があります。それについてご見解をお聞かせください。","respondent":"川原高齢者地域支援課長","answer":"認知症検診に限らず、日頃の町場のドクターからのお声かけの後押しというご質問です。その辺りにつきましては、引き続き品川と荏原の両医師会にご相談をさせていただいて、お声かけを図っていただくようにお願いをしてまいりたいと考えています。","id":"exchange-067"},{"speaker":"松澤委員","kind":"質問","question":"しっかりしたお声がけで、このすばらしい取組がもっともっと広がるように期待しております。次に、新規事業になります、絵本の読み聞かせについてお聞きいたします。子どもたちとの接点をつなぐということは、本当にすてきな取組かなと思っています。そこで、例えば、どこでこのような取組を開催していくのか、また、読み聞かせをすることによって何が分かるのか、詳しく教えてください。","respondent":"川原高齢者地域支援課長","answer":"令和５年度、新規に始まります認知症予防を目的とした絵本読み聞かせ講座の開催場所ですが、こちらは荏原文化センターでの開催を予定しています。年に２回、ワンクール３か月、計１８回の講座を６月と１０月の開催という形で現在考えているところです。","id":"exchange-068"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、２３９ページ、補聴器購入費助成事業、２４９ページ、ファミリーサポートセンター運営費について伺っていきます。昨年６月、私ども公明党の一般質問で、認知症予防、そして専門機関、業界団体とも連携し、補聴器の有効性を確保した上で、金額ありきではなくて、お金ありきではなくて、補聴器購入費の助成制度の導入を求めました。そして、今回の予算案に計上されたという認識です。","respondent":"川原高齢者地域支援課長","answer":"具体的には、助成開始まで期間を設けている理由としては、普及啓発をしっかりすることと区民に耳の聞こえについて関心を持っていただくこと、耳の聞こえに少しでも疑問を感じたら、耳鼻科の専門医を受診していただくということをより意識していただきたいということで。","id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはりこの件に関してはお問合せをかなりいただいておりまして、ご自身が対象と思われる区民の方は、７月以降どのような手順を踏めばよいのでしょうか。今回住民税本人非課税という条件が付されました。こうした段階においては、こうしたことについては、また対象者の拡大も視野に入れていただきたいと、これが私どもの考えですが、その辺りのご見解を伺わせていただければと思います。","respondent":"川原高齢者地域支援課長","answer":"購入後、その購入した証明書をもって助成をするという予定を考えてあります。次に、周知についてのお話です。","id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問","question":"大井ファミリーサポートセンターにおいては、社会福祉協議会が運用しているので、同じ建物ですから民生委員や成年後見センターがあって、様々な関係で区民の出入りが多いために、比較的いろいろな方に声がかけやすくて、提供会員が集まりやすいという話も伺いました。この辺り、２つのファミリーサポートセンターの提供会員、依頼会員数の比較などの事実関係、そして区の認識を伺いたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"それぞれの提供会員に対して、施設の特性で集まりやすい区民の出入りというお話の部分もございましたけれども、併せて、それぞれ行っている広報や周知活動など、そういった部分などについて違いがないのかですとか、そういった要因の部分も含めて。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"課題の今後の検討というお話もありましたが、何年も区議会での議論で、このミスマッチ、はっきり言ってしまうと、この提供会員、今２つのところを合わせると４２４人と。最後に、来年、もしこの予算特別委員会において、こういった改善ができました、そう簡単には改善はできないと思いますけれども、ぜひそういったご答弁をいただきたいなと思うのですが、お考えを伺いたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"援助活動に関する報酬額の増額以外にも、取り組める方法がないかというところにつきましても、委託事業者に現状を確認しつつ、検討できればと考えているところです。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今のご答弁の中で事業者にというお話もあったのですけれども、やはりこのミスマッチの解消というものは、もう事業ができているわけですから、構築されてしまっているので、これをやってくださいというものが事業者なので、それを事業者が解決をするということはなかなか難しいので、根本的に見直していただきたいということが今日の質問の趣旨ですが、最後のご答弁をお願いして終わります。","respondent":"染谷子ども家庭支援センター長","answer":"委託事業ということで、区として実施している事業ですので、委託事業者と状況を確認させていただき、また協議させていただきたいとは思いますけれども、区として実施する事業として見直しができないかというところについては、検討させていただきたいと思います。","id":"exchange-073"},{"speaker":"おくの委員","kind":"質問","question":"そこで伺います。かつての返還免除がなかった時代の区の奨学金貸付制度によって奨学金を借り受けて、返済の終わっていない方は今何人いらっしゃるでしょうか。そして、その貸付けの合計額は、今どのくらいになるのでしょうか。返済が滞っている方もいらっしゃると聞きましたけれども、どのような理由でできなくなっているのでしょうか。この点伺います。","respondent":"飛田子育て応援課長","answer":"合計金額は約６,３００万円、そのうち滞納されている方は８７人おりまして、合計が約１,８００万円ほどとなっております。返済できない理由としましては、失業とか、ご病気、また多重債務が原因で、なかなか払うことが難しいという声も聞いております。","id":"exchange-074"},{"speaker":"おくの委員","kind":"質問","question":"そこで伺いますが、返済ができないほど生活に困っているような方には、返還を全部あるいは一部免除してはいかがでしょうか。それならば、今問題にしている奨学金の返還は、かつての制度によるものなのですけれども、今の制度に合わせて免除してほしいと私は思うのですが、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"そういった過去、また、今ももちろん返済をしている方もいますので、そのような方の公平性等も考えると、免除は非常に難しいと考えております。やむを得ない事情のある方には、お話を聞きながら、延納や、またさらに分割をするなど、柔軟な対応を行って返済をお願いしています。","id":"exchange-075"},{"speaker":"おくの委員","kind":"質問","question":"公平性を考えるということでしたけれども、公平性ということを言い出したら、制度の改善ができないと思うのです。私が今言いましたような免除を認めるということは、例えば国際人権規約のＡ規約、よく持ち出されますけれども、第１３条２項（ｂ）で、中等教育は、日本の高校教育ですね。このような日本政府が１１年前に留保を撤回して批准しております。そこでさらに伺います。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"おくの委員","kind":"質問","question":"私としては、趣旨を活かして無償教育へ一歩近づいていってほしいと考えています。日本政府は、先ほど申しましたように、１１年前に留保を撤回して、批准したというところです。そうしますと、やはりそのような前提である以上、私は、高校生のみならず、大学生に対しても給付制奨学金制度を設けることを考えていくべきではないかと思うのですけれども、その点いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"区としては、現段階としましては、区独自の大学生向けの奨学金を実施する予定はございませんが、今後とも、国が実施している様々な支援策の動向などを注視してまいりたいと考えています。","id":"exchange-077"},{"speaker":"おくの委員","kind":"質問・要望","question":"これはもう非常に強く求められているあかしではないかと私は思うのです。これがなぜ品川区では実施ができないのでしょうか。それともう一つ、国に制度があるということで、品川区は設けていないのだというようなお答えだったと思いますけれども、品川区の考えとして、国の制度で十分だと考えていらっしゃるのでしょうか。私は不十分だと思っているのですけれども、その点いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"そのようなところでは、区独自、また単費で実施することはまだまだ課題は多いと思いますので、また国の動向や他区の動向を見ていきたいと考えております。","id":"exchange-078"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひこれは実現する方向でいっていただきたいと思います。とにかく、その人が置かれた経済的条件にかかわらず、教育を受ける権利を等しく区民に保障していくために、高校生、大学生に、その一歩として給付制の奨学金制度、これを求めて質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"小芝委員","kind":"質問","question":"お願いします。私からは、２３１ページ、在宅高齢者支援事業についてお伺いいたします。一方で、入りたくても、年齢や介護のランクによっては、順番待ちになることもあります。現在、要支援、要介護の認定を受けている高齢者は、大体どのくらいいらっしゃるのか、また、在宅介護認定者の数、要介護者全体の中で在宅介護認定者の占める割合、３つについてお伺いいたします。","respondent":"菅野高齢者福祉課長","answer":"在宅高齢者についてお答えします。現在、認定者数約１万５,０００人程度です。それに対して、在宅の高齢者数は１万２,０００人弱と認識しておりまして、約７５％ぐらいが在宅の方で、残りの２５％の方が施設入所されていると認識しているところです。","id":"exchange-080"},{"speaker":"小芝委員","kind":"質問","question":"高齢者全体で８万人を超える中で、その大体２割以下ですか、要支援・要介護認定者であるということ、さらにその中で要介護の方、およそ多分１万人前後ではないかなとは思いますが、そこから特別養護老人ホームに入れる方はさらに絞られまして、要介護３以上の方ですので、大体５,０００人前後ぐらいではないかなと思います。","respondent":"菅野高齢者福祉課長","answer":"区では２０か所の在宅介護支援センターや、区内１３か所に支え愛・ほっとステーション等があります。民生委員の方などの情報も得まして、少しでも介護認定の申請につながって、必要な方に介護サービスが提供できるように努めていきたいと、情報収集に努めているところです。","id":"exchange-081"},{"speaker":"小芝委員","kind":"質問","question":"この利益を受けることができるわけですが、大体どのくらいの年間の件数なのかを教えてください。そのような方でも、例えば段差のあるところだとか、トイレの中での手すりが必要だとか、そのようなものがあれば便利ということもあると思いますけれども、そのような方へのサービス、ほかにはどういったものがあるのかも含めて、教えていただければと思います。","respondent":"菅野高齢者福祉課長","answer":"こちらにつきましては、介護保険の認定で非該当と判定された６５歳以上の高齢者で、住宅の改修が必要と認められた方ということで、先ほどの対象者の拡大ということなので、手すりの設置や段差の解消などが対象工事となっております。","id":"exchange-082"},{"speaker":"小芝委員","kind":"質問・要望","question":"件数が減ったということなのですけれども、ぜひ、周知や案内を徹底していただきたいと思います。次、質問変えます。あることは承知はしておるのですが、なかなかそういった方々はあまりそういったところに入らないという傾向もありまして、そのような方々にも何か施策の展開ができるものではないかなと思っておるのですけれども、その辺り、区のお考え等ありましたら教えていただければと思います。","respondent":"川原高齢者地域支援課長","answer":"そのほか、応募等の要らない公園の健康遊具を利用した運動教室ですとか、シルバー大学での学びの支援ですとか、様々な角度から介護予防、また認知症予防に合致したプログラムを引き続き提供して、検討してまいりたいと考えています。","id":"exchange-083"},{"speaker":"木村委員","kind":"確認","question":"私からは、２１７ページ、高齢者安否確認事業からの質問です。令和４年度５,８１９万円余、令和５年度が５,７８２万円余と、約３６万円と微妙な減り具合ですけれども、安定した予算となったと思います。高齢者等地域見守りネットワーク事業ですが、この事業と予算の内容をお聞かせください。高齢者等とありますけれども、この等とは何を意味しているのでしょうか。これもお聞かせをください。","respondent":"寺嶋福祉計画課長","answer":"高齢者等地域見守りネットワーク事業につきましては、主に地域で見守りが必要と思われる高齢者の方を、地域で緩やかに見守っていただくということを目的に実施している事業です。大きく２つありまして、１つは町会・自治会等による見守り活動です。","id":"exchange-084"},{"speaker":"木村委員","kind":"質問","question":"町会の方々による見守り活動とのことですけれども、現在はどのぐらいの数の町会が活動し、また、これがいつ頃から始まった事業で、高齢者の皆さんの反応はどのように聞かれているのでしょうか。これもお聞かせください。","respondent":"寺嶋福祉計画課長","answer":"昨今コロナで少し活動が難しくなっているところはあるのですけれども、今年度も新たに３町会に加わっていただきまして、活発に活動していただいていると、このような状況です。","id":"exchange-085"},{"speaker":"木村委員","kind":"質問・要望","question":"民間企業についてもお尋ねをしますけれども、現在区と、この見守り協定をしている企業は、大体何社ぐらいあるのか、あるとすればどのような事業なのか、差し支えない範囲で結構ですので、お答えをいただきたいと思います。","respondent":"寺嶋福祉計画課長","answer":"先月の末時点で２１の事業所、団体と協定を締結しておりまして、３月１日付で新たに２社加わりまして、現在２３社による協定締結となっております。どのような企業かということなので、幾つか事例として申し上げますと、例えば信用金庫です。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"長寿お祝い事業についてですが、お聞きをいたします。この事業と予算の内容をお聞かせください。予算書に記載されているお祝い品とは、無論高齢者が必要としている商品等であろうと思いますけれども、どのようなものをお祝いとして出しているのか、これもお聞かせください。","respondent":"寺嶋福祉計画課長","answer":"長寿お祝い事業につきましては、８８歳、米寿、９０歳、卒寿、９９歳、１００歳、１０１歳以上の方に区内共通商品券をお届けしている事業です。安否確認を兼ねた事業となっておりますけれども、昨今コロナなので、この３年間は郵送による対応という形になっております。","id":"exchange-087"},{"speaker":"木村委員","kind":"質問・要望","question":"高齢者の方々に喜ばれている事業だとは思いますけれども、喜びの声や感想など、何か寄せられたようなことはあるかどうか、そしてその喜びの声などがあれば、お聞かせいただきたいと思います。","respondent":"寺嶋福祉計画課長","answer":"この間郵送にはなりましたけれども、区のほうから簡易書留で発送した、もう翌日以降に、区役所にお礼の電話が、１件、２件ではなく、複数件あったりとか、直筆、便箋のお礼状が届いたりということもありまして、大変喜ばれている事業です。","id":"exchange-088"},{"speaker":"木村委員","kind":"質問・要望","question":"令和４年が４１８万円余、令和５年度が３８８万円余と、減額予算となっております。その中でいきいきカラオケ広場、３万６,０００円とあります。これは令和４年度が３万６,０００円で、令和５年度も同じだと思いますけれども、大変低く計上されていますが、この事業自体を取りやめるようなことは考えていないのでしょうか。そして、これはなぜ続けるのでしょうか。それをお聞かせいただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"今後も実施を予定しています。","id":"exchange-089"},{"speaker":"木村委員","kind":"質問・要望","question":"歌は腹から声を出すため、健康にはとてもよいと思っています。続けるためには多くの参加者が必要だと思いますけれども、大変今厳しい状況の予算でありますが、それを続けていくためには何が必要なのか、それをお聞かせいただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"こちらの継続について、どのように図っていくかです。","id":"exchange-090"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひとも、高齢者の皆さんのためにも、このような事業が続くこと、私も歌が大好きでありますから、ぜひ続けていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"こんの委員","kind":"質問","question":"私からは、２３９ページ、介護予防活動拠点運営費、２点目が２３９ページ、高齢者向けスマホ教室体験会、２６９ページ、ベビーシッター利用支援事業、この３点からお伺いしたいと思います。順不同でお伺いします。この事業を利用する際の助成金の申請についてお伺いしたいと思います。","respondent":"中元保育支援課長","answer":"具体的に申し上げますと、１月から３月にご利用いただいた分については、翌月の４月１５日頃を交付申請の締切りとしているものです。申請していただいたものを審査いたしまして、４月末にお支払いするという流れで、今事務を行っているものです。","id":"exchange-092"},{"speaker":"こんの委員","kind":"質問・要望","question":"申請状況をご説明いただきました。この申請期限ですけれども、今ご説明いただいたように、利用月の翌月１５日ぐらいまでに申請となっているということです。ですから、利用した翌月の１５日までにその領収書が手元に来ない。この辺についてはどのように捉えていらっしゃいますでしょうか。申請日数に余裕を持たせた、こうした申請にしていただきたいと思うのですが、いかがでしょうか。","respondent":"中元保育支援課長","answer":"こちら、実はホームページのＦＡＱのほうには一番最後に書いてございまして、なかなかそこが目立たないところでございましたので、周知のほう、今後は、もう少し分かりやすいところにご案内するように検討してまいりたいと考えているところです。","id":"exchange-093"},{"speaker":"こんの委員","kind":"質問・要望","question":"このＦＡＱで分かるようにホームページのほうでもと言ってくださっているのですが、表現の仕方を工夫していただきたいなということが１つあります。高齢者向けのスマホ教室ですけれども、今年度の８月に本格実施をされて半年がたちますが、この事業の実施状況を確認させていただきたいと思います。併せて確認ですけれども、募集の案内だとか、応募についての方法、この辺も確認させてください。","respondent":"川原高齢者地域支援課長、中元保育支援課長","answer":"定員の約８５％から９０％確保しているような形で、実は抽せんになってしまったところもあるのですが、抽せんから残念ながら外れてしまった方は、空いている回へのご移動でのご協力の依頼などを丁寧に行いまして。先ほどのベビーシッターの支払い等の期限のホームページの表現につきましては、今後検討し、対応してまいりたいと考えています。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問・要望","question":"スマホの教室のことですけれども、今現状を伺いまして、やはりニーズは高いというか、これからも高齢者におけるデジタルデバイド、この対策については進めていただきたいという考えですが、そうすると、初めてのスマホ体験教室で、これはスマホを持っていらっしゃる方もいれば、あるいは、これからスマホを買おうかなと思っていらっしゃる方もいると。","respondent":"川原高齢者地域支援課長","answer":"そしてこの講座に参加した方が、新たに同じスマートフォンを購入したというような実績も出ている形です。さらなるステップアップというところに関しては、来年度また実施をして、来年度の後期、もしくは再来年度で、新たな企画を検討してまいりたいと思います。","id":"exchange-095"},{"speaker":"西村委員","kind":"質問","question":"２５４ページ、児童保育費全般から保育園入園状況について、２５５ページ、保育園業務システム、２６３ページ、保育関係事務費から保育士労務環境改善、２６５ページ、一時預かり事業、２６９ページ、私立幼稚園費、時間が許せば、２３３ページのさわやかサービスと、順不同で伺ってまいります。保育園の入園状況について伺います。区の見解と現況をお聞かせください。","respondent":"立木保育課長","answer":"１歳児の定員割れは１２園ありました。昨年の定員割れの園が、０歳児３８園、１歳児が３園でしたので、それぞれ増えているという形になります。やはり０歳よりは１歳から入るというようなことが、今のところ見られるというような状況にはなっていると考えております。","id":"exchange-096"},{"speaker":"西村委員","kind":"質問","question":"令和４年度、児童福祉法も改正されまして、いわゆる一時預かり事業でレスパイト利用についても可能であることが明確化されています。次に、新しく始まる一時預かり事業について伺ってまいります。こちらはリフレッシュでも活用できるとのことです。幅広く、このような方の受皿にもなると思いますが、担当課では様々な整備が必要かと思います。一言お言葉いただけますでしょうか。","respondent":"中元保育支援課長","answer":"こちら、これまで私立保育園でも一定程度の一時保育をやってございましたが、私立保育園に加えまして、地域型保育事業や認証保育所でも対象を拡大し、補助の対象とすることで、保育施設における一時預かりの実施を誘導してまいりたいと考えているものです。","id":"exchange-097"},{"speaker":"西村委員","kind":"質問","question":"こちらも新しく始まる、保育園と保護者をアプリでつなぐ保育園業務システムですけれども、ＩＣＴ化が進むことは、現場の先生方にとっては手書き文化で抵抗があると、以前保育士の方々より伺ったことがあります。今回区立園４０園で導入するに当たりまして、保育士の皆さんに対してもスムーズな導入になるように努めたことですとか、現場の声、課題があったらお聞かせください。","respondent":"初貝保育教育運営担当課長","answer":"今回の導入に当たっても、今ご指摘いただきました、保育士がきちんと混乱なく導入、操作ができるような形の視点も含めて、適切に選定、導入を進めてまいりたいと考えております。","id":"exchange-098"},{"speaker":"西村委員","kind":"質問","question":"さらに次は、保育士たちの働き方改善のために、社会保険労務士を活用した労務状況分析業務等委託事業として伺ってまいります。私立認可園１０園程度に対する試験的な実施を行うとありますが、実施する園についてどのように決めるのか、また、これまでは労務面はどのようにチェックをしていたのか、それが今後どのように変わるのかを伺います。","respondent":"立木保育課長","answer":"そういったところを勘案しながら、委託予定であります社会保険労務士会といろいろ打合せをしながら、１０園選んでいきたいと考えています。こちら私立の認可保育園が対象になります。","id":"exchange-099"},{"speaker":"西村委員","kind":"質問・要望","question":"私立幼稚園の長期休暇について伺います。もうすぐ春休みが始まりますが、私立幼稚園も預かり保育の充実には力を入れようとしてくださっているものの、採用などなかなかうまくいかない点もあるとお話を伺い、感じています。一方、私立幼稚園に預ける母親の預かり保育への要望は、年々高まるところです。そこで、私立幼稚園の長期休暇について伺います。伺います。","respondent":"立木保育課長","answer":"令和３年度の実績になりますが、私立幼稚園在園の方の一時保育の利用が２１６件、延べ日数でいいますと、１,１１３日ご利用いただいたという形になってあります。","id":"exchange-100"},{"speaker":"西村委員","kind":"質問・要望","question":"すみません。私先ほど区立幼稚園と言ってしまいました。区立保育園です。選ばれる努力は私立園独自でもされているものの、区としても、私立幼稚園ガイドなどをホームページに作成したり、各園がこれから頑張りますホームページへリンクが飛ぶように、私立幼稚園の魅力を伝える取組をぜひ背中を押していただきたいと思いますが、ご意見を伺います。","respondent":"中元保育支援課長","answer":"保護者への情報発信力の強化を目指してまいりたいところです。","id":"exchange-101"},{"speaker":"西村委員","kind":"質問・要望","question":"他区の事例にはなりますが、私立幼稚園が潰れないために、１・２歳児のプレ保育を定期的に始める園もあると伺いました。次にさわやかサービス、最後に伺わせていただきたいと思います。一般質問で高齢者の買物空白地域について質問させていただきましたが、今、買物支援について区で行っていただいていることもあると思います。こちら改めて伺います。","respondent":"寺嶋福祉計画課長","answer":"買物支援につきましては、まず１つは介護保険制度の中で、要介護認定、要支援の認定を受けた方につきましては、生活援助というサービスの中で買物の代行ができることになっております。同行はできないのですが、代行は可能ということになっております。","id":"exchange-102"},{"speaker":"西村委員","kind":"質問・要望","question":"実際には、この地域は町内に困っている人が多いとか、ここは坂が急だから買物に困りやすいなど、地域の事情がそれぞれ異なりますので、買物支援のモデル地域などを一度検証していただきまして、ぜひとも地域の事情に合わせた、こういった買物で困っていらっしゃる難民の方がいらっしゃらないのか、お調べいただきたいと考えています。こちらは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、２１７ページの高齢者福祉施設整備費、２３３ページの特別養護老人ホーム運営費に関わって、特別養護老人ホームと老人保健施設増設を求めて質問します。現在も申し込んでも入れない状況は続いています。直近、この３回の申込者数とその傾向を伺います。年齢別に、７０代以上で、各年代の申込者と入所できた人数、また、介護度別に、要介護３以上の申込者と入所できた人数を伺います。","respondent":"菅野高齢者福祉課長","answer":"特別養護老人ホームの入所申込みは、年に２回申込みを実施しまして、調整会議を行わせていただいております。今現在、２月末までの入所申込みで締め切った部分につきましては、３９５名の方の申込みがございました。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"さきの一般質問で、特別養護老人ホームの増設を求める質問に、区は在宅支援を重視しつつ、セーフティーネットとして多様な入所・入居系施設の整備を進めているとの答弁でした。区は、９０歳でも約半分が入れない、また、要介護５でも３分の２が入れない状況で、特別養護老人ホームと老人保健施設は足りているという認識でしょうか。伺います。","respondent":"菅野高齢者福祉課長","answer":"そのような方はリハビリ等をすることによって、回復するという可能性もありますので、その辺りについても入所調整会議の中で、介護期間の中で介護度が高くても、判定が、点数が高く上がらないという場合もありますので、一概には要介護度が高くついているからといって。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"恐らくこうした状況が、区内に広がっていると思います。こうした家庭の状況など、区内の実態をつかんでいるのでしょうか。伺います。こうした家庭が特別養護老人ホームに入所でき、生活を支えられるように、特別養護老人ホームと老人保健施設の増設を進めていくために、この待機者をゼロにする目標を持って、そのためにいつまでにどれだけつくるかの計画をつくることを求めますが、いかがでしょうか。","respondent":"菅野高齢者福祉課長、寺嶋福祉計画課長","answer":"入れない方でいろいろとご家庭で困っている方の状況についてですけれども、区としましては、在宅介護支援センターのケアマネジャー等の情報など、いろいろと情報がありますので、そういったところから寄せられて。今現在、第八期の介護保険事業計画が進んでおりまして、この第八期の計画を策定するときに、令和６年度以降の第九期、第十期におきまして、特別養護老人ホームの定員を１５０から２００に増やすというふうに計画上定めております。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした状況ではない方も、やはり必要な方がたくさんまだいるということですから、ぜひそれは増設していくべきだと思います。なぜ目標を持って計画をつくらないのか、伺います。併せて介護職員の処遇改善も求めたいと思います。今コロナで職員の負担も増え、必死に取り組んでいます。ぜひ区としても改善していただきたいと思いますし、国にも介護報酬アップを求めていただきたいと思います。","respondent":"寺嶋福祉計画課長、菅野高齢者福祉課長","answer":"整備計画につきましては、目標を持ってということで、第八期の中で目標を定め、第九期に向けて現在進めているところです。介護職員の処遇改善につきましても、今国のほうで、第九期の介護保険事業計画に向けて審議等進めておりますので、その動向を注視していきたいと思います。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"今の計画では足りないので求めておりますので、ぜひ進めて増設していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"せお委員","kind":"質問","question":"私からは、２２３ページ、障害者訓練等給付事務から就労移行支援等、２３１ページ、超短時間就労促進事業、２４９ページ、児童相談所移管推進事業をお伺いします。初めに就労移行支援等のところですが、当初予算は就労継続支援Ａ型や就労継続支援Ｂ型なども合わせて、１０億１,０００万円を超えています。当初予算が増えている、この理由をまず教えてください。","respondent":"松山障害者支援課長","answer":"それに伴い、利用者も増えている状況です。中でも精神障害、発達障害の方で、就労、働きたいという方が多い状況で、給付費の増を見込みまして、予算額を増額して計上させていただいたものです。","id":"exchange-109"},{"speaker":"せお委員","kind":"質問","question":"一般質問でも伺いましたが、超短時間就労についてです。このような内容になった経緯は何でしょうか。教えてください。もう１点、障害者やそのご家族は、身近である地域の商店街での就労を希望する声も多くて、ですから、私も以前から商店街をキーワードに挙げていますが、その商店街の皆様へ、実態調査としてアンケートを実施することも有効かと思います。結果も興味深いのですが、今後取り上げます。","respondent":"松山障害者支援課長","answer":"この間、委託先の東京大学の近藤先生と協議、調整していますが、東京大学のノウハウを一律で品川区にそのままパッケージして持ってくる、それを当てはめるのではなく、品川区自体の地域の実情に合わせて、今後継続した就労を支援する仕組みを構築するということを目標に。","id":"exchange-110"},{"speaker":"せお委員","kind":"質問・要望","question":"アンケートをぜひお願いします。こちらは要望で終わります。これはちょうど３年前の一般質問でも取り上げて、文教委員会に所属していた頃も何度か要望しておりますが、児童相談所の職員の業務負担軽減のためにも、そして障害児への一貫性のある支援のためにも、愛の手帳の判定は障害児関連の施設でいかがでしょうか。業務の見直しの検討だけは行っていただきたいのですが、見解を伺います。","respondent":"長谷川児童相談所移管担当課長","answer":"児童相談所設置市としての事務である愛の手帳の判定につきましては、自治体間における判定基準にばらつきがあることから、国において基準の統一化に向けた調査研究が進められていると認識しており、国の動向を引き続き注視してまいります。","id":"exchange-111"},{"speaker":"高橋（伸）委員","kind":"質問","question":"よろしくお願いします。２２７ページ、心身障害者福祉会館運営費、２２１ページ、手話理解促進、同じく２２１ページ、２０２５年デフリンピック大会東京開催周知啓発についてお伺いいたします。最初に２２７ページ、心身障害者福祉会館運営費についてお尋ねをいたします。その中でも１人の方が、小学校、中学校のときにあの屋上で遊んだというようなお声もいただいて、私も遊んだ記憶があるのです。","respondent":"松山障害者支援課長","answer":"今のところは、まだ代替地検討までは至っておりませんが、いずれ代替地を検討して、建て替え、あるいは改修なのかという形で、検討する必要があると考えております。","id":"exchange-112"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。本当に建て替えなのか、改装なのか、いずれ前向きにご検討いただきたいと思います。よろしくお願いします。もう１点なのですけれども、来年度の予算の中で、屋上の花壇の改修が入っているのです。私もあそこ、障害者まつりなどでお邪魔したことはあるのですけれども、それは地域、当該町会の要望など、そのようなものがあっての改修なのかというお尋ねをしたいと思います。","respondent":"松山障害者支援課長","answer":"心身障害者福祉会館の屋上花壇の改修についてお答え申し上げます。現在、清水台小学校の地域園芸ボランティアグループの協力をいただきながら、心身障害者福祉会館の利用者が野菜などを栽培して、食したりする取組を行っているところです。","id":"exchange-113"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。続いて、手話理解促進についてお尋ねをします。品川区では、令和３年７月に品川区手話言語条例を制定いたしました。次年度の手話理解促進事業で、１１５万円余の予算計上があって、これが少ないのかどうか、ちょっと私は分からないのですが、この予算規模についてのお考えをお伺いしたいと思います。","respondent":"松山障害者支援課長","answer":"それから子ども向け、区民向けも行っております。来年度につきましては、心身障害者福祉会館だけでなく、障害児者総合支援施設ぐるっぽにおきまして、夏休み手話講座と、それから区民向け講座を初めて開始するということになりました。そちらを積算したものです。","id":"exchange-114"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"同じく２２１ページの２０２５年のデフリンピック大会東京開催周知啓発ということなのですけれども、これ３９万５,０００円の予算計上がされておりますが、来年度予算で、所管は違うのですけれども、デフスポーツ啓発事業でも結構金額が計上されていまして、これ東京大会があるということで、手話理解も当然そうなのですが、啓発について、大体約４０万円の中で、恐らく啓発ですから、ポスターとか。","respondent":"松山障害者支援課長","answer":"２０２５年のデフリンピック大会東京開催の周知啓発について、お答え申し上げます。","id":"exchange-115"},{"speaker":"たけうち委員","kind":"質問","question":"２３３ページの高齢者災害対策支援事業費の福祉避難所施設備蓄品配備等、それから同じページの高齢者福祉施設運営費、それから２５３ページの児童手当給付金について伺います。東日本大震災から明日で１２年となります。１２年前の３月１１日、今日と同じ金曜日です。そこで、２３３ページの福祉避難所施設備蓄品配備等とありますが、この「等」の事業内容と予算額を教えてください。","respondent":"菅野高齢者福祉課長","answer":"私からは、福祉避難所施設備蓄品配備等の「等」の部分についてお答えします。こちらについては、福祉避難所施設の介護職員宿舎借上げ助成６５万１,０００円分がついております。","id":"exchange-116"},{"speaker":"たけうち委員","kind":"質問・要望","question":"高齢者福祉施設運営費については、昨年の決算特別委員会でもお聞きしましたが、いわゆる施設入所者に対しての面会支援について、コロナのほうもいろいろと５月８日から２類から５類に変わったりとか、またマスクも間もなく緩和されて、今、世の中的にはそういう形で緩和されてきていますけれども、この面会についてはどのようになっていくのか、ご見解を教えていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"地域密着型のサービスなので、１８人以下の小さい介護サービス、デイサービスなどをやっている事業所等が検討していると手を挙げてはいただいているのですけれども、災害時の協定締結をするにあたってのいろいろな条件整備等で少し時間がかかっておりますので。","id":"exchange-117"},{"speaker":"たけうち委員","kind":"質問・要望","question":"２３７ページで外国人に対して、また、介護職員住居支援事業等も品川区でやっておりますので、こことの関連もしっかり備えながら進めていただきたいと思います。それから、児童手当につきましては、今東京都が１８歳まで所得制限なしで助成をしますとなっております。こうした動きを区として今どのように捉えているか、また何か東京都のほうの情報が入っているかどうか、お聞かせいただきたいと思います。","respondent":"飛田子育て応援課長","answer":"区としましては、現在国も都もこのように様々な支援策を検討しておりますので、今後の動向などを注視してまいりたいと考えております。","id":"exchange-118"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私たち公明党もこの４月の統一地方選挙の重点政策の一つとして、この児童手当の拡充、１８歳までの延長、また所得制限の撤廃を掲げて、今、党として取り組ませていただいているところです。こうしたことをしっかり出しながら進めていただきたいと思うのですが、その辺のお考え、また決意を教えていただきたいと思います。","respondent":"飛田子育て応援課長","answer":"ですので、そういうところでは、なかなか財政的な観点からも非常に難しいかとは考えております。","id":"exchange-119"},{"speaker":"たけうち委員","kind":"意見","question":"試算をしていただいているということは、その本気度が伝わってまいりましたので、期待しております。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"初めに、障害者の日常生活用具給付事業ですが、自家発電装置の購入費助成について伺いたいと思います。何人が利用されたのか伺います。その方は、自分で持っているバッテリーは１２時間分しかないので、ぜひ備えておきたいということなのですけれども、この人工呼吸器装着者の電源確保を使い勝手のよいものに当事者や業者などの意見も聞きながら改善していただきたいと思いますが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"区としても、やはり人工呼吸器を使用する方が、災害時安全に在宅で避難ができるように、個別計画の作成についても進めていきたいと考えていますので、再度周知をさせていただきたいと考えています。","id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"続きまして、障害者グループホームの整備等助成事業について伺いたいと思います。森澤区長が公約で、障害者グループホームを１００人分増設するということで掲げましたけれども、具体策はありません。残りの７０人余の増設はいつまでにどのようにしていくのか、伺いたいと思います。それから、令和２年度から整備補助が２,５００万円まで増額しましたが、３年間で何件活用されたかも教えてください。","respondent":"川崎障害者施策推進課長","answer":"グループホームについてのご質問です。１つ、いつまでにというお話でしたけれども、現行の計画で、令和６年度末までに４８名増を予定しております。","id":"exchange-122"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２,５００万円の補助というのが、結局２,５００万円になってからは何か所だったのですか。資格要件は比較的緩い。人件費は安い。設備基準は比較的緩い。それから、当事者や家族が求めるグループホーム、労働者の待遇も確保されるグループホームということになると、私は区が責任を持って重度者も入れる、地域移行もできる、もうそういう形で計画的に増設が必要だと思いますが、その点についても伺います。","respondent":"川崎障害者施策推進課長","answer":"ですので、私どもも民間の整備においては活力を使いながら整備を進めていく方向ではありますけれども、そこの部分は丁寧に説明しつつ、安定的に運営していける事業者の確保にも努めていきたいと考えております。","id":"exchange-123"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３つ目に、地域包括支援センターについて伺います。１７年もたっても、地域に地域包括支援センターを造っていないのは、２３区では品川区だけしかありませんし、東京全体でも品川区だけしかないのではないでしょうか。今のままだと基準を満たしていないわけですから、看板がかけられませんね。だって保健師がいないのですから。このチームアプローチについて、品川区はどう考えているか伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そういったケースが起きたときには、保健師、社会福祉士、主任ケアマネ、チームを組んで対応しています。在宅介護支援センターからも、区の保健師のほうに相談等が寄せられて、こちらのほうで連携をとって対応させていただいている次第です。","id":"exchange-124"},{"speaker":"渡部委員","kind":"質問・要望","question":"よろしくお願いします。２４５ページ、児童センターのところで伺っていきます。一般質問等でも触れさせていただいたのですが、児童センターの方向性が出てきて、この中で今後こういうふうにという話がされていて、これは中を見ていると、プロジェクトチームは去年からということで動いていたのですね。","respondent":"廣田子ども育成課長","answer":"地域の活動拠点が必要というところが出てきておりますので、二本立てで、児童センターのモデル的な地域とも密着したような形で構想を練り、若者の拠点の考えを整理して、理想的なものというか目指すところというのを整理しようと思っているところなのですが。","id":"exchange-125"},{"speaker":"渡部委員","kind":"質問・要望","question":"今回予算案の中でも南品川の検討に入りますよということがあった。新しい計画が出てくるわけですから、これからの在り方の中にそこは生かされていくのだという方向性はそれで間違いないというのだけ、少し確認をさせていただきたいと思います。","respondent":"廣田子ども育成課長","answer":"少々言い忘れてしまったのですが、児童センターのチームで、０歳から１８歳のセンターではあるのですけれども、１施設全部０歳から１８歳まで満足させるコンプリートはできないということがニーズ調査で分かったので、それをグルーピングをして。","id":"exchange-126"},{"speaker":"渡部委員","kind":"質問","question":"よろしくお願いします。その在り方が出た中で、若者と一緒になったという中で南品川が出ているわけだから、そうすると次、図書館と一緒にというのがあったり、外遊びができたりというようなその特色があるような何かさせるところからある程度順次やっていこうかなとか、保育園との兼ね合わせが当然あると思うのですけれど、その辺の考え方というのを少し教えてもらえれば。","respondent":"廣田子ども育成課長","answer":"ハード面ではなかなかうちだけでは決めかねますので、どこからスタートしてもできるようにというところで、どことコラボしてもできるような考え方を整理しておいて、順番が来たらゴーという形で進めていくような。","id":"exchange-127"},{"speaker":"渡部委員","kind":"質問","question":"ですから、どこまでかというそのやり方の考え方、その施設を作る中で、例えば児童センターで少し高学年を預かれる仕組みをとるとか、どこか考え方を変えていかないと疲弊してしまうのではないかという心配もあるので、その建物を検討するときにそういうところ、いわゆるこれも品川の子育てに関することを全て一切合財考えていかなければならないと思うのですけれども。","respondent":"廣田子ども育成課長","answer":"ご指摘のとおり、すまいるスクールはかなりきゅうきゅうしています。児童センター側の提案としては、ランドセル来館とか、そういう面についてもよその区ではやっているので、それも含めてそういう事態が来たときは対応できるようにという検討も併せて少しずつしています。","id":"exchange-128"},{"speaker":"渡部委員","kind":"質問・要望","question":"１分余ったので、保育園のことを聞きます。誰が何人入ったかはいいのですけれども、いわゆる入園には指数があって、それが地域偏差というかエリアによる偏りというのが相当あると思うのですけれども、やはり４０点では入れないような地域がまだ品川区にはあるのかどうなのか。あるのだったらどの辺なのか、少し教えてください。","respondent":"立木保育課長","answer":"おおむね４０点、フルタイムの保護者の方は４０点というのが標準なのですけれども、それ以下でも入れているという園が増えてまいりました。ただ、やはり海側のところですね。","id":"exchange-129"},{"speaker":"渡部委員","kind":"質問・要望","question":"沿岸部のほうとかで軒並み４０点を超えているようなところというのは、やはり需要があって供給が足りてないのかなとも感じますので、そこはまた新たな園を作るべくお願いしたいですし、海のほうから、では中延でも旗の台でも中のほうまで通ってくれというのはなかなか難しいところもありますから、まだ足りないところは進めていただくよう要望させていただいて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"よろしくお願いします。２５９ページの幼保一体施設、２６５ページ、私立保育園費をお願いします。一体的な運営も軌道に乗っていると承知しています。品川区として早急に進めていただく観点から、認定こども園化が遅れているというのはどのような支障があるのかお伺いします。それをクリアするためにはどうすればいいのかお尋ねします。クリアするために現在何を進めているのでしょうか。","respondent":"立木保育課長","answer":"まだまだそこのところでできるところも十分ありますし、国と特別区のほうの動向を見ながら、これからどのような形で進めていくかというところを検討するという考え方で、今やっているところです。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、なかなか進まないという感じのご答弁と私は感じました。残念ながら、様々な理由から認定こども園化がプリスクールは進んでおりませんが、認定こども園化を進めていくとすれば、今回少々止まってしまっているぷりすくーる西五反田と都内の西五反田保育園との関係を含めて、今後の展開をお伺いします。","respondent":"立木保育課長","answer":"そこでネックになりますのが、敷地の要件、園庭の要件でございまして、そこのところをクリアするためには、隣に立地しております西五反田保育園というところをやはり一つ一体的に考えていく必要があるだろうということで、今検討を進めているところです。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"就学前教育で日本の先頭を走っていた品川区ですので、新しい時代の就学前教育においてもこの認定こども園化をして、ぜひ特色ある教育を進めていっていただきたいと思います。次に、私立保育園費で、特別支援の巡回相談です。ところで、基本的には区立保育園が中心となって、特別に支援が必要なお子さんを受け入れる体制を整備していくことが必要だと思いますが、まずその点、担当課の方針を伺います。","respondent":"立木保育課長","answer":"区でも特別支援には力を入れてございまして、特に来年度から医療的ケアの項目に関しても対応を拡充をしていくというところがあります。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問","question":"区立のほうできちんと整備を整えていく、受け入れる体制を整えていくというご答弁がありました。よろしくお願いします。ところで、障害者の支援ということでお尋ねしますけれども、現場の保育士たちは、残念ながら特別支援の専門家ではありません。そこで対応に苦慮しているという現場の声があります。保育所等訪問支援を行っている事業者は区内でどれぐらいあるのでしょうか。","respondent":"松山障害者支援課長","answer":"保育所等訪問支援の事業所についてですけれども、区内では１か所、品川児童学園のみです。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問","question":"課題を今ご説明いただきました。そしてもう一つ、今、区内にも事業所を誘致するというお話があったのですが、その３点について、障害者支援の所管として今後の見通しというか、見解といいますか、進め方をお願いします。","respondent":"松山障害者支援課長","answer":"保育所等訪問支援の事業所ですけれども、今後、児童発達支援センターが２か所目もできることから、またあと例えば民間の誘致をするなど様々な方法がありますので、進めてまいりたいと考えています。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"お子さんを大切するという気持ちは、障害者の所管でも、また保育の所管でも一緒なので、ぜひ連携して共通認識を持って進めていっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"若林委員","kind":"確認","question":"２３９ページ、補聴器購入助成についてお尋ねいたします。件数が８０件ということで、この考え方をお聞かせください。それから、事項別明細等を確認して、助成期間は通年とあります。４月の購入分からに対しての助成制度化かというところの確認。ボーダーの方が当然いらっしゃいますので、そういう方は希望すれば、お医者様の判断も含めて対象になるのかどうか。こういうところをお聞きしたいと思います。","respondent":"川原高齢者地域支援課長","answer":"こちらは今年度新たに実施しました渋谷区の高齢者福祉課の補聴器助成に関してヒアリングを行いまして、人口と、１か月当たりの実績を品川区で割り振ったところ、１年で８０人相当となるだろうという形で見込ませていただき、この人数を設定をさせていただいたところです。","id":"exchange-137"},{"speaker":"若林委員","kind":"質問・要望","question":"効果検証を伺います。代表質問でも、今後この効果検証については検討というところで、７月のいわゆるこの助成開始までに、この検証の仕組みが整うのかというのを１つお聞きしたいと思います。ぜひそういう８０件を超えるようなことがあれば、しっかりと何らかの拡充の準備をしておいていただきたいということが要望の一つで、お考えをお聞きしたいと思います。","respondent":"川原高齢者地域支援課長","answer":"効果の検証が７月の助成の時期までに決まるのかというところに関しましては、現在進行形で、医師会の方と、あとは言語聴覚士の方と適宜お話をして伺っているところではあるのですけれども、今のところ検討段階ではありますが、アンケートの送付をいつにするか。","id":"exchange-138"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、予算書２６３ページ、児童保育費、各種児童保育委託から病児保育事業について、２６５ページ、保育支援費、保育人材確保・育成支援事業、新型コロナウイルス感染症対策事業から保育園の感染症対策について、時間があれば、保育所の応募状況についてお伺いしてまいりますので、よろしくお願いいたします。令和４年度の病児保育の現況についてお伺いします。よろしくお願いします。","respondent":"初貝保育教育運営担当課長","answer":"お預かりしている罹患症状の内訳といたしましては、上気道炎のお子様が６６２人、咽頭炎３０６人、急性胃腸炎が１２１人、気管支炎が１１３人、その他ＲＳウイルス感染症、インフルエンザなどが合計で３２４人という実績になっております。","id":"exchange-139"},{"speaker":"鈴木（博）委員","kind":"質問","question":"この間、予算特別委員会、決算特別委員会と継続して病児保育の利用状況をお聞きしてまいりました。新型コロナウイルス感染症が現在終息状況、しかも５類に変更されて、大きな感染症の流行がない落ち着いた状況の今だからこそ、品川区の病児保育のグラウンドデザインを検討するべきだと思われますが、いかがでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"今後の病児保育の利用状況の推移などを踏まえ、需要に即した病児保育の提供ができるように努めてまいりたいと考えております。","id":"exchange-140"},{"speaker":"鈴木（博）委員","kind":"質問","question":"現在の小規模な医療機関併設型の病児保育所の力量では、残念ながら医療スタッフのマンパワー、医療施設設備のレベルにおいて医療的ケアが必要な障害児をお預かりすることはできません。医療的ケア児の預かりも時代の趨勢と思われますが、現在、検討等は行われているのでしょうか。ご説明をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"今ご質問いただきました病児保育での医療的ケア児の受入れに関しましては、スペース的な問題でありましたり人的な課題、そういったところをどのような形でクリアして園児の安全を担保するかなどといった課題や、他自治体などの動向を研究いたしてまいりたいと考えております。","id":"exchange-141"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ただし、保育所における新型コロナウイルス感染症の対応は当面大きく変わらないと思われますが、今後保育所における感染症対策についてお伺いしたいと思います。３密を避けて換気を行うこと。手洗いを励行すること。その方向を伺いたいと思います。間違っても、各施設が独自の判断として、子どもの健全な発育・発展を阻害するような過剰な感染対策に固執しないような指導も含めて、区のご見解を伺います。","respondent":"初貝保育教育運営担当課長","answer":"しかしながら、園では園児に対して愛情を持った触れ合いが大切だと考えておりますので、状況や場面に応じた適切な保育や保育環境を整えていくように、関係部署と連携をとりながら検討を進めてまいりたいと考えています。","id":"exchange-142"},{"speaker":"鈴木（博）委員","kind":"質問","question":"感染症対策は、特に年少児になればなるほど一元的な対応ではなく、状況に応じた場面に応じたきめ細かな対応が要求されると考えます。保育園では、コロナ禍の中でこのような乳幼児の心の問題についてどのように配慮し、どのように対応されてきたのでしょうか、また、子どもの心を最大限配慮したような感染対応が、今後５類移行後、より強く要請されると考えますが、区のお考えをご説明ください。","respondent":"初貝保育教育運営担当課長","answer":"行動が制限される中でも、集団を分けるなどといった工夫をしながら園での活動を実施してきた次第です。子どもの心の問題に関しましては、今後も園児の様子などを注意深く観察いたしまして、子どもの心に寄り添った保育をしてまいりたいと考えております。","id":"exchange-143"},{"speaker":"鈴木（博）委員","kind":"質問","question":"コロナ禍の中でかなりルールが緩んできて、今まで登園許可が必要だったような疾患が、登園許可が素通りするような事態が現出されているわけですが、登園許可証はもう既に廃止されていますけれども、今後の保育園の感染症の登園許可の扱いはどうなるのでしょうか、ご説明をお願いします。","respondent":"初貝保育教育運営担当課長","answer":"今の登園に関することです。新型コロナウイルス感染症の流行前から、区立保育園においては品川区立保育園保健マニュアルに従った対応しております。","id":"exchange-144"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２つ質問します。１つは今でもそれは続いているのでしょうか。それとあともう一つ、続けて質問します。保育職員に対する感染症対策の研修として、コロナ流行以前では、保育所における感染症対策ガイドラインを踏まえた研修会が毎年開催されてきました。今後、保育職員に対する感染症研修はどのような形で続けられるのでしょうか。今の研修予定等がありましたら、ご説明をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"令和４年度におきましては、ウェブでの研修を実施しておりまして、延べ１０６名の方が受講しております。今後も、新型コロナの通知を含めて速やかに通知をするとともに、保育園での知識の醸成を図ってまいりたいと思います。","id":"exchange-145","title":"議員研修会の内容と所要時間"},{"speaker":"田中委員","kind":"質問・要望","question":"２２０ページ、障害者支援費、特に精神障害者支援について伺います。２７０ページ、生活保護費の中から生活困窮者支援と、２７７ページ、修学旅行等支度金を関連して伺います。そして２４５ページ、プレイパーク運営費を特定整備路線予定地の活用を求めて質問します。２４９ページ、ヤングケアラー支援について伺います。現在、相談支援事業所の増設の議論は進んでいるのでしょうか、伺います。","respondent":"松山障害者支援課長","answer":"現在精神障害者の方がご相談される場所はたいむ１か所ではございませんで、いわゆる地域拠点相談支援センターのたいむを除きまして、計画相談、ケアプランを作成する事業所、これが区内には１２か所ありますが。","id":"exchange-146"},{"speaker":"田中委員","kind":"質問・要望","question":"特にその精神障害の方への支援というのは、障害者支援施策の中でも非常に少ない状況なので、ぜひ当事者の声を聞いていただきたいと思います。次に、進みます。生活困窮者支援と修学旅行等支度金について伺います。一般社団法人生活サポート基金にお話を伺うときがありました。最近は精神疾患を患う相談者が増えてきていると伺います。特に若い世代についてはどのような支援につながったのか、伺います。","respondent":"櫻木生活福祉課長","answer":"ご相談の内容によっては障害関係の相談にもつないでいるところです。特に若者という観点というよりは、そのような形で全般として対応しています。","id":"exchange-147"},{"speaker":"田中委員","kind":"質問・要望","question":"併せて、修学旅行等支度金について伺います。このような突然のトラブルに対する救済的な措置・対応を求めたいのですが、現在、支援策があるのか伺います。この家庭は周りの方に一生懸命助けを求めて、様々なネットワークを駆使してリサイクル品を集めて、どうにか負担が発生せずに済みました。このようなときにも、区での支援がすぐにつながればと思うのですが、現在ある支援策について伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"ご相談、ご質問の内容ですが、１つは不動産等の資産がある生活困窮者への対応です。現実に不動産をお持ちの方であっても、今現実として困窮している方であれば、生活保護につながることができます。","id":"exchange-148"},{"speaker":"田中委員","kind":"提案","question":"修学旅行については、就学援助は対象にはならないということも伺ってしまっていて、だから何かあればいいということを思いました。ヤングケアラーについて伺います。生活者ネットワークが２０１８年からヤングケアラー支援、具体的支援を求めてきました。今想定されている具体的支援をぜひ示していただきたいと思います。これまで家事支援やレスパイト保証を求めてきたので、ぜひ何かあればと思います。","respondent":"染谷子ども家庭支援センター長","answer":"ヤングケアラーに対する具体的な支援ですけれども、既にこちらのほうで来年度想定しております事業の中に、家事援助を行うための訪問支援につきまして、国の財源を活用しながらヤングケアーのいるご家族にも入れていくということは想定しているものです。","id":"exchange-149"},{"speaker":"石田委員","kind":"質問","question":"私からは、４４４ページ、国保の一般会計繰入金から、子どもの国保料の減免、そして高過ぎる国保料の引下げについて、そして５１１ページ、介護保険について伺いたいと思います。国保のほうですけれども、令和４年度、まだ少しありますけれども、直近での国保の滞納者数、差押え件数、あと短期証、資格証、あと滞納処分の執行停止数、それぞれ伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"それともう一つが、短期証と資格証の世帯ですけれども、資格証の世帯につきましては、１月末現在では４７世帯。それと短期証対象世帯につきましては１,１２７世帯です。","id":"exchange-150"},{"speaker":"石田委員","kind":"質問","question":"差押え件数は、滞納処分、執行停止と一緒になっていますか。差押え件数と滞納処分の執行停止数を教えてください。","respondent":"池田国保医療年金課長","answer":"執行停止ですね。執行停止の金額ですけれども、今年度は約２億円の執行停止という形になっているところです。件数につきましては、およそ３,４２０件が今年度の執行停止の件数となっております。","id":"exchange-151"},{"speaker":"石田委員","kind":"質問","question":"そうすると、差押え件数はさっきおっしゃった１３９件ということでいいのでしょうか。","respondent":"池田国保医療年金課長","answer":"１３９件で結構です。","id":"exchange-152"},{"speaker":"石田委員","kind":"質問・要望","question":"差押え件数１３９件、本当に少なくなったと考えています。それは区も言うとおりです。そのことを、厚生委員会だったり先日の補正予算で確認したところ、できるけれども、国が好ましくないと言っているからできないのだというような答弁をされたのですけれども、好ましくないと考えるのは国の考えであって、自治体にその考えを押しつける法的根拠はないと思うのですけれども、少々確認させてください。","respondent":"池田国保医療年金課長","answer":"こちらにつきましては、先日もお話ししましたように、賦課と減免の違いというところでございまして、減免については一律にやるものではなく、申請を受けてやるものが減免という指導がありますので、求められている一律での減免ということについては。","id":"exchange-153"},{"speaker":"石田委員","kind":"質問・要望","question":"制度としてどのように減免するかというのは別として、自治体の裁量で減免をするということは可能です。そこは可能ですというのは言っておきたいと思います。それで、そうした国に基づいて算定し賦課した上で、減免の対象を決める裁量は自治体と首長にあって、ここに国は介入できません。なので国がどうこうというのではなく、区として減免を行うことは可能だ。その理由を明確にお答えいただきたいと思います。","respondent":"池田国保医療年金課長","answer":"これは区としてではなく、国としても同じなのですけれども、国民健康保険というものにつきまして、まず今回の子どもの保険料の減額ということで、５割減額、未就学児でやったところですけれども、実際に保険料は相互扶助により運営された区民のものですので。","id":"exchange-154"},{"speaker":"石田委員","kind":"質問","question":"それが区の考えだということですね。そのような中で条例減免の仕組みを活用して、子どもの均等割の独自軽減や、子育て世帯やひとり親世帯、生活困窮者世帯、そして障害者や障害児のいる世帯など、国保料の減免を区として行っていくことは、こういう状況ではいよいよ重要だと思いますけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"国民健康保険というのは相互扶助により運営されているというところで、何度も説明させていただいているところではあります。","id":"exchange-155"},{"speaker":"石田委員","kind":"質問・要望","question":"国保は相互扶助ではなく、社会保障です。この公平性の観点というところからも、ほかの子どもたちと同様に、子どもの国保料の無料化を求めますけれどもいかがでしょうか。区としてできるし、区もさっきから言っているこの申請制度、それも申請制度にすれば、この子どもの国保料を無料化できますので、やっている自治体もありますので、ぜひ実施していただきたいと思いますけれども、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"委員のおっしゃるところの要望につきましては、特別区の課長会、それから区長会のほうでも認識しておりまして、こちらにつきましては、国、都のほうに就学時のお子さん、それと保険料について申出をさせていただいて。","id":"exchange-156"},{"speaker":"石田委員","kind":"質問・要望","question":"国や都がやらないので、ほかの自治体は独自でやっているのです。なので、ぜひ品川区として、子どもの国保料の無料化をまず進めてください。そして、本当にもう今回は今までにない大幅値上げですから、それを引き下げることは可能ですので、ぜひそこに踏み出していただきたい。潤沢な財政を使ってやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"塚本委員","kind":"質問","question":"私からは、２２７ページ、障害者医療ショートステイ事業。それから２４３ページ、子育て支援推進費。それから５４９ページの一般介護予防事業について伺っていきたいと思います。現在までの運用実績がどうだったかということをお伺いするのと、令和５年度については６９万３,０００円という予算ですけれども、利用人数等はどの程度見込んでいるのかお知らせください。","respondent":"松山障害者支援課長","answer":"それから次に、令和５年度の予算額でどの程度を見込んでいるのかということですけれども、今年度は、実績に応じて年間８人を見込んでいたところなのですけれども、昨年は全く利用がなかったということで、令和５年度については年間６人程度ということでご利用を見込んでおります。","id":"exchange-158"},{"speaker":"塚本委員","kind":"質問・要望","question":"この利用について、今後のそういった呼吸器なども含めた利用の拡大について、区としての今後の取組の姿勢等を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"区としては可能な限り受け入れていただくように医療機関にお願いしていますが、希望される方全てに対応できているわけではございません。しかしながら、コロナ禍でありながら、医療機関に受け入れていただいたことは大変ありがたく感謝しています。","id":"exchange-159"},{"speaker":"塚本委員","kind":"質問・要望","question":"うちの会派からも、補正予算だったかで取り上げたかと思いますけれども、このパパママ応援アプリのいわゆるリニューアル、今年度新しくするという、これまでの答弁ですと１０月をめどにというお話を聞きましたけれども、現在のパパママ応援アプリの課題がどこにあると見ているのか、どういったところを改善していこうとしてリニューアルするのかということ初めにお伺いいたします。","respondent":"廣田子ども育成課長","answer":"今８年ほどたっているのですけれども、まず一番が地図がアプリの地図を使っていないというところで、もう少し何がどこにあるか情報を集めるというようなことができないかところが、まず大きく一つあります。","id":"exchange-160"},{"speaker":"塚本委員","kind":"提案","question":"そういういわゆるパーソナライズされた情報発信ということを、ぜひこのパパママ応援アプリの中で検討していってはいかがか、検討できないかなというところでのご提案なのですけれども、いかがでしょうか。","respondent":"廣田子ども育成課長","answer":"今の技術とかをいろいろ検証しながら作っていく中で、ご提案の内容についても検討の中で入れさせていただいて、何がいいかというのは考えていきたいと思います。","id":"exchange-161"},{"speaker":"塚本委員","kind":"質問・要望","question":"一般介護予防事業なのですけれども、これは運動系と認知症予防というのが２つありますけれども、運動系のほうが来年度は９,５２３万９,０００円。前年令和４年度から比べると、５００万円弱の増。増額の理由というか、増額によって使われるこの事業の使途について、最初にお伺いいたします。","respondent":"川原高齢者地域支援課長","answer":"は脳力アップ元気教室、こちらも既存のもの１クラスに加えて、プラス２クラス増加をして、計３クラス、いろいろな内容での実施を行うような形です。","id":"exchange-162"},{"speaker":"塚本委員","kind":"質問","question":"その意味で、この運動系介護予防事業とか認知症予防事業、この事業の結果、これだけ介護を受けなくても済むようになったとか、例えば認知症になるのを遅らせることができたとか、進むのを止めたとか、そういう効果的なものがエビデンスとして数字的にそういうものを評価できるようなことというのはできていますかというか、やっていますかというところが１つと、なかなか難しいのかという。","respondent":"川原高齢者地域支援課長","answer":"はつらつ健康チェックというものを行っているのですけれども、その上でそれを集計したデータに基づいて、今の高齢者の方がどういったところに、介護予防の観点でこちらが主に事業として実施しなければいけないかというところを今後検証してまいりたいと考えています。","id":"exchange-163"},{"speaker":"塚本委員","kind":"意見","question":"やはりここでしっかりエビデンスみたいなものが出てくると、これはもっと拡大したほうがいいのだ、もっとやっていけるのだということで、いろいろな意味でこの予算の拡充等にもつながっていく、事業の拡大につながっていくということになると思いますので、ぜひそこら辺の効果検証ということをしっかり今後取り組んでいただいて、この予防事業をより拡充できる方向でというふうにお願いをして終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-164"},{"speaker":"鈴木（真）委員","kind":"確認","question":"私は民生費の１項で社会福祉費、障害者関係のところから２２１ページ、八潮南特別養護老人ホーム等増改築、それから２２５ページ、自立生活援助運営費、２３１ページ、障害児者総合支援施設運営費、その点についてお聞きしていきます。最初に、八潮南特別養護老人ホーム。それが今回、急に八潮南で障害者施設、福祉施設というのが出てくるのはどういうわけなのかということで、この点を確認させてください。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"やはり近年の障害の重度化、高齢化、また医療的ケアが必要な方も地域で安心して暮らせる支援体制の整備が必要ということで、この１年ほど検討してきた中で予算を計上させていただいたものになります。障害者支援課のほうには、不安だというお声は現在一つも入ってきておりませんので、丁寧に対応していただいていることと評価をいたします。","id":"exchange-165"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"八潮南のほうは今ピッコロというお話があり、拡充を図っていくのはぜひ進めていただきたいと思います。それから、ぐるっぽのほうです。それがもう出来上がってからずっと残ったまま、現状でもそれがあるということは、やはりプライバシーの問題はありますけれども、カメラの設置等も必要なのではないかと考えるのですが、その辺はどう考えたらいいのでしょうか。","respondent":"松山障害者支援課長","answer":"確かに委員おっしゃるとおり複雑な構造であるため、今後指定管理者と協議しまして、プライバシーに配慮しつつ、安全面の観点から検討していきたいと考えています。","id":"exchange-166"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"さっきピッコロの件で聞き洩らしてしまったのですけれども、これであそこの八潮北の部分が空いていくのか、それともそこはそこで進めたまま定数を増やしていくのか、そこら辺を確認したかったので、増員、現状にプラスなのか、移転するのか、そこら辺を教えてください。それから、ぐるっぽのほう、今カフェレストランというお話もありました。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"ピッコロの件なのですけれども、今回の拡充は２０名程度ということで予定しております。ピッコロの移転かどうかというところなのですけれども、跡地も含めまして、隣接している施設の状況を踏まえて今後検討してまいります。今年度指定管理者のご提案によりまして、作品展と共に土曜日に開けたところ、委員おっしゃった鮫洲運動公園のほうからお客様が流れてきまして、親子連れでカフェレストランが賑わったというような事例もありますので。","id":"exchange-167"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ピッコロの跡地も含めて施策展開を進めていただきたいと思います。それからもう一点ですけれども、自立生活援助運営費助成が３３４万６,０００円。これは新しい予算が出てきて、事項別明細を見ると、その援助を提供する事業者への運営費助成と出ていたのですが、この点について少し教えてください。","respondent":"松山障害者支援課長","answer":"こちらは区内にはない初のサービスでして、精神障害者の方がお一人暮らしをされる場合に、やはり理解力や生活力が十分でないために、一人暮らしの選択をできないという方がいらっしゃいます。その方に対しまして、一定期間巡回して支援するというものです。","id":"exchange-168"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"分かりました。ソレイユというのは精神障害者の関係を随分やっていただいていると思います。ただ、今お話を聞くと、１か所ではなくていろいろなところに生活していらっしゃると思うので、その巡回も大変だと思うのですが、できるだけ区のほうとしてもサポートしていただいて、うまく進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-169","title":"議員研修会の内容と所要時間"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/491981?Template=document&Id=1168#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":123796,"voices":378}}]);
